var T5_INDEX = [["getting-started--open-take-5-for-the-first-time","Open Take 5 for the first time","Getting started","setting-up.html","open take 5 for the first time on a mac (macos 11 or later, intel or apple silicon), open the disk image: it holds take 5, a shortcut to applications, read me first.txt and the take 5 demo song. drag take 5 onto applications. the first time, macos asks you to confirm an app that isn't from the app store: on macos 11 to 14, ctrl control -click take 5 and choose open ; on macos 15 or later, double-click it, click done , then go to system settings > privacy & security and click open anyway . if macos says the app \"is damaged\", read me first has the one line to paste into terminal. on windows (10 or 11, 64-bit), run the installer. it asks whether to install just for you (no administrator password) or for everyone on the computer (needs one), offers a desktop icon, adds take 5 to the start menu, makes song packages (.take5song) and parts (.take5parts) open in take 5, and can start it when it's done. if windows says \"windows protected your pc\", click more info , then run anyway . a newer installer installs over the old version, copying only what changed; if take 5 is open it asks to close it first (take 5 asks about unsaved songs). when take 5 asks to use the microphone (mac), click allow : it can't record without it. if you clicked don't allow, turn take 5 on in system settings > privacy & security > microphone. take 5 opens the song you had open last time. the very first time there's none, so it makes a new one, \"untitled song\", in music/take 5 (a real song folder: keep it or delete it), and a short guided tour starts a second later (see \"take the guided tour\"). if take 5 closed without saving last time, it offers the changes it kept (see \"recover after a crash\"). choose your audio interface or headphones in edit > audio settings... (also on edit > preferences... , ctrl+, cmd+, , page audio). see \"set up an audio interface\"."],["getting-started--update-take-5-check-for-updates","Update Take 5 (Check for Updates)","Getting started","setting-up.html","update take 5 (check for updates) the window's title says which version you have: \"my song - take 5 (v1.0.0)\" (\"(edited)\" after the song's name when there are changes not saved yet). each time take 5 opens, it first asks the internet whether there's a newer take 5 (in the background). if there is, a window says an update is available , with what's new in it (its release notes: what's new, changed and fixed; scroll for more) and two buttons: install now and close (which leaves it for now). help > check for updates... (on the mac, take 5 > check for updates... ) asks any time: with nothing newer the status line says which version is the latest, and without internet the window says it couldn't check. install now downloads it with a progress bar (cancel stops it) and checks it's exactly the file that was published (its size and fingerprint), so a broken or altered download is never run. then: on windows, take 5 closes (asking about unsaved changes first), the installer runs by itself and take 5 opens again, in a minute or so. your songs and settings stay as they were. on the mac, take 5 closes (asking about unsaved changes first), the new take 5 takes the old one's place, wherever it is (applications, your home folder's applications or anywhere else), and opens again. if it can't (the folder can't be written to), the disk image opens in finder with the folder of the one you have beside it: quit take 5, drag the new one over the old and open it. what it did is in update.log in the logs folder (see \"where take 5 keeps things\"). the downloaded installer (a few hundred mb) is deleted the next time take 5 opens, once that version (or a newer one) is the one running. the check when take 5 opens says nothing unless there's a newer version; check for updates at startup , next to it, turns it off. which version you have is in help > about take 5 ( take 5 > about take 5 ), with the build it is (\"take 5 v0.17.1\"). the online cheat sheet and manual (alanone.github.io/takefive) links to the latest under its title (windows installer, mac disk image, all releases)."],["getting-started--take-the-guided-tour-tutorial","Take the guided tour (tutorial)","Getting started","setting-up.html","take the guided tour (tutorial) help > tutorial starts a tour of the basics on the song that's open, in 13 steps. it highlights the real controls one at a time: playing and recording, adding a track, a track's controls, plugins, instrument tracks, writing notes, the mixer, recording takes, saving and exporting, and making take 5 your own. do what a step says (it moves on by itself once it's done), or press next ; on the last step it's finish . back goes to the previous step and skip tour ends it. the tour runs on its own the first time take 5 starts, and help > tutorial opens it again any time a song is open. the keys it mentions follow your chosen key commands set. it's safe on a song you care about: the steps that change something (adding a track, writing notes) can be undone with ctrl+z cmd+z ."],["getting-started--find-where-my-songs-are-saved","Find where my songs are saved","Getting started","setting-up.html","find where my songs are saved each song is a folder of its own in your music folder, under take 5 (music/take 5, music\\take 5 on windows). inside it: the song file, ending in .tracktionedit (open this one); audio : every recording and imported file; backups : earlier saves, one at most every 5 minutes, the newest 20 kept ( file > revert lists them by date); snapshots , if you've saved any, and captures , the nam captures and impulse responses copied into the song; a hidden autosave, written every 2 minutes while there are unsaved changes (not while recording), which brings the work back after a crash. recordings always go into the song's audio folder, so the folder can be copied or moved as a whole, or zipped and sent (or use file > share with bandmates > save song package... ). media > show project folder opens it in finder (explorer on windows). what isn't in the song lives in take 5's settings (~/library/take 5, %appdata%\\take 5 on windows): song and track templates, layouts, macros, your key commands and the audio settings."],["getting-started--start-a-new-song","Start a new song","Getting started","setting-up.html","start a new song file > new project... , ctrl+n cmd+n , asks where to make the song: it starts in music/take 5 with the name \"new song\". type a name and save; take 5 makes a folder by that name (it won't use a folder that already has files in it). a new song starts at 120 bpm in 4/4, with the click on, a one-bar count-in and one audio track. to start from your own setup instead (the band's tracks, inputs, plugins, buses and routing), make a song the way you like it and choose file > save as template... : it keeps everything but the clips. then: edit > preferences... > general > template for new songs picks the one file > new song starts from; none (one audio track) goes back to the plain song. file > new project from template picks any of them for this one song (greyed when you haven't saved one)."],["getting-started--open-a-song","Open a song","Getting started","setting-up.html","open a song file > open... , ctrl+o cmd+o , starts in music/take 5: open a song folder's .tracktionedit file, or a song package (.take5song) a bandmate sent you (it's unpacked into music/take 5 first). file > recent projects lists the songs you've opened, by name (with the folder too when two have the same name; songs that no longer exist are left out; clear menu empties it). take 5 reopens the last song by itself when it starts. if the song open now has unsaved changes, take 5 asks whether to save them first. double-clicking a song or a package in finder (explorer on windows) while take 5 is open opens it in that window, not in a second take 5. if files the song uses have moved, take 5 says how many are missing: find in folder... looks for them in a folder you choose, later opens the song without them (see \"find files a song is missing\")."],["getting-started--pick-up-where-you-left-off-the-start-window","Pick up where you left off (the start window)","Getting started","setting-up.html","pick up where you left off (the start window) when take 5 opens, the start window comes up over the song it reopened ( file > start window... shows it any time): your recent songs, each with when it was saved, its tempo, key and length, and a play button that plays a few seconds of it (from where the playhead was left, or its chorus, or a third of the way in; written when the song is saved, at most every 10 minutes, and when you switch to another song). double-click a song (or select it and click open ) to open it; new song , new from template... and open... are there too, with the audio device in use and audio settings... . untick show this window when take 5 opens (or edit > preferences... > general > start window at launch ) to go straight to the last song. the few seconds are kept in the song's folder, in preview."],["getting-started--open-the-demo-song","Open the demo song","Getting started","setting-up.html","open the demo song the demo song \"take 5 demo\" plays on take 5's own sounds (the amp, the drum machine, the built-in synth), so it needs nothing else installed. it's a folder like any song's: the song, its audio and the drum kit's samples. on the mac, drag the \"take 5 demo\" folder from the disk image into music/take 5 (where open song starts). on windows the installer puts it in music\\take 5\\take 5 demo. installing again doesn't overwrite a demo you've changed, and uninstalling leaves it. then file > open... and open \"take 5 demo.tracktionedit\" inside it. play with it freely: to keep the demo as it came, copy its folder first and change the copy, or don't save."],["getting-started--know-the-parts-of-the-window","Know the parts of the window","Getting started","setting-up.html","know the parts of the window the top bars : the transport, with the click volume and count-in at the left; go to start, play and record; loop, punch and the metronome; the display with bar, beat and tick, time, tempo and time signature; the output loudness meter at the right. in the console layout a toolbar, a status line and an info line come under it (see \"work in the console layout\"), and any layout can have them (see \"arrange the top bars\"). in a window too narrow for a row, what doesn't fit goes onto a line under it. track headers (left): name, input, r (arm), m (mute), s (solo), the headphones (monitoring), a (automation), the fader, pan, meter and plugin slots. the ruler and the lanes above the tracks: tempo, sections, chords, lyrics and the reference track. each lane's header (in the track headers' column) shows what it says at the playhead: the time signature and tempo, the section, the chord. hover a header and click its x to hide the lane; project > tempo track ( g ), marker track ( shift+g ), chord track ( alt+g option+g ) and reference track lane ( alt+shift+g shift+option+g ) show and hide them. a lane with nothing in it yet says how to fill it (double-click the empty reference lane to choose a reference track). the tracks with their clips; below or instead of them, the mixer and the midi editor or pitch editor . side panels on the right: the shortcuts, the audio file browser, notes, the assistant, the test checklist, smart controls, modulators and cpu use ( window > panels ). the inspector on the left ( i ): the selected track's and clip's settings (see \"see a track's settings in the inspector\"). the status line at the bottom: at the left, what just happened and hints; at the right, the audio driver and interface, the sample rate, the buffer size (and the delay it makes), the inputs and outputs, and how much of the computer's time the song's audio takes (cpu). click the right half to see which tracks and plugins use the most (see \"find what's eating the cpu\")."],["getting-started--find-any-command-or-shortcut","Find any command or shortcut","Getting started","setting-up.html","find any command or shortcut the menu bar is file, edit, project, audio, midi, score, media, transport, studio, window and help (since 1.0, the console layout's in every layout): the commands used most at the top level and the rest in submenus by kind: edit > functions , edit > tools and edit > zoom ; file > export ; project > add track , project > group and project > automation ; transport > set project cursor position ; studio > reference track ; window > panels , window > windows , window > top bars and window > layouts ; take 5's own settings in edit > preferences... . every command keeps its key wherever it is, and a command renamed in 1.0 is still found by its old name (the command palette shows it beside the new one). window > command palette... , ctrl+shift+p shift+cmd+p : type part of a command's name, the first letters of its words (\"nit\" finds new instrument track) or words from what it does; up/down and return run one, esc closes it. each row shows the command's key, so it's also a way to learn them. commands you've run come first (until take 5 quits); ones that can't run right now are dimmed. a slip in the typing still finds it (\"mxier\", \"metronme\"), and so do its letters in order (\"mxr\"). when no command matches, it suggests the nearest (\"did you mean...\") and up to four of the guide's tasks about what you typed (\"tone3000\" finds the nam captures task), which open in the online manual. it finds commands, not the choices in a list: for a theme, a layout, a display size or a recent song, use its menu. window > panels > shortcuts , ctrl+/ cmd+/ , also in the help menu: the cheat sheet beside the tracks, with every key and every mouse gesture, grouped by area. it follows your key commands set. hover over any button for a tooltip; a button that runs a command with a key names the key, as it's set now (edit > key commands... changes it)."],["getting-started--bring-a-song-over-from-another-daw","Bring a song over from another DAW","Getting started","setting-up.html","bring a song over from another daw file > import project from another daw... opens an .rpp project, an .als set, a dawproject file (.dawproject, the open format many music apps write), an aaf session (.aaf, which most music apps and video editors can export) or a folder of stems and midi files, as a new song, made in music/take 5 under the original's name. tracks, folders, names, volume, pan, mute, colours, audio clips (copied into the song) and midi come over, plus the starting tempo and time signature. plugins, sends and tempo changes don't, nor automation (except from an aaf; see \"import an aaf session\"). when it's done, a report says what came in and what didn't. things to know: other apps' own project files (.logicx, .ptx, .cpr, .flp, .song, .bwproject and the like) can't be read: take 5 says what to export instead when you choose one (an aaf, a dawproject file, or stems and midi). omf isn't supported: export aaf instead. from an .als set, warped clips come in at their original speed and looped clips play once; return tracks aren't brought over. from an .rpp project, items that were muted come in playing: mute them again. a folder of stems has no tempo in it: set the song's tempo before editing to the grid. while it imports, a window says which file it's copying into the song (a session's audio can be gigabytes, so it can take a while), and stays until the new song is open."],["getting-started--import-an-aaf-session","Import an AAF session","Getting started","setting-up.html","import an aaf session in the other app, export the session or timeline as aaf (choosing aaf where it offers aaf or omf, with the audio embedded or next to the .aaf). in take 5, file > import project from another daw... and pick the .aaf. clips land where they were, with their fades, crossfades, clip gain and clip volume envelopes, track volume and pan (automation too, in the track's lanes), mute, solo and markers. if the session started at a timecode (01:00:00:00, say), the song keeps it: an aaf exported from the song starts there too, so it lines up again in the editor (the video window's timecode... shows or changes it). if the audio isn't next to the aaf, take 5 asks for the folder it's in; for mxf audio, choose the \"mediafiles\" folder on the drive it was recorded to (the mxf audio is converted to wav files in the song's audio folder). the import report lists anything missing."],["audio-and-midi-setup--set-up-an-audio-interface","Set up an audio interface","Audio and MIDI setup","setting-up.html","set up an audio interface connect the interface (and install its driver, if it has one) before opening take 5. open edit > audio settings... (or edit > preferences... , ctrl+, cmd+, , page audio). choose the driver and the interface: - on the mac there's one driver (core audio): choose the interface as the output and the input . they can be different devices (the interface's inputs, the mac's speakers), but one device for both keeps them in time. - on windows, choose the audio device type first: asio for most interfaces (see \"use asio on windows\"), else one of the windows audio types. with asio there's one device list for both. tick the input channels you'll record from ( active input channels ) and the output channels you'll listen on ( active output channels ). only ticked channels show up in take 5: an unticked input isn't in the tracks' input menus. pick the sample rate and the audio buffer size (see \"choose a sample rate\" and \"choose a buffer size\"). test plays a short tone (440 hz, a second, at half level) on the active outputs: turn your speakers or headphones down first. the meter next to the input shows its level: make a sound and check it moves. the interface's name shows at the right end of the status line. each ticked input appears in the tracks' input menus; inputs are mono, one per track, unless you make a pair one stereo input (see \"record a stereo source on one track\"). settings are remembered between launches. if the interface is unplugged while take 5 is open, the sound moves to the computer's own output (in the console layout the status line turns amber); plug it back in and choose it again here. there's nothing to set for midi: take 5 listens to every midi keyboard it finds (see \"connect a midi keyboard\"). on the mac, bluetooth midi... at the bottom pairs a bluetooth one."],["audio-and-midi-setup--choose-a-sample-rate","Choose a sample rate","Audio and MIDI setup","setting-up.html","choose a sample rate the sample rate (how many times a second the sound is measured) is set in edit > audio settings... , from the rates the interface offers. 44.1 khz or 48 khz is right for most music: 48 khz is the usual one for video and most interfaces, 44.1 khz the cd's. higher rates (88.2, 96 khz) take more cpu and disk for little you can hear. choose it before recording a song, so every take is at the same rate: a recording made at another rate still plays at the right pitch, but is converted as it plays. exports offer 44.1, 48, 88.2 or 96 khz, starting at the interface's rate."],["audio-and-midi-setup--choose-a-buffer-size-latency-vs-dropouts","Choose a buffer size (latency vs dropouts)","Audio and MIDI setup","setting-up.html","choose a buffer size (latency vs dropouts) the buffer size in edit > audio settings... decides how long the sound takes to get through the computer: the list shows each size with the delay it makes (\"128 samples (2.7 ms)\"). smaller is quicker (better for playing through an amp sim or monitoring a vocal) but works the computer harder; too small gives crackles and dropouts. 128 samples is a good start for recording, 64 or 32 on a fast computer with a good interface; raise it to 512 or 1024 for mixing a big song with lots of plugins. if you hear crackles, raise it one step. on the mac the choices are powers of two (32, 64, 128...), 512 at first; with asio they come from the interface's driver, often set in its own control panel . while recording, transport > low-latency mode helps too (see \"play through plugins with less delay\")."],["audio-and-midi-setup--use-asio-on-windows","Use ASIO on Windows","Audio and MIDI setup","setting-up.html","use asio on windows for the lowest latency on windows, choose asio as the audio device type in settings > audio settings... and your interface's asio driver as the device (it's usually named after the interface, ending in \"asio\"). the interface's own control panel (buffer size and so on) opens from the control panel button there, and reset device restarts it if it stops making sound. asio is built into take 5: nothing extra to install but the interface's own driver. without one, the windows types work with any sound card: windows audio (shared with other apps, about 10 ms), windows audio (low latency mode) , windows audio (exclusive mode) (lower, but no other app can play while take 5 has it) and directsound (the oldest, the slowest). on a typical usb interface, asio at 64 or 128 samples plays without dropouts."],["audio-and-midi-setup--measure-recording-latency-so-takes-line-up","Measure recording latency so takes line up","Audio and MIDI setup","setting-up.html","measure recording latency so takes line up take 5 moves every recording earlier by the delay the interface reports, so takes line up with what you played along to. some interfaces report it wrongly, and a take then sits a few milliseconds late. to correct it exactly: connect a cable from an output of the interface straight to an input. turn monitors, amps and headphones down: the measurement plays clicks out of that output. studio > recording latency... : choose that output ( out of ) and input ( back in on ). under them it says what's applied now: \"not measured: going by what the interface reports\", or the correction measured before. press measure : a short burst of clicks plays and take 5 listens for a second and a half. it shows the round trip and how much more it is than the interface reports, and applies that. the correction is kept for that input (by its name) between launches. measure each input you record from, and again after changing the interface or its driver. if nothing comes back, check the cable, the levels and that both channels are ticked in audio settings (measure is greyed while no input or output is on)."],["audio-and-midi-setup--connect-a-midi-keyboard","Connect a MIDI keyboard","Audio and MIDI setup","setting-up.html","connect a midi keyboard plug in the keyboard (usb, or through the interface's midi in). take 5 finds it by itself within a few seconds, even while it's open, and listens to every midi input it finds: there's nothing to tick. a bluetooth keyboard pairs from bluetooth midi... at the bottom of edit > audio settings... . add an instrument track ( project > add track > instrument... , ctrl+alt+s option+cmd+s ) and choose an instrument from the menu. instrument tracks listen to \"all midi ins\", so any connected keyboard plays them. arm the track (its r button) to play it live and record it. no keyboard? use studio > on-screen keyboard ( alt+k option+k ) to play from the computer keyboard: the letters play notes, z and x change the octave, c and v the velocity, and tab holds the sustain. if a keyboard plays some notes twice, see edit > preferences... > midi > ignore notes sent twice by (\"my keyboard plays some notes twice\")."],["audio-and-midi-setup--send-midi-clock-to-a-drum-machine-or-another-app","Send MIDI clock to a drum machine or another app","Audio and MIDI setup","setting-up.html","send midi clock to a drum machine or another app edit > preferences... > midi > send midi clock to lists your midi outputs: tick one and it follows take 5's tempo and start/stop (a drum machine plays along in time, an arpeggiator or another app keeps the tempo). tick it again to stop sending. the choice is kept for that output between launches. the option is greyed out when no midi output is connected: plug in the device (or start the other app's virtual midi port: the iac driver in the mac's audio midi setup; on windows, a tool such as loopmidi) and open the menu again. it shows up within a few seconds."],["audio-and-midi-setup--use-bluetooth-headphones-mac","Use Bluetooth headphones (Mac)","Audio and MIDI setup","setting-up.html","use bluetooth headphones (mac) bluetooth headphones are fine for listening but lag too much for recording. opening a bluetooth headset's microphone switches them to a low-quality call mode, so when the output and input are the same bluetooth headset, take 5 records from the mac's built-in microphone instead (or another input if there's none) and the headphones stay in music mode. it does this when take 5 opens and when the headset connects while it's open. for recording, use wired headphones on an interface."],["customising--change-the-look-themes","Change the look (themes)","Customising","setting-up.html","change the look (themes) window > theme : steel (the default since 1.0: neutral near-black greys, cyan highlights, as the console layout's model has them), studio (the default before 1.0, then called \"take 5\": a studio look, near-black, with knobs and fader caps that look made, buttons that light up, slots and fields set into the panel, an lcd in soft green), light , graphite , midnight , slate , stone , charcoal , indigo and ember . light and stone are light; the others are dark. in every dark theme a knob's arc says what it does: amber for level (gain, threshold, drive), blue for time and tone (attack, frequency), teal for blends (mix, width). in every theme a plugin slot's light is green when it's on, red when it's off (bypassed), and amber with a \"!\" if it crashed. everything switches (tracks, mixer, editors, panels, menus, the window's title bar); the song stays open. the theme is remembered between launches and is the same in every layout (a layout doesn't change it). a theme only changes the look: the keys are in edit > key commands... and the arrangement of the window in window > layouts , so the theme, the keys and the layout are three choices."],["customising--make-everything-bigger-or-smaller","Make everything bigger or smaller","Customising","setting-up.html","make everything bigger or smaller window > display size : 90%, 100% (the default), 110%, 125% or 150%. everything scales and stays sharp; remembered after a relaunch. useful on a big screen, from across the room, or for tired eyes. on a small laptop screen 90% fits more tracks and plugin slots. for taller or shorter tracks only, use edit > zoom > zoom in tracks / zoom out tracks , ctrl+↓ cmd+↓ / ctrl+↑ cmd+↑ : in steps of 20 points, between 60 and 280. the track height is kept with the layout."],["customising--use-another-daw-s-shortcuts","Use another DAW's shortcuts","Customising","setting-up.html","use another daw's shortcuts edit > key commands... : under \"key set:\", choose take 5 (the default), classic or set b to set f , other sets of keys people know from elsewhere; the line under it shows the set's main keys (play, record, split, undo), so pick the one you recognise. then change any single shortcut: click + to add a key, click a key to change or remove it. a key another command already has asks first ( re-assign moves it). a note under the list warns when a key is one the system takes first, so it would never reach take 5 (on the mac, command- space for spotlight or control+arrows for spaces; on windows, alt+f4, ctrl+esc and the like). the cheat sheet, tooltips, menus and tutorial follow your keys. classic is take 5's keys from before 1.0 (r records, c loops, x shows the mixer, p the midi editor, k the metronome...): choose it to keep working as before. take 5 is the keys now, the console layout's since 1.0. things to watch: choosing another key set replaces your single changes with that set's keys, and reset to defaults goes back to take 5's keys (after asking; \"key set\" then says take 5). your keys are kept in take 5's settings, for every song."],["customising--arrange-the-screen-layouts-and-panels","Arrange the screen (layouts and panels)","Customising","setting-up.html","arrange the screen (layouts and panels) window > layouts : built-in arrangements (default; browser, the browser on the right and the mixer in place of the tracks; edit and mix, no panels and the midi editor in its own window; compact, like browser with shorter tracks; mixer below; console; browser and mixer; floating windows, the mixer and the editor each in a window; recording, big tracks; mixing, the mixer full size), save current layout... for your own, and delete saved layout . a layout keeps: the side panels open and their order, whether they float or sit side by side, the mixer (shown or not, and where), the midi editor floating or not, which lanes show, the track height, the inspector, the console layout and the top bars' arrangement, the floating windows' places and the sizes of the panes. it doesn't change the theme, the display size or the keys. the default layout opens the shortcuts panel; the console one also turns on window > top bars > console layout , the inspector and the audio file browser. things to watch: choosing a built-in layout also puts its lanes and track height back; saving under a name you've used replaces that layout; delete saved layout doesn't ask first. side panels ( shortcuts , media browser , notes , assistant , test checklist , smart controls , modulators , audio performance , in window > panels ) each open and close on their own key; several open at once stack on the right, one above another (drag the edge between two to share the height). window > windows > side panels side by side puts them in columns; window > windows > side panels in own windows floats them all (or, when they all float, puts them back). esc closes the panel or window you're working in, as its close button would: a side panel (once you've clicked in it, typing in its text box too) or the inspector (editing one of its names, the first esc cancels the edit, the next closes it), a panel in its own window, a plugin's window, the tuner and the other small windows, a dialog. a plugin's own controls may keep esc to themselves: click the window's title bar first. while exporting, esc in the export window cancels. while midi learn waits for a control, esc cancels that instead, in any window; and if you've given esc to a command ( settings > key commands... ), it runs that in a panel's own window rather than closing it. esc doesn't close the window of a song being imported: it stays up until the import is done. window > windows > mixer in place of tracks , mixer in project window and mixer in own window say where the mixer goes; open editors in a window floats the midi editor. drag the edge between panes (tracks and mixer, the editor, the side panels, the track headers' right edge) to resize; double-click an edge for its default size. the track headers are 240 to 600 points wide (300 at first). sizes are kept between launches and in saved layouts."],["customising--arrange-the-top-bars-customize-top-bars","Arrange the top bars (Customize Top Bars)","Customising","setting-up.html","arrange the top bars (customize top bars) the top of the window is made of blocks: the click and count-in, the transport's buttons, loop, punch and metronome, the position display (position, time, tempo, signature), the loudness, and the toolbar's undo and redo, m s l r w a , follow, the tools, snap and grid with q , the output level, the zones, the status line and the info line. put them where you like, in up to four rows: window > top bars > customize top bars... (or right-click an empty part of the bars). each block gets an outline, and a strip under the bars says how. drag a block to move it: let go in the left, middle or right third of a row to put it at that row's left, in its middle or at its right (a line shows where it lands among the blocks there); let go under the last row to start a new row. a row you empty goes. right-click a block to hide it; show a block... brings a hidden one back (at the end of the last row). reset goes back to the layout's own arrangement. done . the arrangement is kept with the layout: save it with window > layouts > save current layout... to have it as a layout of your own. window > top bars > toolbar , status line and info line hide those blocks, or bring them back on a row of their own, in any layout. in a window too narrow for a row, what doesn't fit goes onto a line under it."],["customising--work-in-the-console-layout","Work in the Console layout","Customising","setting-up.html","work in the console layout take 5 opens in it (since 1.0). window > top bars > console layout (or window > layouts > console , which also opens the inspector, the media browser and the mixer below the tracks, at a compact track height of 60) arranges the window around a toolbar and a console-style mixer, with the transport along the bottom and the mixer or editor in a lower zone. choose it again for take 5's other arrangement. the menus, keys, preferences and theme are the same in every layout. the transport runs along the window's foot (the click and count-in, to start, play, record, loop, punch and metronome, the position, time, tempo and signature, the loudness), where take 5's own layout has it at the top. the lower zone : mixer and editor tabs along the foot of the tracks show one or the other under them: the mixer, or the midi editor in its place. opening the editor (double-clicking a clip, or midi > key editor ) and studio > mixer switch them the same way. the media tiles over the audio file browser: instruments (a new instrument track), effects (one added to the selected track), loops & samples (the sample library search), presets (a new track from a track template), file browser (the folders) and favorites (the places). the toolbar , under the transport, across the window. at the left: undo and redo; m (lit when a track is muted: click to unmute them all), s (the same for solos), l (the listen bus), r (every track reads its automation), w (every track writes it, in touch; again, back to read), a (the next track with automation); following the playhead. in the middle: the tools (pointer, marquee, scissors, glue, mute, zoom, draw, play); snapping on or off with its grid; q to quantise. at the right: the output's level and the zones: the inspector, the mixer below the tracks, the side panels. (where the playhead is shows in the transport above.) in a narrow window the middle moves over, and what doesn't fit is left out. the status line under it, in the middle of the window: whether the audio inputs and outputs are connected (amber when not), the listen bus, how long can be recorded on the song's disk, the record format, the pan law and the buffer size. click one to change it (audio settings, the listen bus). the info line under that, across the window in pills like the status line's: the selected clip's name, start, end, length, fades, volume and mute; with no clip selected, the selected track's name, volume, pan, mute and solo; a hint when nothing is. several selected: how many, and the first one's. click a value to type a new one, as in the inspector; click mute or solo to switch it. hide any of these three rows with window > top bars > toolbar , window > top bars > status line and window > top bars > info line ; the tracks get the room. to move their blocks around (or onto the transport's row, or into take 5's own layout), see \"arrange the top bars\". they're kept with the layout. the menus and preferences (every layout's since 1.0): see \"find any command or shortcut\" and edit > preferences... , a window with a page for each kind (editing, editors, general, midi, record, transport, user interface, plug-ins, audio), each setting a switch, a button for its window, or a choice (the click sound, the theme, the template for new songs...). type in the search box at its top left to find a setting on any page by its name or what it does (they're listed under their pages, to change there), and any command with its key ( key commands... to change one). the window stays open while you work; esc closes it. track headers : the track's number, m s, its name and level on top; under them record, monitor, r and w (this track's automation read, or written in touch), e (its settings, in the inspector) and a (its automation lanes), with its plugins (and + to add one) beside them, under the level, and its input too where the track list is wide enough; on a taller track, a picture of what it is with the input and plugins beside it; the meter down the right edge. the mixer : under each name a routing section (its input and output); pre , the channel's input stage: ø (polarity), its input gain (-24 to +24 db) and a low cut (20 hz to 2 khz) and a high cut (1 to 20 khz), 12 db an octave, each switched on with lc or hc , before any plugin; then inserts and sends , each with a switch that turns all of them on or off at once and, for the inserts, the delay their plugins add (in ms); pan and width as bars, lit from the centre (pan) or from 100% (width) out to where they're set; e beside m and s; the name plates grey, the track's colour in the band along the strip's top. the mixer's title bar has configurations (save how the mixer looks under a name, and recall it), racks (which of routing, pre, inserts and sends the strips show), narrow / wide strips (more fit when narrow), q-link (lit: moving a fader, pan, mute or send on one of the selected channels moves the others too, as studio > link selected channels ), and m and s to unmute and unsolo everything."],["customising--run-several-commands-from-one-key-macros","Run several commands from one key (macros)","Customising","setting-up.html","run several commands from one key (macros) studio > macros... : new makes one (\"prepare a vocal track\"), rename... and delete change the list. with a macro chosen, add a command... adds any command to it (from a list by menu: new track, arm track, input monitoring, channel strip...), in order; move up , move down and remove change its order, run tries it. set key... opens key commands , where the macros are under macros : give it a key there. then the key (or studio > run macro , greyed until there's a macro) runs its commands one after another. a command that can't run at that moment (arm track with no track selected, say) is skipped, and the status line says how many of them ran. a macro can't run another macro. macros are kept in the app's settings, for every song."],["customising--make-stop-go-back-to-where-i-started-playing","Make stop go back to where I started playing","Customising","setting-up.html","make stop go back to where i started playing edit > preferences... > transport > return to start position on stop : when on, stopping puts the playhead back where playing started; off (the default), it stays where it stopped. transport > to project start , home or num ., always goes to the start. handy for playing the same passage again and again while mixing or rehearsing a part. after a scrub (playing while you drag the playhead), stop leaves it where it is. the setting is kept between launches."],["recording--record-a-guitar-or-vocal","Record a guitar or vocal","Recording","recording.html","record a guitar or vocal choose your interface in edit > audio settings... . add an audio track ( + track ). it takes the first input no other track uses; pick another from the input menu in its header. an input feeds one track at a time: choosing it on a track takes it off the one that had it. arm it with its r button. its meter now shows the input level: play as loud as you will and check it stays clear of the top. too hot clips the recording for good, so set the level on the interface's gain knob, not the track's fader (the fader changes what you hear, not what's recorded). turn the click on ( c , or the metronome button) and choose a count-in in the transport bar. a new song starts with both on: the click, and a count-in of one bar. press num * (or the record button; r on a mac) to record, and space (or num * again) to stop. the waveform draws as you record. the take is a 24-bit wav file at the interface's sample rate, named after the track (\"vocal_take_3.wav\"), in the song's audio folder, and the song is saved after each take: the status line says \"take recorded and saved\" (or what went wrong). recording over an old take replaces it where they overlap, but the old one is kept as a take (see \"comp the best parts of several takes\"); midi on an instrument track works the same way. recording over a clip that wasn't recorded (an imported file, or notes you drew) cuts it where they overlap, and only undo brings that part back. if the song has lyrics, the lyrics prompter opens when recording starts. in the console layout the status line shows the record format and how long you can record on the song's disk."],["recording--hear-myself-while-recording-input-monitoring","Hear myself while recording (input monitoring)","Recording","recording.html","hear myself while recording (input monitoring) the headphones button in a track's header sets input monitoring. click it to go through auto (you hear the input while the track is armed, playing or stopped), on (always) and off (never, for when the interface's own direct monitoring is on; the button is drawn faint). with monitoring on, the input goes through the track's plugins, so you can play through an amp sim. if what you hear is delayed, lower the buffer size or turn on transport > low-latency mode . monitoring belongs to the input, not the track: it goes with the input to another track and to other songs, and is kept between launches. the button is greyed out while the track has no input. hearing yourself twice, with a slight echo? direct monitoring on the interface is on too: turn one of them off."],["recording--record-several-inputs-at-once-a-band","Record several inputs at once (a band)","Recording","recording.html","record several inputs at once (a band) tick all the inputs in edit > audio settings... , then project > add track > tracks for unused inputs to get a track for each, or set each track's input by hand. arm them all: shift -click an r arms the selected tracks too (and disarms them, when it disarms), ctrl cmd -click arms every track, and project > arm all tracks / disarm all tracks do it from the menu (tracks without an input, and buses, are left out). press r : each input records onto its own track, all starting at the same moment, so they stay in time with each other."],["recording--record-a-stereo-source-on-one-track-stereo-inputs","Record a stereo source on one track (stereo inputs)","Recording","recording.html","record a stereo source on one track (stereo inputs) inputs are mono, one per track, which suits guitars and mics. for something stereo (an amp modeller's two outputs, keys, a pair of overheads), open an audio track's input menu and choose make input 1 + input 2 one stereo input (or 3 + 4, and so on: always an odd one and the next, never 2 + 3): the pair becomes one input, \"input 1 + 2\", that track records from it, and its takes are stereo files. make input 1 + 2 two mono inputs in the same menu splits it again. the pairs are a setting of this computer, as the inputs are the interface's: a pair made stereo is stereo in every song, and another track that was on input 1 or 2 has no input afterwards (the status line says which)."],["recording--use-the-metronome-and-count-in","Use the metronome and count-in","Recording","recording.html","use the metronome and count-in transport > activate metronome , c , or the metronome button (in the transport, beside loop and punch) turns the click on or off. the click slider at the left of the bar is its volume (it goes quiet but never silent: turn the click off for that). count-in (beside the click slider): no count-in, 1 beat, 2 beats, 1 bar or 2 bars of clicks before recording starts (a bar as the song's first time signature has it). it plays only when you record from stopped: pressing r while playing starts recording at once. transport > click sound : classic (the default), woodblock, beep, cowbell, hi-hat, claves, side stick, tambourine or shaker; the first beat of the bar is higher or louder. the sound is the same in every song. transport > click only when recording : no click on playback. transport > click output : send the click to another output (for example only the drummer's headphones) instead of the main outputs . the click's volume, output and click only when recording are kept with the song. the click is never in an export."],["recording--punch-in-to-fix-a-part","Punch in to fix a part","Recording","recording.html","punch in to fix a part drag in the ruler over the part to fix: that sets the punch (and loop) range, drawn in the ruler. the drag doesn't snap to the grid. turn on the punch button (red) in the transport bar. loop and punch can't be on together, so turning one on turns the other off. arm the track, start playing before the range and press num * (or start recording early): only the punched part is replaced; the rest of the old take stays, and the replaced part is kept as a take. transport > pre-roll (off, 1 bar, 2 bars) starts recording that many bars before the punch-in, wherever the playhead is, so you can play yourself in (a count-in plays before that). without pre-roll, recording from past the range starts a second before the punch-in. the pre-roll is kept with the song."],["recording--record-several-takes-in-a-loop","Record several takes in a loop","Recording","recording.html","record several takes in a loop drag in the ruler to set a range (longer than 2 seconds: a shorter one doesn't record), turn on looping with transport > cycle , num /, or the loop button, arm the track and record. recording always starts from the start of the loop. each pass becomes a take of its own, on audio and instrument tracks alike (on an instrument track, a pass you played nothing in isn't kept); stop when you have enough. while it records, the track's own clips go on playing. the track plays the last complete pass (a pass you stopped part way through is kept as a take too), and its takes button shows them all for comping. transport > locators to selection , p , loops over the selected clips or a marquee range instead (and turns punch off)."],["recording--keep-something-i-played-without-recording-capture-recording","Keep something I played without recording (Capture Recording)","Recording","recording.html","keep something i played without recording (capture recording) take 5 keeps what you play even when not recording: a midi keyboard's notes, and the last minute of every input a track in the song uses. select the track and choose transport > retrospective record , shift+num * : it appears as a clip named \"captured\". on an instrument track you get the notes (not the sustain pedal or other controllers); on an audio track, what came in on its input: the last performance, from after its last pause of 4 seconds or more, saved in the song's audio folder (it isn't a take). played along with the song, it lands where you played it (for a loop, the last pass); played while stopped, it goes at the playhead with your timing. it replaces whatever is under it on the track. with no track selected, it goes on the armed track (an instrument track first), or the first instrument track for notes. undo takes it away."],["recording--play-through-plugins-with-less-delay-low-latency-mode","Play through plugins with less delay (low-latency mode)","Recording","recording.html","play through plugins with less delay (low-latency mode) some plugins delay the sound to do their work (look-ahead limiters, linear-phase eqs and the like), and take 5 delays everything else to match, so playing through them feels late. transport > low-latency mode switches off (bypasses) every plugin on the tracks and the master that delays the sound by more than 3 ms, so what you hear while playing is immediate; the status line says how many. turn it off again to bring exactly those plugins back. it's kept with the song, so turn it off before mixing: while it's on, those plugins stay off for playback. an export always has every plugin on, low-latency mode or not (its message says so). plugins you add while it's on aren't switched off, and one you switch on or off yourself while it's on stays as you left it."],["recording--tune-my-guitar-or-bass","Tune my guitar or bass","Recording","recording.html","tune my guitar or bass studio > tuner , alt+t option+t , or right-click an audio track > tuner... to tune on that track's input. choose the input (its meter shows it's hearing you), the instrument (guitar, 7-string guitar, 8-string guitar, bass, 5-string bass, 6-string bass, or chromatic for anything) and a tuning (standard, half or whole step down, drop d, c#, c or b, dadgad, open d, e, g or c, and the 7- and 8-string and bass ones: drop a, drop e, bass drop d, bead, high c...). play a string: the string is found by itself (or click one to tune only it; auto goes back to finding it), its note and cents show, and the pill says tune up , tune down or in tune (within a cent); a string gets a tick once it's stayed in tune for half a second. needle or strobe switch the view: the strobe turns one way when the string is sharp and the other when it's flat, faster the further out, and stands still when it's in tune, which shows the last cent better than the needle. capo (0 to 12 frets) and a reference pitch other than a = 440 hz (415 to 466) are at the bottom; new tuning... in the tuning list takes your own as notes (\"d a d g b e\"), and delete this tuning removes one. mute speakers silences the song while tuning, until the tuner closes. the input, view and your tunings are kept between launches."],["recording--reamp-a-di-through-a-real-amp","Reamp a DI through a real amp","Recording","recording.html","reamp a di through a real amp record a clean di first, then play it out to a real amp later and record the amp: right-click the di track > reamp... . choose the output your reamp box is on (it starts on the di track's output) and the input the amp's mic comes back in on. press measure once (with the amp turned down, or a cable from the output straight to the input): it measures how late the sound comes back, as studio > recording latency... does, and keeps that for the input on this computer. set up reamp : the di track's output goes to the reamp output (so it leaves the main mix), and a \"<track> reamp\" track appears under it, armed on the mic's input. record it: the reamped take lines up with the di to the sample. for pedals or outboard gear on a track as it plays, use the hardware insert built-in effect instead."],["recording--make-a-headphone-mix-for-each-player-cue-mixes","Make a headphone mix for each player (cue mixes)","Recording","recording.html","make a headphone mix for each player (cue mixes) turn on more outputs in edit > audio settings... (for example outputs 3 and 4 for a headphone amp). project > add track > cue mix... makes a mix for one player on an output of its own: give it a name (\"cue: drums\" to start with) and an output. it starts like the main mix (each track's send at its fader level) and is fed by pre-fader sends (marked \"pre\" in the mixer), so its levels change without touching the main mix, and the main mix's faders don't change it. turn up what a player wants more of (\"more me\") on that cue mix's sends. only the tracks there when it's made get a send: give a track added later one with its + send . to send the click to only that output, use transport > click output ."],["recording--talk-to-the-band-in-their-headphones-talkback","Talk to the band in their headphones (talkback)","Recording","recording.html","talk to the band in their headphones (talkback) set up a mic at the computer once: transport > talkback settings... has the mic it's on (its meter shows it's the right one) and its level in the headphones (-40 to +12 db; double-click for 0 db). then transport > talkback , y , talk in that window or on the mixer's master strip turns it on until you press it again: the mic goes into every cue mix (headphone mix), never the speakers, the song or an export. while recording it's turned down 20 db, so a word during a take doesn't drown the players (the button says so). it needs cue mixes on outputs of their own (see \"make a headphone mix for each player\"), not shared with the main outputs; the window says which ones it reaches. the mic and level are kept for this computer; talkback itself starts off."],["takes-and-comping--see-all-the-takes-on-a-track","See all the takes on a track","Takes and comping","recording.html","see all the takes on a track once a track has a recording, its header gets a takes button with the number of takes (\"takes 3\"). click it to show or hide the take lanes under the track: each take (\"take 1\", \"take 2\"...) on its own lane, wherever on the track it was recorded, the parts used in the comp shown bright. midi recordings get take lanes too, shown as notes. whether a track's lanes show is kept with the song."],["takes-and-comping--comp-the-best-parts-of-several-takes","Comp the best parts of several takes","Takes and comping","recording.html","comp the best parts of several takes show the take lanes with the track's takes button. drag across a take lane over the part you like: that part of that take goes into the track (the comp). the drag snaps to the grid; hold ctrl cmd while dragging to ignore it. click a take lane to use the whole take. do this for each phrase until the comp is right; each choice is undoable. comped pieces are ordinary clips with short crossfades (10 ms; none between midi pieces), so you can trim or fade them like any other clip. moving all of a comp's clips, even to another track, moves the takes with them. on tracks in an edit group (a drum kit's mics), choosing a take on one chooses it on all of them, so the kit stays in phase."],["takes-and-comping--delete-a-take-i-don-t-want","Delete a take I don't want","Takes and comping","recording.html","delete a take i don't want hover over a take's name in the take lanes and click its x, or right-click the take > delete take (and the comp's pieces of it) . right-click > use whole take puts all of it in the comp. deleting a take also removes the pieces of it that were in the comp, so check the comp afterwards. ctrl+z cmd+z brings it back. the take's file stays in the song's audio folder ( file > clean up unused audio... removes files nothing uses)."],["takes-and-comping--turn-a-comp-into-one-clip-flatten-comp","Turn a comp into one clip (Flatten Comp)","Takes and comping","recording.html","turn a comp into one clip (flatten comp) right-click the track > flatten comp (greyed until the track has two or more clips): everything on the track, from its first clip's start to its last clip's end, becomes one clip named \"comp\" that sounds the same, its audio a new file (\"<track> comp.wav\") in the song's audio folder. the track's plugins and fader stay on the track. the takes are still there to comp again, and ctrl+z cmd+z puts the comp back. for midi, the comped clips are merged into one."],["takes-and-comping--put-each-take-on-its-own-track-takes-to-tracks","Put each take on its own track (Takes to Tracks)","Takes and comping","recording.html","put each take on its own track (takes to tracks) right-click a track with two or more takes > takes to tracks : a copy of the track for each take appears under it (\"<track> - take 2\"), with the same plugins and fader but no input, each playing its take. the original keeps its comp. useful for doubling a part, or comparing takes in the mixer."],["takes-and-comping--tidy-midi-takes-automatically-after-recording","Tidy MIDI takes automatically after recording","Takes and comping","recording.html","tidy midi takes automatically after recording midi > align midi takes after recording (off at first) gives each midi take a gentle quantise as soon as it's recorded, keeping the feel: notes close to the grid move 60% of the way to it (the snap grid, with its swing or groove; 1/64 with snapping off), the rest stay, and lengths don't change. each pass is tidied before it's kept as a take, so choosing a take again from its lane gives the tidied notes too. the setting is saved with the song. turn it off to keep takes exactly as played. to tidy a part by hand later, open it in the midi editor and use midi > align notes or the quantise button."],["tracks--add-an-audio-track","Add an audio track","Tracks","tracks-and-arranging.html","add an audio track click + track at the top of the track headers (beside the feel and snap boxes), or project > add track > audio , ctrl+alt+n option+cmd+n . an audio track records from one input (a guitar, a mic) or holds audio files. the new track goes at the end, named \"audio 1\", \"audio 2\"..., with the next colour, and takes the first input no other track uses (or none: pick one in its input menu). project > add track > tracks for unused inputs adds a track for every input that hasn't got one, for recording a band. adding a track is one undo step."],["tracks--rename-colour-reorder-or-delete-tracks","Rename, colour, reorder or delete tracks","Tracks","tracks-and-arranging.html","rename, colour, reorder or delete tracks rename: double-click the track's name (or right-click the header > rename ). colour: right-click the header > colour , one of eleven (blue first, grey last). project > colorize by instrument colours every track, and gives it a picture, from what its name says it is (kick, bass, vocal...). reorder: drag a header up or down; a line shows where it goes. several selected tracks move together. the same works in the mixer, dragging a strip by its name. delete: right-click the header > delete track , or select tracks and press delete. deleting and moving are each one undo step. select tracks: click a header; shift -click or ctrl cmd -click adds or removes tracks. a right-click acts on the selected tracks when the one you click is among them, else on that one alone. height: edit > zoom > zoom in tracks / zoom out tracks , ctrl+↓ cmd+↓ / ctrl+↑ cmd+↑ : all tracks, in steps of 20 points, between 60 and 280."],["tracks--group-tracks-into-a-folder-a-drum-bus","Group tracks into a folder (a drum bus)","Tracks","tracks-and-arranging.html","group tracks into a folder (a drum bus) select the tracks and choose project > group > group into folder , ctrl+shift+d shift+cmd+d , or right-click a header > group selected tracks into folder . the folder, named \"folder\", takes the first track's place. a folder is also a group bus: everything inside plays through its fader, pan, mute and plugins (put the drum bus compressor there). click its chevron to collapse or expand it (collapsed, it shows a mini row per track). drag a track onto the middle of a folder's header to put it in, or onto its top or bottom edge to put it above or below. right-click the folder > ungroup folder removes the folder and keeps the tracks where it was. project > group > group into vca is the other kind: a folder whose fader moves its tracks' levels without mixing them through it (see \"move several faders together\"). grouping and ungrouping are one undo step each."],["tracks--copy-tracks-with-all-their-settings","Copy tracks with all their settings","Tracks","tracks-and-arranging.html","copy tracks with all their settings select track headers and edit > copy , ctrl+c cmd+c , then edit > paste , ctrl+v cmd+v : new tracks after the last selected one (in its folder, if it's in one; at the end with none selected), with the same input, plugins and their settings, automation, fader, pan, mute, sends and colour, but no clips. edit > paste tracks with clips , ctrl+shift+v shift+cmd+v , brings the clips too. copying a folder brings its tracks. an input feeds one track at a time, so a copy only gets the input if no other track uses it. each paste is one undo step."],["tracks--save-and-reuse-a-track-setup-track-templates","Save and reuse a track setup (track templates)","Tracks","tracks-and-arranging.html","save and reuse a track setup (track templates) right-click a track's header > save as track template... and name it: its plugins and their settings, automation, fader, sends, colour and input are saved, not its clips (a guitar track with your amp sim, a vocal chain). with several tracks selected (including the one you right-click), or a folder, they're saved together. in any song, project > from track template adds them. templates are kept with take 5, not the song, so every song can use them. for whole-song setups, see \"start songs from a template\"."],["tracks--try-different-versions-of-a-track-alternatives","Try different versions of a track (alternatives)","Tracks","tracks-and-arranging.html","try different versions of a track (alternatives) right-click an audio or instrument track > alternatives keeps several versions of a track's clips to switch between, on the same plugins, settings and automation (only the clips differ): new alternative (empty) starts a blank one (\"alt 2\"...) to record a different part. duplicate as new alternative copies the current clips to edit. picking a name switches to it. the first is \"main\". rename... , and delete this alternative (its clips go with it; greyed for the last one). once a track has two or more, its header shows which one is playing. alternatives are saved with the song and undoable. a bandmate's version of a part arrives as an alternative named after them."],["tracks--show-only-some-tracks-in-a-big-session-hide-tracks-track-sets","Show only some tracks in a big session (hide tracks, track sets)","Tracks","tracks-and-arranging.html","show only some tracks in a big session (hide tracks, track sets) the button at the bottom of the track headers (it says \"all 75 tracks\", or \"14 of 75 tracks shown\", lit while any are hidden) and project > show tracks choose what's shown in the tracks and the mixer: show all tracks brings every one back (also project > show all tracks ). under show only , the sets, each with how many tracks: your own, then ones made from the song: each folder's tracks, and tracks grouped by what their names say they are ( drums : kick, snare, toms, hats, overheads, rooms...; bass , guitars , keys , vocals , and buses and fx ; each only when two or more tracks fit). one click shows just those. show only the selected tracks and hide the selected tracks ; or right-click a track > hide track . save what's shown as a set... names what's shown now (a name you've used replaces that set; \"drums\" of your own wins over the one made from the names); delete a saved set takes one away. hidden tracks still play and are in exports: hiding only tidies the view. what's hidden and your sets are kept in the song; showing and hiding aren't undo steps. hiding a folder hides what's in it; showing a track in a folder shows the folder too."],["tracks--keep-a-track-in-view-while-scrolling-pin-it","Keep a track in view while scrolling (pin it)","Tracks","tracks-and-arranging.html","keep a track in view while scrolling (pin it) right-click a track > pin to the top (stays in view) : it moves above the other tracks, under a line, and stays there while they scroll (a lead vocal while editing the band, a guide track). unpin puts it back in its place. pinning is kept in the song, and isn't an undo step."],["tracks--find-what-s-eating-the-cpu-audio-performance","Find what's eating the CPU (Audio Performance)","Tracks","tracks-and-arranging.html","find what's eating the cpu (audio performance) click the cpu reading at the bottom right of the window, or window > panels > audio performance (f12), and play the song: a window lists each track's share of the audio's time (and the master's), the busiest first, with each of its plugins that uses any under it, and a bar for each (red when one takes a quarter of the time alone). it updates three times a second while playing; nothing is measured while the song is stopped. double-click a plugin to open it; right-click it to bypass it (or turn it back on ), freeze its track or deactivate the track (see below)."],["tracks--free-up-cpu-by-deactivating-or-freezing-a-track","Free up CPU by deactivating or freezing a track","Tracks","tracks-and-arranging.html","free up cpu by deactivating or freezing a track right-click a track > deactivate track : its plugins are unloaded (a plugin running in its own process is closed) and the track is silent, greyed out and left out of exports, its settings kept. activate track brings it back exactly as it was. deactivating a folder takes its tracks with it. undoable. use it for a track you're not using now but want to keep. right-click > freeze : the track's clips are recorded through its plugins as they sound and the plugins switched off; it still plays, from the recording. its fader, pan and sends stay live (move them freely). the header says frozen . if you change its clips or plugins it turns to an amber changed : choose freeze again (it's changed since) . unfreeze brings the plugins back. use it for a finished track with heavy plugins. only audio and instrument tracks freeze; drum channel tracks (and a drum machine split into them) can't."],["tracks--write-notes-for-a-song-or-a-track","Write notes for a song or a track","Tracks","tracks-and-arranging.html","write notes for a song or a track window > panels > notepad , ctrl+alt+p option+cmd+p , opens a side panel with the song's notes (lyrics, ideas, what's left to do) and the selected track's notes (mic, amp settings, which take to keep; the box waits until a track is selected). they're saved with the song as you type (not undo steps)."],["arranging--add-and-name-sections-intro-verse-chorus","Add and name sections (intro, verse, chorus)","Arranging","tracks-and-arranging.html","add and name sections (intro, verse, chorus) sections show in the sections lane under the ruler ( project > marker track , shift+g ). put the playhead where a section starts and choose project > insert marker , insert: the marker goes at the nearest bar, named \"section 1\", \"section 2\"... or right-click the sections lane > add section marker here (on the grid where you clicked). a section runs to the next marker; the last one to the end of the song. with the playhead where a section already starts, the status line says so and nothing is added. double-click a section to rename it, or right-click > name for intro, verse, pre-chorus, chorus, bridge, solo, breakdown or outro ( rename... for your own name, add comment here... for a note at that point). drag a marker's left edge to move it (it snaps to the grid). to jump from section to section, use transport > set project cursor position > locate previous marker / next section , shift+b / shift+n . each kind of section has a colour of its own (the usual names all differ: a bridge never looks like the chorus), and every one of a kind looks the same (\"chorus 2\", \"verse b\" and a \"refrain\" too)."],["arranging--loop-duplicate-or-delete-a-whole-section","Loop, duplicate or delete a whole section","Arranging","tracks-and-arranging.html","loop, duplicate or delete a whole section right-click a section in the sections lane: loop this section sets the loop to it, turns looping on (and punch off) and puts the playhead at its start: for rehearsing or recording takes over just that part. duplicate section repeats it right after itself on every track (a second chorus). delete section (and everything in it) removes it and closes the gap. remove marker only keeps the music and removes the marker. the clips (cut at the section's edges), takes, automation on every track and the master, chords and lyrics go with the music: a duplicated section has its own copy of them, and after a deleted one they move up to close the gap. so do tempo and time-signature changes: a duplicated section starts at its own tempo and changes where it does, and after a deleted one the song goes on at the tempo that played after it. each is one undo step."],["arranging--try-the-song-in-another-order-arranger-chains","Try the song in another order (arranger chains)","Arranging","tracks-and-arranging.html","try the song in another order (arranger chains) project > arranger chains opens a window with the song's sections (from its markers) as buttons: click them in the order you want them played, a section as often as you like (a chorus twice) and leaving out the ones you don't (the bridge cut). the chain shows as a list, each section with its bars and where it starts in the chain: move up , move down , remove and clear change it. play chain plays the song in that order without changing it (the song's playhead jumps along to where each section is in the song; the button turns to stop , and pressing play on the song stops the chain). new , duplicate , rename... and delete manage several chains to compare, and the drop-down switches between them; they're kept in the song, and each change is undoable. a section whose marker you delete drops out of the chains. export as wav... saves a chain's version as a file (in the song's exports, \"<song> - <chain>.wav\" to start with). flatten into song... (after asking) rewrites the song in the chain's order: every track's clips (cut at the sections' edges, with short fades there so the joins don't click), automation, markers, chords and lyrics. sections the chain leaves out are gone; one undo takes it all back. anything before the first marker is the section \"start\". a song that changes tempo or time signature can't use chains yet."],["arranging--insert-bars-of-silence","Insert bars of silence","Arranging","tracks-and-arranging.html","insert bars of silence press 2 for the range tool (or t and choose marquee from the tool menu), drag a range as long as the gap you want, starting where the gap should go, and choose edit > functions > insert silence , ctrl+shift+e shift+cmd+e : everything from the range's start moves later by its length, on the tracks the range covers, their automation too (the gap holds the value it had there); a clip across the start is split there. with nothing selected, the status line says how. over every track, it's the whole song that makes room: the section markers, tempo and time-signature changes, chords, lyrics and takes after it move too. over some tracks, only those tracks move. edit > delete and close gap , shift+backspace , does the opposite: it takes the range out and pulls what's after it back (over every track, the whole song's). one undo step each."],["arranging--set-the-tempo-and-time-signature","Set the tempo and time signature","Arranging","tracks-and-arranging.html","set the tempo and time signature double-click the tempo in the transport bar's display and type a new one (20 to 400 bpm); pick a time signature from the box next to it (2/4, 3/4, 4/4, 5/4, 6/8, 7/8 or 12/8; the tempo lane has more). both change the tempo or signature the playhead is in: the whole song, for a song with no changes, or that stretch of it (to add a change, use the tempo lane). midi stays on its beats; ordinary audio stays where it is in time, so a recording no longer lines up with the bars (audio clips set to follow the tempo are stretched with it). the display always shows the tempo and signature at the playhead. each change is one undo step."],["arranging--tap-the-tempo","Tap the tempo","Arranging","tracks-and-arranging.html","tap the tempo transport > tap tempo , shift+space : tap along at least twice and the tempo the playhead is in is set from your taps (the last eight, averaged). a pause of two seconds starts the count again. a run of taps is one undo step. the first tap only starts the count: the status line says to keep going. to set the tempo by typing, double-click the tempo in the transport bar. for a whole free-time take, see \"fit the tempo to a band take\"."],["arranging--add-tempo-changes-and-ramps-the-tempo-lane","Add tempo changes and ramps (the tempo lane)","Arranging","tracks-and-arranging.html","add tempo changes and ramps (the tempo lane) project > tempo track , ctrl+t cmd+t , shows the lane under the ruler. double-click (or right-click > add tempo change here ) to add a tempo change; it starts at the tempo already playing there. drag a point up or down for the tempo, in whole bpm (shift: tenths), or sideways to move it ( ctrl cmd , ignores the grid); a drag goes one way or the other, as it starts. a change can't be dragged past its neighbours, and the first one (the song's starting tempo) stays at the start. double-click a point, or right-click > set tempo... , to type a tempo; alt option -click it, or right-click > remove this change , to delete it. right-click a point > ramp to next for a smooth speed-up or slow-down to the next change. right-click or double-click the lane's top strip for a time signature from that bar (twelve to choose from), or to remove one."],["arranging--fit-the-tempo-to-a-band-take-played-without-a-click-conduct-tempo","Fit the tempo to a band take played without a click (Conduct Tempo)","Arranging","tracks-and-arranging.html","fit the tempo to a band take played without a click (conduct tempo) choose transport > conduct tempo (choose it again to stop without making anything). play the take from the start and tap shift+space on every beat (or every half bar, or bar), the first tap on a downbeat. stop: say what each tap was (\"each tap was a beat\", half a bar or a bar), then make the tempo ( keep tapping to go on, discard to throw the taps away). it needs two taps or more. the bar lines now fall on the played downbeats, the tempo lane shows the speeding up and slowing down, and the audio hasn't moved, so the click and midi follow the band. the taps are corrected for the interface's delay, and the bars are in the song's starting time signature. one ctrl+z cmd+z undoes it."],["arranging--find-the-tempo-of-a-recording","Find the tempo of a recording","Arranging","tracks-and-arranging.html","find the tempo of a recording right-click an audio clip > detect tempo... : for a loop or a take played to a steady beat (six seconds or more), it suggests a tempo between 60 and 200 bpm, to a tenth of a beat per minute (or says none was found). it hears the beat from where the notes start, and the bar from how they repeat, so strummed eighths don't come out twice as fast; between two that fit equally well it picks the more usual tempo (a song at 70 could come out as 140). choose set song tempo to set the song's starting tempo to it, or clip follows song to stretch the clip to the song's tempo instead. for a band take played without a click, see \"fit the tempo to a band take\"."],["arranging--make-linked-copies-of-a-midi-part-or-an-audio-clip","Make linked copies of a MIDI part or an audio clip","Arranging","tracks-and-arranging.html","make linked copies of a midi part or an audio clip select a clip (midi or audio) and choose edit > functions > duplicate linked , ctrl+alt+r option+cmd+r , or right-click it > duplicate linked : a copy right after it, linked (shown by a link before its name). midi: editing the notes of any copy changes them all. audio (the chorus guitar used three times): a fade, gain, pan, reverse, pitch, warp marker, envelope or clip effect on one is on all of them. each keeps its own place, length, trim, name, colour and mute. right-click one > unlink (it says how many others it's linked to) to vary it on its own. plain duplicate , ctrl+d cmd+d , makes an independent copy."],["editing-audio--select-move-and-copy-clips","Select, move and copy clips","Editing audio","editing-audio.html","select, move and copy clips click a clip to select it; shift -click adds or removes clips. drag across empty lane space to select clips on several tracks (shift adds). drag a clip to move it, also onto another track: an outline shows where it lands. several selected clips move together. the clip's start lands on the grid (a clip that was off the grid jumps onto it); hold ctrl cmd while dragging to ignore the grid. a clip can't go before the start of the song. edit > copy / cut / paste , ctrl+c cmd+c / ctrl+x cmd+x / ctrl+v cmd+v : paste goes at the playhead, on the tracks the clips came from, and replaces what was there. edit > select all , ctrl+a cmd+a , selects every clip. edit > delete , backspace or delete, removes them (selected tracks too). a clip moved over another wins: the one underneath is trimmed back to a 10 ms crossfade (a midi clip cut exactly, with no crossfade), or removed if it's almost all covered."],["editing-audio--split-a-clip","Split a clip","Editing audio","editing-audio.html","split a clip put the playhead where to cut, select the clip and edit > functions > split at cursor , alt+x option+x . or choose the split tool (3, or press t for the tool menu) and click the clip where to cut. with edit > snap to zero crossing on (it is by default, and kept with the song), cuts and trims land where the waveform crosses zero (within 5 ms), so they don't click; each selected clip at its own crossing. clips that are stretched, reversed, looped or pitch-shifted are cut exactly where asked. the two halves meet exactly, with no crossfade. with the scissors, clicking a selected clip cuts all the selected clips there."],["editing-audio--trim-the-start-or-end-of-a-clip","Trim the start or end of a clip","Editing audio","editing-audio.html","trim the start or end of a clip drag a clip's left or right edge. trimming follows the snap grid (hold ctrl cmd , to ignore it) and, with edit > snap to zero crossing on, lands on a zero crossing. trimming only hides audio: drag the edge back out to get it back (as far as the recording goes; a clip can't be shorter than 10 ms). trimmed over a neighbour, the trimmed clip wins and the neighbour is cut back to a 10 ms crossfade. the trim edges are the outer few pixels of a clip (a very narrow clip has none: zoom in). to slide the audio inside a clip without moving the clip, see \"nudge, repeat and slip clips\"."],["editing-audio--add-fades-and-crossfades","Add fades and crossfades","Editing audio","editing-audio.html","add fades and crossfades drag the fade handle at a clip's top-left or top-right corner (just under the name) to fade in or out. right-click the clip > fade in shape / fade out shape : linear, fast (convex), slow (concave) or s-curve; choosing a shape on a clip without a fade gives it a beat-long one (at most a third of the clip). fade drags don't snap, and a clip's fade in and fade out together can't be longer than the clip. only audio clips have fades. fade lengths can also be typed in the inspector ( i ). overlapping clips crossfade by themselves (10 ms; drawn as an x); drag the later clip's fade-in handle at the join to make the crossfade longer: it stays centred on the join, as long as there's audio either side, and the status line shows its length."],["editing-audio--change-a-clip-s-volume-clip-gain-or-normalise-it","Change a clip's volume (clip gain) or normalise it","Editing audio","editing-audio.html","change a clip's volume (clip gain) or normalise it right-click an audio clip > gain : +6, +3, +1, -1, -3 or -6 db, normalise (to -0.1 db) or reset to 0 db (the menu shows the gain now: \"gain (-3.0 db)\"). normalise sets the gain from the loudest sample in the part the clip plays (fades and envelope aside), each selected clip on its own. clip gain goes from -60 to +24 db; type it, or drag it (-24 to +24), in the inspector. the clip's gain shows in its name strip after the name. settings in the clip menu apply to every selected audio clip (midi clips in the selection are left alone)."],["editing-audio--draw-a-volume-or-pan-envelope-on-a-clip","Draw a volume or pan envelope on a clip","Editing audio","editing-audio.html","draw a volume or pan envelope on a clip right-click an audio clip > volume envelope (or pan envelope ): a line over the clip. click the line to add a point, drag points to shape it (the status line shows the value; points don't snap and can't pass their neighbours), alt option -click a point to remove it. volume goes from silence up to +6 db, on a scale like a fader's; pan has left at the top. the envelope moves and copies with the clip. the envelope commands act on the clip you right-click; clear envelopes removes both from every selected clip."],["editing-audio--nudge-repeat-and-slip-clips","Nudge, repeat and slip clips","Editing audio","editing-audio.html","nudge, repeat and slip clips edit > functions > nudge left / nudge right , ctrl+← cmd+← / ctrl+→ cmd+→ : move the selected clips one grid step (10 ms with the grid off); never before the start. their automation goes with them when edit > automation follows events is on. edit > functions > duplicate , ctrl+d cmd+d : a copy of the selection right after it (several clips keep their layout), selected, replacing what's there; press again for more. slip: alt+shift option+shift -drag a clip to move the audio inside it while the clip stays put (not snapped, and only as far as the recording goes). loop: drag the right end of a clip's name strip (its top-right corner) to repeat the clip as a loop, on the grid; right-click > unloop puts it back to one pass."],["editing-audio--use-the-snap-grid-triplets-and-swing","Use the snap grid, triplets and swing","Editing audio","editing-audio.html","use the snap grid, triplets and swing the snap box above the track headers (\"snap: beat\" to start with) sets the grid for moving, trimming and nudging: off, bar, beat, 1/8, 1/16, or the triplets 1/4 t, 1/8 t, 1/16 t. hold ctrl cmd while dragging to ignore it. the feel box next to it is straight , swing 54, 58, 62, 66 or 70% (on the beat, 1/8 and 1/16 grids; bars and triplets don't swing), or a groove from a played part (right-click a midi clip, or an audio clip, > use as groove ; it applies when its grid is the snap grid). snapping and quantising follow the feel. the lines in the tracks (and the ticks in the ruler) are the snap grid's own: a line at every place a drag can land, swing included, bars strongest, then beats, then the steps between them. zoomed out, where they'd crowd together, only the beats are drawn, then only the bars. with the grid off, bars and beats show; on bar, only bars."],["editing-audio--use-the-edit-tools-pointer-marquee-scissors-glue-mute-zoom-draw-play","Use the edit tools (pointer, marquee, scissors, glue, mute, zoom, draw, play)","Editing audio","editing-audio.html","use the edit tools (pointer, marquee, scissors, glue, mute, zoom, draw, play) press t ( edit > tools > tool menu ) to choose what the mouse does in the tracks: select tool , 1 (select, move, trim and fade), range tool , 2 (select a range of time across tracks), scissors tool , 3 (click a clip to split it), glue tool , 4 (click the selected midi clips to join them), mute tool , 7 (click a clip to mute or unmute it; muted clips are dimmed), zoom tool , 6 (click to zoom in there, alt option -click to zoom out, drag across what you want to fill the view), draw tool , 8 (drag across an empty part of an instrument track: a midi clip that long, on the grid) and play tool , 9 (hold the mouse down anywhere in the tracks: it plays from there until you let go, then goes back; not while recording). fade work is an ordinary mouse gesture with the pointer. a tool acts on the clip you click, or on all the selected clips when that one is among them. the glue tool joins midi clips; for audio, use audio > bounce selection ."],["editing-audio--select-a-range-across-tracks-and-edit-it","Select a range across tracks and edit it","Editing audio","editing-audio.html","select a range across tracks and edit it choose the range tool (press t and pick it), then drag across one or more tracks; its edges snap to the grid (hold ctrl cmd , not to). dragging a range deselects any selected clips, so the commands below act on the range alone. its edges cut clips exactly (not at zero crossings). with a range: edit > delete , cut , copy and paste act on just that range. edit > functions > delete time , shift+backspace : remove it and move what's after earlier (the tracks' automation too; over every track, the markers, tempo, chords and lyrics as well). edit > functions > insert silence , ctrl+shift+e shift+cmd+e : push everything from the range's start later by its length (see \"insert bars of silence\"). transport > locators to selection , p : loop it. audio > bounce selection ( ctrl+b control+b ): bounce just that range. file > export > export range as wav... : what each track plays there, with its effects, one file per track. edit > zoom > zoom full , shift+f : fit it in view. drag inside it to move what's in it (clips cut at its edges, and its automation) to another place on the same tracks, snapped to the grid: what was where it lands is replaced, and the automation where it was holds the values either side. hold alt option to copy it instead (a razor edit). drag its right edge to stretch what's in it from its start: audio is time-stretched with its pitch kept (each clip's stretch mode; it stops following the tempo), midi notes spread out (or squeezed together), and the automation with them. longer, it covers what came after on those tracks; shorter (down to 50 ms), it leaves a gap. warped clips are left as they are. each is one undo step. click an empty lane to clear the range."],["editing-audio--delete-so-the-gap-closes-ripple-editing","Delete so the gap closes (ripple editing)","Editing audio","editing-audio.html","delete so the gap closes (ripple editing) turn on edit > ripple edits : deleting (or cutting) clips moves the later clips on the track earlier to close the gap; their automation stays where it is. it's off whenever a song opens. or use edit > functions > delete time , shift+backspace , once, on selected clips or a marquee range (a range takes its automation along)."],["editing-audio--reverse-change-channels-or-export-a-clip","Reverse, change channels or export a clip","Editing audio","editing-audio.html","reverse, change channels or export a clip right-click an audio clip: reverse plays it backwards. channels : stereo, mono (left + right), swap left and right, left only, right only. export as wav... saves the clip as heard (gain, fades, envelope, reversed or warped, its clip effects with their tail), without the track's effects, as a 24-bit wav in the song's exports folder; with several clips selected, a file each in a folder."],["editing-audio--remove-silence-between-phrases-strip-silence","Remove silence between phrases (Strip Silence)","Editing audio","editing-audio.html","remove silence between phrases (strip silence) right-click an audio clip (a vocal, a tom track) > strip silence and choose quiet recordings (-50 db) , normal (-40 db) or loud or noisy (-30 db) : the quiet parts are cut out, leaving a clip for each phrase or hit. gaps shorter than a quarter of a second are kept, and each piece keeps a moment before the sound (10 ms) and after it (80 ms), so nothing is clipped off; there are no fades. the status line says how many clips are left; one undo puts them all back. clips that follow the tempo, play reversed or loop are skipped."],["editing-audio--make-audio-follow-the-song-s-tempo","Make audio follow the song's tempo","Editing audio","editing-audio.html","make audio follow the song's tempo right-click an audio clip (a drum loop, say) > follow tempo : it stretches with the song's tempo and tempo changes, keeping its pitch, and stays locked to the beat. its own tempo is taken to be the song's where it starts; for a loop recorded at another tempo, right-click it > detect tempo... > clip follows song (see \"find the tempo of a recording\"). ordinary audio stays where it is in time when the tempo changes; midi always stays on its beats. right-click it > stretch mode for how it's stretched (following the tempo, warped or pitch shifted): standard (all-round, the default), percussive (the sharpest hits: drums, picked guitar) or smooth (bass, vocals, pads: softer attacks). all three stay on the beat; stretched a long way (half speed, say) hits soften and smear in any of them."],["editing-audio--tighten-the-timing-of-a-drum-take-warp-and-audio-quantise","Tighten the timing of a drum take (warp and audio quantise)","Editing audio","editing-audio.html","tighten the timing of a drum take (warp and audio quantise) select audio clips and press q ( edit > quantize ), or right-click > quantise audio to grid : their hits move all the way to the snap grid (1/16 with the grid off), with its swing or groove; hits less than half a millisecond off stay. finding the hits can take a few seconds on a long clip. midi clips in the selection are left alone (quantise them in the midi editor). on clips in an edit group, q opens quantise group instead (below). for hand edits, right-click > warp (it also turns on follow tempo): click in the clip's top strip to put a marker on the nearest hit, drag to pin the audio there and move it; drag a marker to move it ( ctrl cmd , ignores the grid); alt option -click a marker to remove it. remove warp markers starts over."],["editing-audio--edit-a-multi-mic-drum-kit-as-one-edit-groups","Edit a multi-mic drum kit as one (edit groups)","Editing audio","editing-audio.html","edit a multi-mic drum kit as one (edit groups) select the drum tracks (or their folder) and choose project > group > group for editing , ctrl+shift+g shift+cmd+g . their headers show g1 (g2 for the next group). now clicking a clip on one mic selects the clips at the same time on all of them, so a cut ( alt+x option+x ), move, nudge, delete or quantise does the same to the whole kit; trimming, fading or slipping one clip does the same to the others; a marquee range over one track covers the group; and comping a take on one mic (the takes lanes) comps the same take on the others. edit > edit groups on turns grouping off for a moment (to fix one mic on its own; the badges go faint); project > group > ungroup for editing ends it."],["editing-audio--tighten-a-multi-mic-drum-take-without-phase-problems-quantise-group","Tighten a multi-mic drum take without phase problems (Quantise Group)","Editing audio","editing-audio.html","tighten a multi-mic drum take without phase problems (quantise group) quantising each drum mic on its own moves each by its own hits, so the overheads and rooms drift away from the close mics and the kit sounds smeared. with the kit grouped (above), select a clip on any mic and press q (or edit > quantize group... ); to do only a section, drag a marquee over it first. in the window: tick the tracks to find the hits on: the kick and snare are ticked to start with (the inside kick and top snare mics). move them by : cutting before each hit, crossfading the joins slices every mic 4 ms before each hit and moves the slices, with 6 ms crossfades: the hits stay exactly as played and the mics exactly in phase (the usual choice for drums). warping (stretching between the hits) stretches the audio between the hits instead: no joins, the mics within a millisecond of each other. strength (100%: all the way to the grid) and sensitivity (50% to start; higher finds ghost notes too), both remembered. hits within 30 ms of each other on different mics count as one. it uses the arrange view's grid and feel (swing, groove). one ctrl+z cmd+z puts it all back."],["editing-audio--jump-to-the-next-drum-hit-opt-n","Jump to the next drum hit (Opt+N)","Editing audio","editing-audio.html","jump to the next drum hit (opt+n) transport > set project cursor position > locate next hitpoint , alt+n option+n , moves the playhead to the next hit (transient) on the selected tracks (or on the selected clips' tracks; with nothing selected, any track); alt+b option+b goes back to the one before. handy for cutting at hits ( alt+x option+x , splits there) and checking a quantise."],["editing-audio--slow-down-speed-up-or-transpose-a-clip","Slow down, speed up or transpose a clip","Editing audio","editing-audio.html","slow down, speed up or transpose a clip right-click an audio clip: varispeed (tape: faster is higher) : 50, 67, 75, 80, 90, 95, 100, 105, 110, 125, 133, 150 or 200%, like a tape machine; length and pitch change together. the clip's start stays and its end moves (check it doesn't now run over the next clip), and it stops following the tempo. pitch shift (keeps the length) : -12 to +12 semitones, in the clip's stretch mode. both apply to every selected clip."],["editing-audio--correct-the-pitch-of-a-vocal","Correct the pitch of a vocal","Editing audio","editing-audio.html","correct the pitch of a vocal double-click an audio clip (or right-click > pitch correction... ) to open the pitch editor under the tracks: sung notes as bars and the pitch as a line. tick correct : after a moment the corrected line sits on the notes of the key and the clip plays in tune, the voice still sounding like the singer. choose which notes are in tune ( song key , chromatic or notes i choose ), and set how far notes go ( correction , 100% to start), how quickly ( speed , 0 to 400 ms, 40 to start: 0 is the robotic effect, 100-200 ms keeps vibrato) and how much natural drift stays ( humanise , 30% to start). recorded clips open it; imported ones too. drag a note to send it to another note (hold alt option , to move it in cents); double-click one to leave it as sung. untick correct to hear the original. the controls are down the left of the editor, beside the note names (across its top when it's too small). scroll up and down through the pitches; alt option -scroll shows more or fewer of them, the one under the pointer staying put."],["editing-audio--fix-single-notes-in-the-pitch-editor-split-join-vibrato-timing","Fix single notes in the Pitch editor (split, join, vibrato, timing)","Editing audio","editing-audio.html","fix single notes in the pitch editor (split, join, vibrato, timing) right-click a note in the pitch editor: split the note here (a melisma or run found as one note, tuned to one pitch) or join with the next note (a legato note found as two). octave heard wrong : the note's real pitch is an octave above or below what's shown. vibrato (none, half, as sung, more, or as speed decides), drift (straightened, half, as sung, or as humanise decides) and tilt (a rise or fall through the note, a half or a whole semitone): for that note only, whatever speed and humanise say. formants (bigger or smaller voice, -3 to +3) and level (louder or quieter by 3 or 6 db). leave this note as sung , back to the nearest note in tune , reset this note . to move a note's timing, drag its start or end (the pointer shows arrows), or shift -drag the note to move it whole: it snaps to the grid (hold ctrl cmd , not to). that's written as warp markers on the clip, the audio half a second either side pinned so only the note and the gaps beside it stretch."],["editing-audio--tune-a-screamed-or-gritty-vocal","Tune a screamed or gritty vocal","Editing audio","editing-audio.html","tune a screamed or gritty vocal in the pitch editor's more menu, pitch heard in says how readily pitch is heard: screams left alone hears pitch only in clean singing, so a scream or growl isn't touched (no warbling); clean voice , normal (the default), gritty or breathy voice and rough voice hear it in rougher and rougher singing. to leave one stretch alone (a scream, a spoken line), drag across it in an empty part of the editor and right-click > leave this stretch alone ( correct this stretch again undoes it). leave notes already in tune (flex-tune: off, 10, 20, 30 or 50 cents) leaves notes that close to a note in tune where they are, so only the ones that are off move."],["editing-audio--formants-the-chord-lane-breaths-and-levels-for-a-vocal","Formants, the chord lane, breaths and levels for a vocal","Editing audio","editing-audio.html","formants, the chord lane, breaths and levels for a vocal in the pitch editor's more menu: formants (whole clip) : the whole clip's voice bigger (-) or smaller (+), -4 to +4, without changing its pitch (a double that sounds like another singer). follow the chord lane (chord snap) : each note goes to the nearest note of the chord playing there, not of the key (where the chord lane has chords). breaths and esses : the breaths turned down 6, 10 or 15 db (or breaths 10 db and esses 4 db), as dips in the clip's volume envelope (which you can then adjust). level the notes : quiet notes up and loud ones down, gently (half way) or fully (all to one level) , also in the envelope. correct the track's other clips the same way : a comp's clips with the same settings (not the note-by-note changes). show other tracks behind : the pitch of doubles and harmonies at the same time, faintly, to match them."],["editing-audio--write-lyrics-along-the-song-the-lyrics-lane","Write lyrics along the song (the lyrics lane)","Editing audio","editing-audio.html","write lyrics along the song (the lyrics lane) project > lyrics track shows a lane under the chords. click a line to select it (it lights up); shift -click another to select the lines between, ctrl cmd -click to add or take away one. drag to move the selected lines together (on the grid; hold ctrl cmd , to ignore it). ctrl+c cmd+c , ctrl+x cmd+x and delete copy, cut and delete the selected lines; ctrl+v cmd+v pastes them at the playhead, as far apart as they were (the words go on the system's clipboard too, to paste into a message). right-click for add a line here... , change , copy , cut , paste here , delete , paste lyrics from here... (a whole song's words, a line each, a bar apart, to drag into place after), clear all lyrics , lyrics window... and lyrics prompter . hyphens split a word into its syllables for the lead sheet (\"beau-ti-ful\"). double-click the lane (or project > lyrics lines... ) for the lyrics lines window: every line with where it's sung (bar|beat and the time), the one being sung lit. click a position or the words to type new ones: a position takes a bar (\"17\"), a bar and beat (\"17.3\") or a time (\"1:23.5\") and moves the line there; empty words take the line out. add line puts one where you double-clicked (or a bar after the selected line) with its words ready to type; delete takes the selected lines out; go to puts the playhead on the selected line; paste words... pastes a whole song's words from it. the rows selected there are the lane's selected lines too, so copy and paste work on them. while the song plays, the lane's header shows the first word of the line being sung. project > lyrics prompter shows the words big, for the singer: the line being sung, the next under it, and a bar across for how far through the line the song is. it opens by itself when recording starts if the song has lyrics; put it on a screen the singer can see. on the lead sheet (notation, and the printed and pdf parts) the lyrics go under the first part that isn't drums, a syllable a note. lines transcribed from a vocal (see \"get the lyrics from a recorded vocal\") also know when each word is sung: the lane draws each word where it's sung (when there's room), the prompter's bar goes word by word, and so does the lyrics video's lighting. correcting a word keeps the words' times: a word put right or changed keeps its own, a word added gets one between its neighbours, and a line moved takes them with it. lines copied and pasted, or typed, have none (their words are spread over the line)."],["editing-audio--get-the-lyrics-from-a-recorded-vocal-transcribe-lyrics","Get the lyrics from a recorded vocal (Transcribe Lyrics)","Editing audio","editing-audio.html","get the lyrics from a recorded vocal (transcribe lyrics) rather than type a song's words, have take 5 hear them: right-click the vocal's audio clip > transcribe lyrics... , or select it and choose audio > transcribe lyrics... . in the window: model : standard (141 mb) is quick and good on a clear vocal; better (465 mb) and best (547 mb) get more of a sung vocal's words right (and put each word more exactly where it's sung), taking longer. start with standard; if too many words are wrong, undo and try better. language : find it from the vocal , or choose the language (a short or sung vocal can be taken for the wrong one). nearly a hundred languages. separate the vocal first (the clip has the band in it) : for a mixed song or a live take with one mic, the vocal is taken out of the mix first (as separate stems does, but nothing is added to the song), and only that is listened to. a vocal recorded on its own doesn't need it. replace the lyrics already there (on to start with): the lyrics lane's lines from the first word heard to the last are taken out first. off, they stay and the new lines go between them (a line at the same beat is replaced). click transcribe . the first time, the model is downloaded (from hugging face; with separate the vocal first, the 4-stem separation model too, 84 mb) and kept in the models folder (see \"where take 5 keeps things\"); after that it needs no internet. it runs on the computer and nothing is sent anywhere: a verse takes seconds, a whole song well under a minute with standard on a recent computer, a few minutes with best on an older one. stop stops it, and nothing changes in the song. the words arrive in the lyrics lane (which opens if it was hidden) as one undo step: a line at each phrase (a new one after a pause, or after eight words or so), at the beat its first word is sung, each word at its own time. a line's last full stop or comma is left off; \"[music]\", \"(laughs)\" and the like aren't words and are left out. then check them: double-click the lyrics lane for the lyrics lines window and play the song, its line lit as it's sung, and click the words to put the wrong ones right (each keeps its time). with a sung vocal, expect some words wrong, more where it's quiet, sung low under the band or held long; the times are close to where each word starts (within a tenth of a second with better and best, a little further out with standard). add hyphens for the lead sheet's syllables (\"beau-ti-ful\") as you would for typed lyrics. the assistant can do it too (\"write down the lyrics of this vocal\")."],["editing-audio--make-a-harmony-from-the-lead-vocal","Make a harmony from the lead vocal","Editing audio","editing-audio.html","make a harmony from the lead vocal open the lead's clip in the pitch editor and choose more > make a harmony voice : a third, fifth or sixth above, or a third, fourth or octave below. the notes (as corrected) move that many notes of the key (or the chord, following the chord lane), keeping half the lead's own vibrato so it sounds like a second singer, onto a new track under the lead (\"lead harmony (3rd above)\"). undo takes it away."],["editing-audio--tighten-double-tracked-guitars-or-stacked-vocals-align-to-a-reference-take","Tighten double-tracked guitars or stacked vocals (align to a reference take)","Editing audio","editing-audio.html","tighten double-tracked guitars or stacked vocals (align to a reference take) pick the take the others should follow (usually the tightest). select all the takes ( shift -click them), then right-click the reference > align selected to this clip > tight (100%) , natural (70%) (a little of each player's looseness kept) or loose (40%) . recorded or imported audio clips only. the hits (palm mutes, picked notes, consonants) of each other take are paired with the reference's nearest, within 80 ms, and moved onto them with warp markers; between hits the audio is stretched, with the percussive stretch mode so the attacks stay sharp. a hit with no partner nearby (a note only one take plays) is left where it is. move whole clips (no stretching) only slides each clip by their typical difference, for takes recorded together that are just a little apart. it takes a few seconds per take; one undo takes it all back, and the warp markers can be moved by hand afterwards (see warping above). the clip's name strip says \"warp\" once it's aligned."],["editing-audio--match-a-double-s-pitch-to-the-lead-vocal","Match a double's pitch to the lead vocal","Editing audio","editing-audio.html","match a double's pitch to the lead vocal select the doubles (or gang vocals) and the lead, right-click the lead > match pitch of selected to this clip > tight, natural or loose. each double is pulled toward the lead's pitch moment by moment, wherever they're singing the same note (within two semitones, so a harmony is left alone), keeping its own formants, so it still sounds like a second voice. the double plays a new file in the song's audio folder (\"matched\" on its name strip); right-click it > remove pitch match puts its own audio back. do it after aligning the timing."],["editing-audio--take-out-a-squeak-a-click-hum-or-mouth-clicks-repair","Take out a squeak, a click, hum or mouth clicks (Repair)","Editing audio","editing-audio.html","take out a squeak, a click, hum or mouth clicks (repair) right-click a recorded clip > repair : remove mouth clicks : lip smacks and tongue clicks on a close-miked vocal, found and smoothed over (the voice around them left alone). remove hum (50 hz: europe) / (60 hz: the americas) : mains hum and its harmonics, in narrow notches. spectral repair... : the clip's spectrogram (time across, pitch up, louder brighter). drag a box over the sound to take out (a chair squeak, a pick click, a cough stands out brighter), then remove selected : each frequency in the box comes down to what it is just before and after it, so what stood out goes and what was under it stays. each makes a new file the clip plays (undoable); take off repairs goes back to the original. the spectral window is titled \"spectral repair\" with the clip's name."],["editing-audio--split-a-song-into-vocals-drums-bass-and-the-rest-separate-stems","Split a song into vocals, drums, bass and the rest (Separate Stems)","Editing audio","editing-audio.html","split a song into vocals, drums, bass and the rest (separate stems) for a mixed recording (a song you're learning or covering, a band's live take with one mic, a demo bounced to one file): right-click the audio clip > separate stems... , or select it and choose audio > separate stems... . in the window: model : 4 stems: vocals, drums, bass and the rest (the cleanest), or 6 stems: guitar and piano apart too (the guitar comes out well; the piano is rougher, and the other stems a little less clean than with four). make tracks of : tick the stems you want (all to start with). other is everything the others aren't: keys, strings, synths, effects, and with the 4-stem model the guitars too. mute the original (on to start with): the clip stays where it is, muted, so turning it back on compares. click separate . the first time, the model is downloaded (84 mb for 4 stems, 55 mb for 6, from hugging face) and kept for next time in the models folder (see \"where take 5 keeps things\"); after that it needs no internet. it runs on the computer, on as many cores as its memory allows (it can use up to half the memory while it runs): about a minute per minute of song on a recent computer, a few on an older one or one with 8 gb. the window shows how far it's got and the time left; stop stops it, and nothing changes in the song. each stem arrives on a new audio track under the clip's, named \"<clip> vocals\", \"<clip> drums\"... and coloured for what it is, with a clip exactly where the original is and as long: they line up sample for sample, so together they play the song again. the stems are the clip as it plays (its gain, fades, pitch or warp included), saved as wav files in \"<clip> stems\" in the song's audio folder. one undo takes the tracks away and unmutes the original. the stems are good, not perfect: a little of the drums can be heard in the vocal and the other way round, more in a dense mix. the assistant can do it too (\"take the vocal out of this\")."],["editing-audio--play-along-with-a-song-with-the-guitar-or-the-vocal-taken-out","Play along with a song with the guitar (or the vocal) taken out","Editing audio","editing-audio.html","play along with a song with the guitar (or the vocal) taken out bring the song in (drag the file onto the tracks) and set the song's tempo to it (right-click the clip > detect tempo... > set song tempo ), so the bars and click line up. right-click it > separate stems... , choose 6 stems for a guitar, and separate . mute the stem you'll play (its track's m ), or solo the others: the band plays on without it. for a vocal (karaoke, or singing it yourself), mute the vocals track. to practise a hard part, loop it (drag in the ruler, or right-click its section > loop this section ). to slow it down without changing the pitch, select every stem's clip, right-click > follow tempo , then lower the song's tempo (double-click it in the transport bar): the stems stretch with it (see \"make audio follow the song's tempo\"). play along through your amp sim on a track of your own and record yourself over it if you like. just to learn it, file > practice... does all this in one window, with the bars and chords shown (see \"learn a song from a recording\")."],["editing-audio--pull-a-riff-a-bass-line-or-a-drum-part-out-of-a-recording","Pull a riff, a bass line or a drum part out of a recording","Editing audio","editing-audio.html","pull a riff, a bass line or a drum part out of a recording separate the recording (see \"split a song into vocals, drums, bass and the rest\"), then work on the stem alone: a bass line or a guitar or vocal melody as notes: right-click its stem > melody to midi (see \"turn a sung or hummed melody into midi\"); the notation view shows it as tab on a bass or guitar part. it works best on a stem with one note at a time. a drum part onto pads: right-click the drums stem > slice at hits (see \"slice a drum loop onto pads\"), or right-click its track's header > drum replacement... to play your own samples from its hits. a remix: the stems are ordinary audio clips: cut, rearrange, put effects on them or take one out."],["editing-audio--move-the-playhead","Move the playhead","Editing audio","editing-audio.html","move the playhead click anywhere in the lanes: on empty space, a clip, a folder, a section, a chord, a lyric or the tempo. the playhead goes there, snapped to the grid (hold ctrl cmd , for exactly where you clicked), and the click does what it does there too (a click on a clip still selects it). a click in the ruler puts it exactly where you clicked. clicks (in the ruler too) don't move it while recording. or only by dragging it: turn off edit > preferences... > editing > locate when clicked in empty space . then a click in the tracks selects and edits as usual and leaves the playhead where it is; to move it, drag the playhead's line in the tracks (the pointer becomes a two-way arrow over it), and it stays wherever you let go (on the grid; hold ctrl cmd , for exactly there). a click in the ruler still moves it. kept between launches. from the keys (in transport > set project cursor position , and to project start in transport ): - num - / num +: back or on a bar. back from inside a bar goes to its start first. - shift+← / shift+→ : back or on a grid step (a beat with the grid off). - page up / page down: back or on by a screen (the width of the arrange view). - shift+b / shift+n : the start of the section before or the next one. - home or num .: the start. end: the end of the song (where its last clip ends). - alt+n option+n / alt+b option+b : the next or previous drum hit (see \"jump to the next drum hit ( alt+n option+n )\"). when the playhead moves out of view (from a key, to project start, or the assistant), the arrange view scrolls to show it. while playing, it pages along as the playhead reaches the edge. another key set ( edit > key commands... ) puts some of these on that set's keys: classic , take 5's keys before 1.0, moves the playhead a bar with the arrow keys and goes to the start with return ."],["editing-audio--follow-the-playhead-while-playing","Follow the playhead while playing","Editing audio","editing-audio.html","follow the playhead while playing window > autoscroll , f , on to start with: while the song plays, the tracks page along when the playhead reaches the right edge. editing while it plays (moving or trimming a clip, dragging a marquee) or scrolling along the song yourself pauses it, so the view stays where you're working. it follows again on the next play or stop, or when you move the playhead (a click, a key). zooming doesn't pause it. turned off, the tracks stay where they are while playing."],["editing-audio--hear-the-audio-as-i-drag-the-playhead-scrub","Hear the audio as I drag the playhead (scrub)","Editing audio","editing-audio.html","hear the audio as i drag the playhead (scrub) grab the playhead in the ruler (the pointer turns to a two-way arrow over it), or alt option -drag anywhere in the ruler, and drag: the audio under it plays in tiny loops as it moves, to find a hit, a word or a click by ear. let go and the playhead stays there (the song plays on if it was playing)."],["editing-audio--put-a-clip-at-an-exact-place-spot","Put a clip at an exact place (spot)","Editing audio","editing-audio.html","put a clip at an exact place (spot) right-click a clip > spot... and type where it starts: a bar (17), a bar and beat (17.3), with ticks (17.3.480, 960 a beat), or a time (1:23.5, 83.5s, 0:01:23.5). with several clips selected, the earliest goes there and the others keep their places relative to it (midi clips too). one undo step. unlike a drag, it doesn't trim the clips it lands on: check for overlaps."],["editing-audio--zoom-and-scroll","Zoom and scroll","Editing audio","editing-audio.html","zoom and scroll zoom: edit > zoom > zoom in / zoom out , h / g, ctrl cmd -scroll, the scroll wheel over the ruler, or pinch on a trackpad (a windows touchpad's pinch works too). it zooms around the pointer, or around the playhead when the pointer is near it, so the playhead stays put. drag up or down in the ruler to zoom (down zooms in), moving sideways in the same drag to scroll. a drag sideways sets the loop range as before. double-click the ruler to zoom to fit, as shift+f does (the range, the selected clips or the whole song; again to go back). scroll: the wheel scrolls through the tracks, shift -scroll scrolls sideways along the song, and a trackpad's two fingers scroll both ways at once. drag with the middle mouse button anywhere in the lanes to pan both ways, and in the piano roll, drum editor and pitch editor too (along the song, and up or down the notes or pitches). taller or shorter tracks: alt option -scroll or ctrl+shift cmd+shift -scroll, as well as edit > zoom > zoom in tracks / zoom out tracks . in the piano roll and the drum editor, the same makes the note rows taller or shorter, the row under the pointer staying where it is. edit > zoom > zoom full , shift+f : fit the marquee range, the selected clips or the whole song; press shift+f again to go back. edit > zoom > undo zoom , shift+z , goes back to how it was zoomed before, and again further back (each zoom is kept once it has settled, however many wheel or pinch moves made it); edit > zoom > redo zoom , alt+shift+z option+shift+z , goes on again. each song opens zoomed and scrolled as it was when it was last closed (kept in take 5's settings, not the song, so zooming never asks to save). the main window comes back at the size and place it was when take 5 was quit, full screen if it was."],["editing-audio--bring-in-audio-files","Bring in audio files","Editing audio","editing-audio.html","bring in audio files drag audio (or midi) files from finder or explorer onto a track: a green ghost shows where it lands. a new track is named, coloured and given an icon from the file's name: \"kick_in_01.wav\" arrives as \"kick in\", red, with a drum (drums red, bass purple, guitars orange, keys green, vocals blue...); stems from another studio arrive looking like a session (a name that says nothing about an instrument stays as it is). aaf and other daws' sessions get the colours and icons, keeping their track names. project > colorize by instrument does it to the song's tracks now (keeping their names). several files: the first on that track, the rest on new tracks below; hold alt option to put them all on that track one after another. drop files between tracks, below the last one or into an empty song for new tracks there. file > import audio or midi... , ctrl+shift+i shift+cmd+i : asks whether to place them at the playhead or at bar 1, on new tracks (one each) or one after another on the selected track, and for midi files whether to keep the song's tempo or use the file's. window > panels > media browser , f5: browse folders, click a file to hear it, drag files in. right-click a file > tags... to tag it (kick, punchy, room: kept for every song) and the places list then has tagged: kick ...; right-click > find similar sounds lists the sounds in the folder (and the folders in it) most like it, by how long, bright, sharp and noisy they are: a kick finds kicks, a hat finds hats, for drum replacement's samples. click one to hear it. files are copied into the song's audio folder."],["editing-audio--use-my-sample-libraries-loops-in-the-song-s-tempo-and-key","Use my sample libraries (loops in the song's tempo and key)","Editing audio","editing-audio.html","use my sample libraries (loops in the song's tempo and key) folders of loops and one-shots (bought sample packs, a sample service's downloads folder, a sample drive) can be the browser's libraries. in window > panels > media browser , open the places list and choose add sample library... , then the folder. it's in the places list from then on as library: <its name> (the download folders of the common sample services are found by themselves). the box under the list searches every library: type words from the samples' or packs' names, a tempo and a key, \"funky bass 120 am\", and press return : the samples with every word in their names, within 3 bpm of the tempo, and in the key or its relative (a minor finds c major too). click one to hear it; selecting a file shows the tempo and key its name gives. a loop dragged into the song from a library fits it: it follows the song's tempo (from the tempo in its name, \"120bpm\") and is transposed by the fewest semitones to the song's key (from the key in its name, \"am\", when the song has a key: midi > song key ); the status line says what it did (\"in time from 95 bpm, up 2 semitones\"). one-shots without a tempo in their name stay as they are (so does a file shorter than two beats at the tempo its name gives: \"kick 101\" is a hit, not a loop at 101 bpm), and so do files from anywhere else. right-click a file in a library > remove \"<name>\" from the libraries to take a library off the list (the files stay)."],["midi-and-instruments--add-an-instrument-track","Add an instrument track","MIDI and instruments","writing-and-midi.html","add an instrument track project > add track > instrument... , ctrl+alt+s option+cmd+s , opens a menu of take 5's own instruments, then your plugins: synth : a track named \"synth\". drum machine with a kit: vintage kit (the usual), club kit, rock kit, or the synthesised electronic kit; a track named \"drums\". keys : grand piano, soft grand piano, upright piano, electric grand, pianet, wurlitzer, drawbar organ. bass : jazz bass, picked bass, upright bass, electric bass. guitar : steel-string, nylon and clean electric guitar. strings and pads : tremolo strings, sweep pad, choir pad. sampler... : your own sample or .sfz instrument. instrument stack : several instruments on one track (see \"layer instruments on one track\"). plugins : your scanned instrument plugins, by maker (none until you scan: studio > plug-in manager... ). the new track is selected, ready to arm and play; one undo step. dropping an .sfz file onto the song also makes an instrument track that plays it."],["midi-and-instruments--layer-instruments-on-one-track-instrument-stack","Layer instruments on one track (Instrument Stack)","MIDI and instruments","writing-and-midi.html","layer instruments on one track (instrument stack) project > add track > instrument... > instrument stack makes a track whose instrument is a stack of instruments played together, a piano and a pad to start, and opens its window. each layer is a row: its instrument ( instrument... opens it, to set its sound), the keys it plays (lowest and highest), the velocity it plays (softest and hardest, for a sound that comes in only when you dig in), transpose (an octave up, say), level and pan , and remove . add layer... adds another of take 5's instruments, playing the whole keyboard to start. split the keyboard with keys (a bass from the lowest c to b2, a piano from c3 up), or layer the whole of it. the stack records, freezes, saves and copies as one track; every change is one undo step. ask the assistant for one: \"a new track with a stack of grand piano and sweep pad\"."],["midi-and-instruments--write-notes-in-the-piano-roll","Write notes in the piano roll","MIDI and instruments","writing-and-midi.html","write notes in the piano roll double-click an instrument track's lane to make a midi clip; the midi editor opens below (also midi > key editor , ctrl+e cmd+e , or double-click any midi clip). in the piano roll: click the empty grid to add a note (a grid step long, velocity 100, inside the clip); drag a note to move it (all selected ones); drag its end to resize it (down to a quarter of a grid step). hold ctrl cmd to add, move or resize off the grid. shift -click adds a note to the selection or takes it out; drag the empty grid to select several ( shift -drag adds them). backspace or delete removes the selected notes; ctrl+a cmd+a in the editor selects every note. drag the bars in the velocity lane to change velocities (1 to 127): dragging a selected note's bar changes all the selected ones by the same amount. one undo step a drag. click a key on the keyboard to hear it (louder further right); slide along the keys to play each. with two or more notes selected a frame shows round them: drag the bar at its right edge to stretch or squash them in time (their starts and lengths together, from the first; the end on the grid, ctrl cmd off it), or the round handle on top down to slow them down across the selection (a ritardando) or up to speed them up (an accelerando), the first and last staying put. one undo step. the assistant does it too (\"make the fill twice as fast\", \"slow the last bar down\"). alt option -scroll makes the rows taller or shorter; fit zooms to the clip, its length across the editor and its notes filling the height ( shift+z goes back). piano roll / drums / notation switch the view; key , transform , step input , quantise and fit are with them, in the column left of the keys (right of the drums' names in the drum view; in the toolbar when the editor is too small for them there)."],["midi-and-instruments--quantise-notes","Quantise notes","MIDI and instruments","writing-and-midi.html","quantise notes press q ( edit > quantize ) to snap the selected notes (or all of them) to the snap grid, with its feel (straight or swung, from the feel box). for more control, click quantise in the midi editor: outlines show where notes will go before you apply it. strength (100% to start) moves them part of the way, a narrower window (100% to start) moves only notes near the grid, note ends too squares off lengths; align sets a gentle pass (60%, notes near the grid, ends left alone) for you to apply with quantise (it closes). midi > align notes applies that gentle pass at once. each is one undo step. q always goes all the way to the grid; the panel's settings (kept while take 5 is open) are used when you press its own quantise . with audio clips selected, q quantises the audio instead (see \"tighten the timing of a drum take\"); on a drum kit in an edit group, it opens quantise group."],["midi-and-instruments--quantise-to-the-feel-of-another-part-groove","Quantise to the feel of another part (groove)","MIDI and instruments","writing-and-midi.html","quantise to the feel of another part (groove) right-click a midi clip you played (a drummer's hi-hats, say) > use as groove , or a recorded drum take (audio) > use as groove (its feel) : its hits are found and how far each sits from the grid (set in the snap box) is the feel. the feel box then shows \"groove: <clip>\", and quantising midi parts makes them take on that feel, so a programmed bass or synth part sits with the real drummer. the groove applies while the snap box is on the grid it was taken with (on another grid quantising is straight, until you go back to that one), and it's kept with the song. choose straight (or a swing) in the feel box to go back."],["midi-and-instruments--play-notes-from-the-computer-keyboard-musical-typing","Play notes from the computer keyboard (Musical Typing)","MIDI and instruments","writing-and-midi.html","play notes from the computer keyboard (musical typing) studio > on-screen keyboard , alt+k option+k , opens a window with the keys. it plays the selected instrument track (or, if the selected track has no instrument, the first armed one), armed or not, and its top line says which: \"plays keys: upright piano\". with no instrument track to play it says so. a s d f... play the white keys (a is middle c to start) and w e t y... the black keys; z / x go an octave down / up, c / v change the velocity (by 20; 100 to start), tab is the sustain pedal. under the keys, - and + do the same for the octave and the velocity, which they show, and sustain holds the pedal down until you click it again. click a key in the window to play it with the mouse, and drag across the keys to play each one you pass: further down a key plays it louder. it also plays as a midi keyboard would, so an armed track records it like a keyboard. while it's open, letters play notes instead of running shortcuts (typing in a text box still types). keys the instrument can't reach are dimmed, and the window's top line says which way to go (for example \"an octave down (z)\"). alt+k option+k again closes it."],["midi-and-instruments--enter-notes-one-step-at-a-time-step-input","Enter notes one step at a time (step input)","MIDI and instruments","writing-and-midi.html","enter notes one step at a time (step input) open a midi clip in the editor and choose midi > step input , alt+i option+i , or its button in the editor. play notes or chords on your midi keyboard: each goes in at the playhead (on the grid; at the clip's start if the playhead isn't in it), as loud as you played it, and it moves on a step. set the step length in the box that appears (1/1, 1/2, 1/4, 1/8, 1/16, 1/32, 1/8 t or 1/16 t; the snap grid to start); rest leaves a gap, tie makes the last notes a step longer, back takes the last step out. the clip grows if you write past its end. each step is one undo step."],["midi-and-instruments--mute-notes-without-deleting-them","Mute notes without deleting them","MIDI and instruments","writing-and-midi.html","mute notes without deleting them select notes in the piano roll and choose midi > mute notes , shift+m : they're drawn faded and don't play, export or show in notation. with none selected it mutes the whole clip. the same key unmutes them (if all are muted already). useful for trying a part without some notes, or keeping a wrong note to fix later. it needs the midi editor open ( p ); it's in transform too."],["midi-and-instruments--humanise-transpose-and-change-velocities-transform-notes","Humanise, transpose and change velocities (Transform Notes)","MIDI and instruments","writing-and-midi.html","humanise, transpose and change velocities (transform notes) the midi editor's transform button (or midi > functions ) works on the selected notes, or on every note in the clip (the menu's first line says which): humanise... : small nudges in timing (up to 12 ms) and velocity (up to 10 either way). legato : each note runs to the next one's start (notes starting together count as a chord). delete doubles : the same key twice within 40 ms (a keyboard's double triggers). fixed length : 1/1 to 1/32. scale velocities... (a percentage and an amount), compress velocities... (50% evens them out half way, 100% makes them all the same, below 0 spreads them) and set velocity... (1 to 127). transpose... (semitones, 12 to start), transpose in key (up or down a step, a third, a fifth or an octave, in the song's key) and snap to key (each note to the nearest one in the key). each is one undo step."],["midi-and-instruments--set-the-song-s-key-and-see-notes-outside-it","Set the song's key and see notes outside it","MIDI and instruments","writing-and-midi.html","set the song's key and see notes outside it click the key button in the midi editor (\"key: c major\") or midi > song key : choose the key and scale (major, minor, dorian, phrygian, lydian, mixolydian, locrian, harmonic minor or melodic minor), or detect key from this clip on a played part (it says when there aren't enough notes to tell). a new song is in c major; the key is kept with the song, each change one undo step. with shade notes outside the key on (it is to start with), out-of-key rows are shaded in the piano roll and the root is tinted. the key is also used for notation spelling, chord ideas, transpose in key and pitch correction."],["midi-and-instruments--draw-pitch-bend-mod-wheel-and-other-controllers","Draw pitch bend, mod wheel and other controllers","MIDI and instruments","writing-and-midi.html","draw pitch bend, mod wheel and other controllers in the midi editor, choose what the bottom lane shows: velocity, pitch bend, mod wheel (cc 1), expression (cc 11), volume (cc 7), pan (cc 10), sustain (cc 64), breath (cc 2), brightness (cc 74), aftertouch, any other controller the clip already uses (marked), or other cc... (any number, 0 to 127). drag to draw freehand, shift -drag for a straight line, alt option -drag to erase; each stroke is one undo step. each value holds until the next; pitch bend snaps to the middle near it. the instrument follows it on playback."],["midi-and-instruments--add-an-arpeggiator-or-chord-effect","Add an arpeggiator or chord effect","MIDI and instruments","writing-and-midi.html","add an arpeggiator or chord effect select an instrument track and choose midi > add midi effect (greyed until one is selected): arpeggiator : pattern (up, down, up & down, as played, random; up to start), rate (1/4 to 1/32, with triplets; 1/16 to start), octaves (1 to 4) and gate (how long each note is, 5 to 100%; 80 to start). hold a chord and it plays its notes in turn, in time with the song. chord : one key plays a chord of that shape on any key: major, minor, 7th, major 7th, minor 7th, sus 4, sus 2, power (5th) or octaves (not tied to the song's key). transpose : moves every note up or down by semitones . it goes before the track's instrument (after any other midi effect) and its window opens. one undo step."],["midi-and-instruments--mix-on-a-hardware-controller-control-surfaces","Mix on a hardware controller (control surfaces)","MIDI and instruments","writing-and-midi.html","mix on a hardware controller (control surfaces) a mixing controller with motor faders that speaks mackie control (most do, often as an option on the unit), or a few others the engine knows, can run the mixer and transport. connect it, then studio > control surfaces... : tick the controller and choose the midi input it sends from and the midi output back to it (its motor faders, lights and display). its faders, pans, mutes, solos and arm buttons are the open song's first 8 tracks (its bank buttons move along 8 at a time, an extender adds 8 more strips), its transport buttons play, stop, record and wind, and its display shows the track names. it follows the song you open. its encoders (the knobs above the faders) turn the selected track's smart controls ( window > panels > smart controls : drive, space ...), named on its display; with a plugin selected they turn the plugin's settings instead, a page at a time. for single knobs on an ordinary midi controller, use midi learn instead (below)."],["midi-and-instruments--map-a-controller-knob-to-a-fader-or-plugin-midi-learn","Map a controller knob to a fader or plugin (MIDI learn)","MIDI and instruments","writing-and-midi.html","map a controller knob to a fader or plugin (midi learn) right-click a fader, pan knob or a slider in a built-in plugin's window > midi learn... , or choose midi > midi learn and pick the selected track's volume, pan or a plugin parameter. then move a knob or fader on your controller: they're linked (controllers only: notes and pitch bend aren't learnt; one knob for one control). esc cancels while it's waiting; right-click > forget unlinks one. a third-party plugin's own window can't be learnt from (use the built-in sliders, or midi > midi learn ). midi > midi mappings... lists the mappings and removes them; they're saved with the song."],["midi-and-instruments--import-or-export-a-midi-file","Import or export a MIDI file","MIDI and instruments","writing-and-midi.html","import or export a midi file import: drag a .mid file into the song (new tracks where you drop it, on the song's tempo), or file > import audio or midi... . each part gets a track (channel 10's drums on a drum machine, the rest on the built-in synth), with its controllers and pitch bend. the import window asks where (at the playhead or bar 1), whether onto new tracks or merged into the selected instrument track, and the tempo: keep the song's tempo (to start with) or use the midi file's tempo and time signature . export: file > export > export midi file... writes the whole song (tempo, time signatures, key, section markers, a track per part, drums as drums). right-click a track > export track as midi file... , or a midi clip > export as midi file... , for just that."],["midi-and-instruments--write-chords-in-the-chord-lane","Write chords in the chord lane","MIDI and instruments","writing-and-midi.html","write chords in the chord lane project > chord track shows the song's chords under the sections. double-click to add a chord (type a name like c, am7, f#dim, bbmaj7, dsus4), drag a chord to move it, right-click to change or remove it ( change... , remove ); chords snap to the grid. a name it doesn't know says what it does know (\"try c, cm, c7...\"). from a midi clip of chords: select it, right-click the lane > chords > detect chords from clip (a chord a bar) or (a chord a beat) . to hear them, chords > make a clip from the chords : held chords , bass note and chord or arpeggio (eighths) , on the selected instrument track (or a new \"chords\" track), over the marquee or the whole chord lane. remove all chords clears it. the same chords menu is in midi > chords . the chords print above the notation."],["midi-and-instruments--get-chord-progression-and-melody-ideas","Get chord progression and melody ideas","MIDI and instruments","writing-and-midi.html","get chord progression and melody ideas put the playhead in a section (or drag a marquee over the bars; with neither, the 8 bars from the playhead), show the chord lane, right-click it > chords > chord ideas for ... and choose a style (pop, ballad, rock, folk, jazz), a chord a bar or two a bar: chords in the song's key replace the ones there, and choosing again gives another idea. then chords > melody idea for ... and a contour ( arch (up, then down) , rising , falling , wave ) and density (sparse, medium, busy): a \"melody idea\" clip on the selected instrument track, or a new \"melody\" track on the built-in synth. keep it, edit it like any midi, or delete it. ctrl+z cmd+z undoes either."],["midi-and-instruments--strum-chords-add-flams-and-grace-notes-chop-and-ratchet-notes-writing-parts-faster","Strum chords, add flams and grace notes, chop and ratchet notes (writing parts faster)","MIDI and instruments","writing-and-midi.html","strum chords, add flams and grace notes, chop and ratchet notes (writing parts faster) in the midi editor, midi > functions (or the editor's own menu) works on the selected notes, or every note in the clip when none are: strum chords : each chord's notes one after another like a guitar: down (low to high) , up (high to low) , or down and up, alternating chord by chord; each later string a little softer (18 ms apart, each string 4 softer). strum spread... strums down with your own spacing (1 to 200 ms) and softening. add flams : a softer hit (60%) of the same note 25 ms before each (snares). add grace notes : a short note (a 32nd) a semitone or a tone below (or a tone above) leading into each. chop into repeats : each note cut into 2, 3, 4 or 8 equal repeats. ratchets : each note played 2, 3, 4 or 6 times in its length, short, or dying away (to 40%). chance (plays some of the time) : a note plays 75 %, 50 % or 25 % of the time, the dice rolled again each time round (a hi-hat that varies, a ghost note now and then). always puts it back. a note with a chance is drawn dashed, with its percentage on it. euclidean rhythm... : hits spread as evenly as they go over a number of steps (3 of 8 is the tresillo, 5 of 16 a son clave's feel), turned by a rotation, at a note you name (c1, f#1 or a number), over the whole clip, replacing that note's hits there (3 of 8 eighths on c1 to start; up to 64 steps). random rhythm... does the same from a seed and a density (16 sixteenths, 50%, f#1 to start): the same seed gives the same rhythm, another seed another one. both fill the whole clip, whatever's selected. each is one undo step."],["midi-and-instruments--record-and-play-an-mpe-controller","Record and play an MPE controller","MIDI and instruments","writing-and-midi.html","record and play an mpe controller an mpe controller (a keyboard or surface where each finger bends, presses and slides its own note) sends each note on a channel of its own with its own expression. choose midi > mpe inputs and tick the controller: from then on its notes are recorded with their expression kept in each note (its bend, pressure and slide), not as the channel's pitch bend and controllers, and the clip plays as mpe, each note again on a channel of its own, to an instrument that takes mpe (set the instrument's own mpe mode on, and its bend range to 48 semitones, as mpe's standard is). a clip can be switched by hand: in the midi editor, midi > functions (or the editor's transform menu) > expression (mpe) > play as mpe . a note with expression shows it: its bend as a line through the note (a semitone a row), pressure or slide as a line along its foot."],["midi-and-instruments--bend-vibrato-and-swells-on-single-notes-note-expression","Bend, vibrato and swells on single notes (note expression)","MIDI and instruments","writing-and-midi.html","bend, vibrato and swells on single notes (note expression) without an mpe controller, notes can be given expression by hand: select them in the midi editor, then midi > functions > expression (mpe) : bend up a semitone / bend down a semitone : held, then bent by the end of the note. scoop up into the note : from a semitone under, up to it in a quarter of a beat. vibrato : a quarter of a semitone either way, two and a half times a beat, after a moment. swell (pressure) / fade out (pressure) : louder in the middle, or dying away (on instruments that answer pressure). clear expression takes it off. each note gets its own, shaped to its length, and the clip plays as mpe (an instrument that takes mpe hears it; others play the notes plainly). each is one undo step."],["midi-and-instruments--set-up-an-instrument-s-articulations-articulation-maps","Set up an instrument's articulations (articulation maps)","MIDI and instruments","writing-and-midi.html","set up an instrument's articulations (articulation maps) an orchestral library's strings (or brass, or a sampled guitar) switch between legato, staccato, pizzicato and the rest with keyswitches (notes below the playable range) or program changes. give the instrument's track a map once, and its notes can be given articulations by name. right-click the track's header > articulation map... (or in the midi editor, transform > articulation > articulation map... ). start from one of the usual layouts (strings, brass, woodwinds, solo strings, guitar; keyswitches from c1 up), then change the lines to your instrument's: a line for each articulation, its name, then = and the keyswitch note (\"staccato = d1\"; middle c is c4, as the piano roll names notes) or \"program\" and its number (\"pizzicato = program 46\"). save keeps it with the track; no map takes it off."],["midi-and-instruments--choose-an-articulation-by-name-articulation-maps","Choose an articulation by name (articulation maps)","MIDI and instruments","writing-and-midi.html","choose an articulation by name (articulation maps) in the midi editor, select notes, then midi > functions > articulation and choose one (staccato, legato...): its name shows on each note. where the articulation changes, the switch is put in a 64th before the note (a short keyswitch note, drawn faint, or a program change), so the library is on the right one when the note sounds; notes with none play as the one before them. none (as the note before) takes a note's articulation off. changing the map puts all the switches in again. in notation (and printed sheet music), staccato, staccatissimo, accent, tenuto, spiccato and marcato show as their marks over the notes."],["midi-and-instruments--turn-a-sung-or-hummed-melody-into-midi-melody-to-midi","Turn a sung or hummed melody into MIDI (Melody to MIDI)","MIDI and instruments","writing-and-midi.html","turn a sung or hummed melody into midi (melody to midi) right-click an audio clip of one voice or instrument (a vocal, a hummed idea, a bass di, a lead guitar) > melody to midi : its notes, found as the pitch editor finds them (its splits, joins and octave fixes included), become a midi clip on a new instrument track under it, each note rounded to the nearest semitone and as loud as it was sung, on a track named \"<track> notes\" (if no notes are found, the status line says so). it plays on the built-in synth (change the instrument as for any track); the notation view shows it as notes, and as tab on a guitar or bass part. short blips (under 70 ms) are left out. the other way, correct to a midi part (same menu) corrects the clip's pitch to a midi part on a track you choose (tracks with midi clips): each sung note goes to the midi note playing at its middle (as if each were set by hand in the pitch editor, where they show and can be changed). one undo step each."],["midi-and-instruments--show-a-part-as-sheet-music-notation","Show a part as sheet music (notation)","MIDI and instruments","writing-and-midi.html","show a part as sheet music (notation) open a midi clip and click notation in the midi editor ( midi > open score editor , ctrl+r cmd+r ). notes show in the song's key and time signature with the chord lane's chords above; whole track shows every clip on the track; the box next to it rounds played timing to 1/8 , to 1/16 (to start) or to 1/32 (kept with the song, and the same as sheet music's). a long part (a whole song's tab, say) takes a moment to lay out: laying out the notation... shows over the last page meanwhile, and the rest of take 5 keeps working; the new page appears when it's done. click a note to select it ( shift -click for more, esc for none), drag it up or down or press up/down to move it a semitone ( ctrl cmd : an octave), 2 to 7 set its length (2 a 32nd, 3 a 16th, 4 an eighth, 5 a quarter, 6 a half, 7 a whole note), . dots it, delete removes it, left/right go to the next note. each edit is one undo step. the notes playing light up and the page follows the playhead."],["midi-and-instruments--open-a-guitar-pro-file-a-tab-from-a-bandmate-or-the-web","Open a Guitar Pro file (a tab from a bandmate or the web)","MIDI and instruments","writing-and-midi.html","open a guitar pro file (a tab from a bandmate or the web) guitar pro files (.gp from guitar pro 7 and 8, .gpx from guitar pro 6, and .gp5, .gp4 and .gp3 from older versions and most tab sites) open as part of a song. drag one into the song, or file > import audio or midi... and choose it. the import window asks where (at the playhead or bar 1) and tempo : use the file's tempo and time signature (the default: the song gets the file's tempo, its tempo changes and its time signatures, bar for bar) or keep the song's tempo . each instrument gets a track of its own, named as in the file: guitars, basses, keys and strings play on the nearest instrument that comes with take 5, drums on a drum machine. delete the tracks you don't want. repeats, first and second endings, d.c., d.s. and codas are played out in order on the timeline, so what you hear is the song as played. the file's sections become section markers, chord names go into the chord lane and lyrics into the lyrics lane, a bar per line (when the song has none yet). the song's key is set from the file's if the song has none. the tab shows what the file wrote: each note keeps its string and fret, and the track's tuning (in its notation menu) is the file's, with its capo (\"d a d g b e, capo 2\"). move a note to another pitch and it's placed as any note is. what the guitar does is heard too: bends and the whammy bar (as pitch bend, up to two semitones), slides, hammer-ons and pull-offs a little softer, palm mutes shorter and softer, dead notes as short clicks, let ring longer, vibrato, harmonics at their pitch, grace notes just before the beat and tremolo picking as repeated notes. an instrument has one pitch wheel, so a bend on one note of a chord bends the whole chord. open the track's midi clip in the editor and switch to notation ( midi > open score editor ) to see it as sheet music and tab, or print it with score > sheet music... . the tab shows how each note's played, as the file wrote it: h and p over hammer-ons and pull-offs, slide lines, the bend's amount, p.m. for palm mutes, let ring, x for dead notes, harmonics and vibrato; sheet music's save as... writes them too, as musicxml, guitar pro or a text tab. to give a part back to someone with guitar pro, score > sheet music... > save as... > guitar pro (.gp)... : a guitar pro 7 and 8 file (guitar pro 6 to 8, tuxguitar and songsterr open it) with every ticked part, each guitar and bass on its strings and frets in its tuning and capo, the drums as a kit, the techniques, tempo, sections, repeats and lyrics. musicxml (for notation apps)... writes the same for any notation or tab app, and text tab (.txt)... the tab as text (see \"copy, paste or open a text tab\")."],["midi-and-instruments--open-a-musicxml-file-from-a-notation-app-or-a-tab-site","Open a MusicXML file (from a notation app or a tab site)","MIDI and instruments","writing-and-midi.html","open a musicxml file (from a notation app or a tab site) musicxml is the file notation and tab apps share: .musicxml , .xml , or compressed .mxl . drag one into the song, or file > import audio or midi... and choose it: it comes in as a guitar pro file does, with the same window (where, and the file's tempo or the song's). each part gets a track of its own: a part with tab keeps each note's string and fret and its tuning and capo, a part without tab comes in by its notes, and drums by their kit pieces. the bars play out in order (repeats, endings, d.c., d.s. and coda), rehearsal marks become section markers, chord names go into the chord lane and lyrics into the lyrics lane, and the playing techniques take 5 writes (hammer-ons and pull-offs, slides, bends, vibrato, harmonics, palm mutes, let ring, dead notes) come back on the notes. a part saved from take 5's save as... > musicxml opens as it was."],["midi-and-instruments--copy-paste-or-open-a-text-tab-the-dashes-and-numbers-kind","Copy, paste or open a text tab (the dashes-and-numbers kind)","MIDI and instruments","writing-and-midi.html","copy, paste or open a text tab (the dashes-and-numbers kind) tab sites and messages write tab as text, a line per string with the frets on dashes: e|-----------------| b|-----------------| g|-----7b9---------| d|-0---5h7---------| edit > paste tab turns a text tab you've copied into a new track (\"pasted tab\") at the playhead; file > import audio or midi... (or dragging it in) does the same for a .txt file with tab in it. the tuning comes from the strings' names (d a d g b e is drop d), chord names above the tab go into the chord lane, and the techniques are read as tab sites write them: h and p (hammer-on, pull-off), / and its backslash (slides), b (a bend to the fret after it: 7b9), ~ (vibrato), x (a dead note), <12> (a harmonic) and pm over palm-muted notes. a text tab rarely says the rhythm, so it's guessed from the spacing: each bar is 4/4 at the song's tempo, a note where it sits in its bar to the nearest 16th. the notes come in in order; fix the timing by ear in the piano roll. the other way, select a guitar or bass track and choose edit > copy as tab : its tab as text, four bars a line, a 16th a dash, the techniques as above and the chord names over it, ready to paste into a message or a tab site."],["midi-and-instruments--get-the-tab-of-a-recorded-guitar-or-bass-part-transcribe-to-tab","Get the tab of a recorded guitar or bass part (Transcribe to Tab)","MIDI and instruments","writing-and-midi.html","get the tab of a recorded guitar or bass part (transcribe to tab) rather than work a part out by ear, have take 5 hear the notes: right-click the guitar's or bass's audio clip > transcribe to tab... , or select it and choose audio > transcribe to tab... . in the window: instrument : guitar or bass (a track with \"bass\" in its name starts on bass). tuning : how it was tuned (the same list as the notation's: standard, drop d, dadgad, open tunings, 7-string; for bass bead and 5- and 6-string), and for a guitar the capo fret. notes : one at a time for a bass line, a lead or a riff (the more reliable: a note's overtones aren't taken for notes of their own), chords too for strumming and arpeggios. a guitar chord (three notes or more heard together) is written in the chord's usual shape (an open c, an f barre, an e5 power chord) with its bass note as heard, rather than every note heard: distortion and ringing strings add notes that weren't played. separate the guitar first (or the bass ): for a mixed song or a band's take, the instrument is taken out of the mix first (as separate stems does, nothing added to the song) and only that is listened to. a part recorded on its own doesn't need it. click transcribe . it runs on the computer and nothing is sent anywhere: a song takes seconds (with separate first, the separation model is downloaded the first time, 55 or 84 mb, and separating takes about a minute per minute of audio). stop stops it, and nothing changes in the song. the tab arrives as one undo step on a new track under the clip's (\"bass tab\"): an instrument track with a recorded guitar or bass, its notation set to that instrument with tab in the tuning, and the notes as midi in time with the song. strings and frets are worked out for the whole part at once, so a line stays in one hand position where it can and moves where it pays to; open strings are used where they fit. a bass note heard an octave off its neighbours is put back in their octave. what's heard of how a note was played is marked as a guitar pro file's is: a bend (with how far, to the nearest half step), vibrato, and, playing one note at a time, a slide or a hammer-on or pull-off into the next note (it goes on from the last without being picked again). check it in the notation view ( midi > open score editor ) against the recording: a fast run or a dense chord gets some notes wrong, and any note's string can be changed by hand there (see \"show guitar or bass tab\"). on a mac it needs macos 13.4 or later; on an older one the command says so."],["midi-and-instruments--see-the-tab-of-what-i-m-playing-tab-as-you-play","See the tab of what I'm playing (Tab as You Play)","MIDI and instruments","writing-and-midi.html","see the tab of what i'm playing (tab as you play) select a guitar or bass track (its input is what's heard) and choose studio > tab as you play... . a window shows what you play as tab, scrolling by from the right a second or two behind your playing, the last ten seconds on screen: each note's fret on its string, with b for a bend, ~ for vibrato, h and p for hammer-ons and pull-offs and / or \\ for slides. the fingering settles as more is heard. the instrument and strings are the track's (right-click it > notation : guitar with tab or bass with tab, and the tuning); one at a time or chords too as for transcribe to tab. nothing is recorded: it's for practice, to see what you just played. keep the last phrase puts what you played since the last pause of two seconds on a new tab track under this one, at the playhead. stop stops listening; listen starts again. the track needs an audio input (its header's input menu)."],["midi-and-instruments--get-the-tab-as-i-record-tab-while-recording","Get the tab as I record (Tab While Recording)","MIDI and instruments","writing-and-midi.html","get the tab as i record (tab while recording) right-click a guitar or bass track > tab while recording (or tick tab while recording on this track in tab as you play). when you record on it, tab as you play opens to show the take as you play it, and when recording stops the take gets its finished tab, as transcribe to tab would make it: the window shows its progress, and the tab arrives on a track under it (strings, frets and chord shapes worked out over the whole take). it's kept with the song."],["midi-and-instruments--show-guitar-or-bass-tab","Show guitar or bass tab","MIDI and instruments","writing-and-midi.html","show guitar or bass tab a midi track with a word like \"gtr\", \"guitar\" or \"bass\" in its name gets tab by itself ( automatic (from the name) ; drum tracks never do). or right-click the track > notation > guitar with tab or bass with tab ( standard for none), and pick a tuning there: for guitar standard, half or whole step down, drop d, c#, c or b, dadgad, open d, e, g or c, and 7- and 8-string tunings; for bass standard, half step down, drop d, bead, 5-string (low b or high c) and 6-string. guitar is written in treble clef an octave down with tab below; bass in bass clef with a line per string. click a fret number to select its note. to see only one of them, right-click the track > notation > show : notes and tab (to start), notes only (no tab; how each note's played, bends, slides and the rest, is marked on the notes instead) or tab only (the strings and frets, with rests for the gaps). it's kept with the track: the notation view, score > sheet music... and the lead sheet show it so, and sheet music has the same choice as guitar and bass for the parts ticked."],["midi-and-instruments--print-sheet-music-or-save-it-as-pdf-or-musicxml","Print sheet music or save it as PDF or MusicXML","MIDI and instruments","writing-and-midi.html","print sheet music or save it as pdf or musicxml score > sheet music... , ctrl+p cmd+p , or the midi editor's sheet music... button. tick the parts (the midi editor's part, or the selected tracks, or all, to start with), set the title, paper (a4 or us letter), shortest note (eighth, sixteenth or 32nd notes), for guitar and bass parts notes and tab, notes only or tab only (each track's own, as its notation menu has it), triplets, chord symbols and section names (kept with the song), and check the preview, page by page (after a change, laying out the pages... shows while the new pages are made; print and save wait for them). print... prints (on windows it opens the pdf in your pdf viewer to print from), save pdf... saves it, save parts... saves each ticked part as its own pdf for each player, and save as... writes the music as musicxml (for notation apps: the format they share), a guitar pro (.gp) file, or a text tab (.txt) (when a ticked part has tab). one part with chords makes a lead sheet. the midi itself isn't changed."],["midi-and-instruments--use-the-sampler-with-my-own-samples","Use the Sampler with my own samples","MIDI and instruments","writing-and-midi.html","use the sampler with my own samples project > add track > instrument... > sampler... and pick a wav, aiff, flac or ogg sample (played across the keyboard; its root note is the one written in the file, or a note name in the file name like \"piano c4.wav\", or else the note take 5 hears it play, tuned to the cent; its loop is used) or an .sfz instrument (with its zones, velocity layers and loops). the sampler's window has attack , decay , sustain , release , cutoff , resonance , volume and velocity (how much playing harder is louder), and can load another sample. detect pitch listens to the sample and sets its root note and fine tune (the line beside it says them, e.g. \"root a3, -31 cents\"), so every key plays in tune; a drum or a noise has no pitch to find, and says so. ø plays the sample upside down (polarity), to line it up with another layer of the same sound. the sustain pedal works."],["drums--program-a-beat-on-the-drum-machine","Program a beat on the Drum Machine","Drums","writing-and-midi.html","program a beat on the drum machine project > add track > instrument... > drum machine and a kit: vintage kit (the usual), club kit, rock kit or electronic kit (synthesised). in its window (click its plugin slot): the pads : 16, the kick at the bottom left, then the snares, hats, toms and cymbals going up. click one to hear it, harder lower down on the pad. each lights up as it's hit, by the song or a keyboard (brighter for a harder hit). the step grid edits the drum track's midi clip at the playhead (or its first clip), a page of 16 sixteenths at a time (a bar in 4/4): click a step to add or remove a hit, shift -click an empty step for an accented one. the line above says which clip and bar it is (\"pattern: drums, bar 1 of 16 (song bar 3)\"); < and > go to its other bars (the grid follows the playhead again when you play). new 1-bar pattern here makes a clip a bar long where the playhead is (on a drum track with no clip yet, make a 1-bar pattern ). one undo step. the drum editor shows the same notes with the pads' names (see \"edit drums in the drum editor\")."],["drums--change-a-drum-pad-s-sound-or-kit","Change a drum pad's sound or kit","Drums","writing-and-midi.html","change a drum pad's sound or kit in the drum machine window: kit switches the whole kit (vintage, club, rock or electronic), even while it plays. it replaces every pad's sound and settings (your own samples too); each pad keeps its output. select a pad (\"pad 1: kick\") to change its tune (-24 to +24 semitones), decay (natural, or cut off after up to 3 seconds), pan and level (-24 to +12 db). on the recorded kits a pad has several samples (soft to hard, and alternating), and these change them all together. polarity : ø plays the pad upside down. to layer two pads (a kick's two mics, a snare and a sample of one), choose the other in compare with... : the line beside it says whether they're in phase , working against each other (they thin each other out when they play together: flip one with ø) or unrelated . drop a sample (wav, aiff, flac, ogg or mp3) on a pad to replace its sound, or right-click it > load sample... , choke group (none or 1 to 4: pads in a group cut each other off, as the open and closed hi-hat do; the hats start in group 1, shown on the pads) or remove sample . the kit and the pads are kept with the song. undo puts each change back (a slider drag is one step)."],["drums--edit-drums-in-the-drum-editor","Edit drums in the drum editor","Drums","writing-and-midi.html","edit drums in the drum editor open a drum track's midi clip (double-click it, or ctrl+e cmd+e ): the editor shows a row per drum, named, with hits as diamonds coloured by family (kicks red, snares orange, hats yellow, toms teal, cymbals violet). on a track that isn't a drum machine, click drums in the midi editor for the standard drum names (any note the kit doesn't name still gets a row, by its note). add, move and delete hits and change velocities (the lane at the bottom) as in the piano roll; q quantises. hits snap to the grid (hold ctrl cmd , for off-grid), have no length to change, and clicking beside a hit that's already in that grid cell selects it rather than adding a second one (the piano roll does the same for notes). the editor opens in piano roll or drums from the clip's track each time. window > windows > open editors in a window floats it."],["drums--give-the-kick-snare-and-hats-their-own-mixer-channels","Give the kick, snare and hats their own mixer channels","Drums","writing-and-midi.html","give the kick, snare and hats their own mixer channels right-click the drum track's header > drum channels > kick, snare, hats, toms and cymbals (or every pad ): tracks appear under it, one per group, each with its own fader, plugins and sends. put a compressor on the kick without touching the hats. the groups: the snare with the side stick and clap; the closed, pedal and open hats; the four toms; the crash, ride and ride bell. the tambourine and cowbell stay on the drum track, and only pads that have a sound get a channel (up to 16). in the drum machine window, a pad's output moves it: drum track (main) , a channel, or new channel for this pad . soloing a channel plays just it; muting the drum track leaves its channels playing. drum channels > all back to one output undoes it; deleting a channel puts its drums back on the drum track. each is one undo step, kept with the song. a drum track with channels can't be frozen (nor a channel on its own), and a channel bounces whole, not a range of it."],["drums--slice-a-drum-loop-onto-pads","Slice a drum loop onto pads","Drums","writing-and-midi.html","slice a drum loop onto pads import a drum loop, right-click it > slice at hits > under onto drum machine pads (up to 16) , choose fewer slices (the main hits) , normal or more slices (quieter hits too) . a new track below, \"<clip> slices\", gets a drum machine with a slice on each pad (slice 1, slice 2...) and a midi clip that plays the loop as it was; the original is muted. with more than 16 hits the strongest are kept, the weaker ones joining the slice before. the slices are taken as the clip plays (its gain, fades, reverse or warp) and saved as wav files in the song's audio folder. move or quantise hits in the drum editor to rearrange it. across sampler keys puts a slice on each key from c1 instead (up to 92; good for riffs and vocal phrases). one undo step."],["drums--add-a-sample-to-every-kick-or-snare-hit-drum-replacement","Add a sample to every kick or snare hit (drum replacement)","Drums","writing-and-midi.html","add a sample to every kick or snare hit (drum replacement) right-click the kick (or snare) mic's audio track header > drum replacement... . with a marquee range on the track, only that range is used. the picture shows every hit found at its level (\"520 hits in 180 s, 40 quieter ones left out\"). adjust sensitivity (higher finds quieter hits; 50% to start), gap (5 to 150 ms, 30 to start: lower for fast double kick) and leave out quieter than (-60 to 0 db, or drag the line) so only real hits count, not bleed. each hit's level is measured in its own drum's band (a kick's lows, a snare's crack), where another drum's bleed is far quieter, so the -24 db it starts at leaves most bleed out and keeps ghost notes. choose the drum (guessed from the track's name: \"kick in\" picks the kick) and kit, or sample of your own... (wav, aiff or flac), and blend under it or replace it (which mutes the original and sets the level to 0 db; blended, it starts at -6). line up with it (time and polarity) is on to start with; off, flip polarity and nudge (up to 10 ms either way) are yours to set. make trigger : a \"<track> trigger\" track appears right under it, lined up in time and polarity, each hit as loud as the one it's under. solo the trigger to check every hit. its track menu > drum replacement settings... changes it later ( update trigger finds the hits again: edits you made to the trigger's notes are lost). one undo step takes it all back."],["drums--a-drum-part-for-the-song-before-the-drummer-s-heard-it-the-session-drummer","A drum part for the song before the drummer's heard it (the session drummer)","Drums","writing-and-midi.html","a drum part for the song before the drummer's heard it (the session drummer) project > add track > drummer adds a drummer: a track called \"drummer\" at the end, a drum machine (with the rock kit) that plays a part for the whole song, following its sections (add section markers first, track > insert marker; with none it plays the whole song). its window opens; press play. track > drummer... (or the track header's menu > drummer... ) opens it again, for the selected drummer track or the first. it sets how it plays: style : rock, half-time, punk, metal (double kick) or blast beat. a section can have its own ( drummer's style follows the drummer's). kick follows : a track whose rhythm the kick plays (its midi notes, or the hits in its audio), e.g. the bass; nothing (the groove's kick) to start with. for each section: plays (off for a break), simple - busy (which groove and fill), soft - loud (how hard; from three-quarters up the hats move to the ride, in a blast beat to the crash) and fill into it ( none , short : the last two beats, or long : the whole bar before it). double-click a slider for the middle. sections start from their names: an intro softer and simpler, a verse a little quieter, a chorus or solo louder and busier with a long fill into it, an outro loud, a break silent. every change writes its part again (a midi clip per section) as one undo step; the same settings always give the same part. write again catches up after the song's sections, tempo or the followed track change. turn into midi keeps the part as ordinary clips with every hit, to edit in the drum editor; if you edit the drummer's clips without doing that, it asks before writing over them (\"write the drummer's part again?\"). other clips you put on the track are left alone. the settings are kept with the song, by section (renaming a section keeps its settings). a drum machine track with nothing on it yet: its track menu > make it the drummer . bars not in 4/4 get a plain beat for now. the assistant can do all of it (\"a punk drummer, busy in the choruses, the kick on the bass\")."],["mixing--open-the-mixer","Open the mixer","Mixing","mixing.html","open the mixer studio > mixer , f3, shows or hides the mixer; so does the × at the right of its title bar. where it shows is up to you: window > windows > mixer in place of tracks (to start with), mixer below tracks ( alt+f3 option+f3 ; drag the edge between them to resize) or mixer in own window ; it's remembered with the layout. with the mixer in place of the tracks, the window's close button closes the mixer first (the status bar says so); click it again to quit. the strips are laid out as on a console: the track's name at the top, then its inserts (plugin slots) and sends , then pan and stereo width, the fader with its db scale and meter, ø (polarity), the level, arm, mute and solo, and the name again at the bottom. the fader stays a sensible height, so a taller mixer shows more slots rather than a longer fader; a short one (below the tracks) drops the headings and the fader shrinks to fit the slots; sends that don't fit are in the track's menu, the inspector and the headers. click a strip's name to select its track, drag it to move the track (into or out of a folder too). a vca's strip has just its fader, name, mute and solo; a bus has no arm button. the master strip is on the right with talk , listen , mono , dim (20 db down), master off and mix / ref ; mono and dim change only what you hear, never an export. in the console layout the strips also have routing and pre (see \"work in the console layout\")."],["mixing--see-a-track-s-settings-in-the-inspector","See a track's settings in the Inspector","Mixing","mixing.html","see a track's settings in the inspector window > inspector , i , shows a column at the left of the tracks (and of the mixer, when it's in their place) for the selected track. click a track or a clip and it follows; with nothing selected it keeps the last track. click a section's heading to fold it away (take 5 remembers which); drag its right edge to make it wider (double-click the edge for the default width); the x in its title bar, or i again, closes it. clip (when a clip is selected): its name , start , end and length ; for audio clips its gain (-24 to +24 db; double-click for 0), fade in and fade out ; muted . click a value to type a new one: start takes a bar (\"17\"), a bar and beat (\"17.3\") or a time (\"1:23.5\") and moves the clip there; end trims the clip's end; fades take milliseconds (\"250\") or seconds (\"1.5 s\"). several clips selected: the first is shown. track : its name, colour (click for the palette), input (audio inputs, or midi inputs for an instrument track, or no input ), output (the master or an output of the interface; a bus has neither) and notes . channel : the track's mixer strip, with its inserts, sends, pan, fader and buttons, and beside it the strip of where it goes (its folder, when the folder is a submix, or the master; none when it goes straight to an interface output). every change is one undo step (but notes, which are kept as you type)."],["mixing--set-levels-pan-and-width","Set levels, pan and width","Mixing","mixing.html","set levels, pan and width drag a fader or pan knob; double-click it, or alt option -click it, to go back to 0 db or centre. shift -drag moves it in fine steps, a tenth as far (pressing shift partway through a drag works too). ctrl cmd -click any fader or knob to type an exact value (\"-6\", \"-inf\", \"l30\", \"c\", \"120%\"). these work on every knob and fader in take 5. the width knob next to pan (0 to 200%): fully left (0%) is mono, the middle (100%) leaves it as it is, fully right is twice as wide. undo puts fader, pan and send moves back, one step per drag. the mouse wheel over a track header's fader or pan scrolls the tracks rather than moving them, so scrolling never changes a level by accident."],["mixing--place-a-track-around-the-listener-in-3d-spatial-mixing","Place a track around the listener in 3D (spatial mixing)","Mixing","mixing.html","place a track around the listener in 3d (spatial mixing) add a plugin > built-in > 3d panner on a track places it around the listener, for headphones: azimuth turns it around (0 ahead, 90 right, -90 left, 180 behind), elevation lifts it (90 overhead) or drops it, distance takes it further away (1 m is as it was; further is quieter and darker), and width keeps some of a stereo track's spread (0: one point). on headphones it sounds from there: the far ear hears it a fraction later and duller, as with a head in the way, behind is darker, and higher has a dip ears use for height. each is automatable, so a synth can circle the listener or a vocal come closer in the chorus. it turns a track to mono and back to stereo, so put it last on the track. on speakers it's a pan with a little colour: it's made for headphones."],["mixing--export-a-spatial-mix-adm-for-a-spatial-mixing-tool","Export a spatial mix (ADM) for a spatial mixing tool","Mixing","mixing.html","export a spatial mix (adm) for a spatial mixing tool file > export > export spatial mix (adm)... writes the song as a broadcast wav with adm metadata, the open format spatial (object-based) mixing and mastering tools read: the tracks with a 3d panner each become an object (their own channel, the track without the panner, with where the panner places it over time), and everything else is a stereo bed. open it in such a tool to make the masters for spatial-audio streaming. (take 5 itself doesn't make those masters: that needs the licensed renderers the streaming services ask for.) the file is made at the loudness spatial mixes are delivered at: -18 lufs, measured on the mix as heard on headphones. take 5 renders that first, measures it, and turns the whole file up or down to -18 (the bed and every object alike, so the balance stays as you mixed it; the song itself isn't changed). it also checks the bed's peak, which should stay under -1 dbtp. the status line says what it found and did: \"-18.0 lufs on headphones (turned down 2.3 db to reach -18), the bed's peak -2.1 dbtp\", or \"over -1: turn the bed's tracks down\" when the bed peaks too high. export takes a little longer for the extra render."],["mixing--solo-and-mute-tracks","Solo and mute tracks","Mixing","mixing.html","solo and mute tracks m mutes, s solos. a soloed track keeps its reverb and delay buses. alt option -click an s: solo just this one. shift -click an s: dry solo, without the buses it sends to (the s shows d). right-click an s for those ( solo , solo just this one , dry solo, without its buses ), solo-safe (never silenced by another solo) (for a reverb bus; its s stays half lit), unsolo all and unmute all . studio > unsolo all and unmute all do the same. soloing a folder keeps the buses its tracks send to. solos are kept in the song but aren't undo steps (press the s again)."],["mixing--add-a-reverb-or-delay-on-a-bus-sends","Add a reverb or delay on a bus (sends)","Mixing","mixing.html","add a reverb or delay on a bus (sends) project > add track > group channel (bus) adds a bus (\"bus 1\"...); put a reverb or delay on it. then right-click a track > send to and pick the bus (or new bus... ; a bus already sent to is ticked, and picking it again removes the send), or use the + send button on its mixer strip. a new send starts at -10 db, with a level knob of its own. right-click a send's name > pre-fader (the fader doesn't change it) to make it independent of the track's fader (it shows \"(pre)\"), or remove send . each is one undo step. on the bus the effect should be all effect, no dry sound (the track's own dry sound is already in the mix): a built-in reverb or delay added to a bus starts that way (reverb's dry level all the way down, delay's mix at 100%), and convolution reverb starts fully wet anywhere. a third-party reverb on a bus: turn its mix fully wet."],["mixing--real-sounding-rooms-halls-and-plates-convolution-reverb","Real-sounding rooms, halls and plates (Convolution Reverb)","Mixing","mixing.html","real-sounding rooms, halls and plates (convolution reverb) add built-in > convolution reverb (on a bus, as above; it starts fully wet). space picks the room: small room, studio room (to start with), drum room, chamber, plate, short plate, concert hall or cathedral (or your own: own ir ). each is made from a room's size and shape (its early reflections) and how long it rings in the lows, mids and highs, and they're all levelled alike, so switching spaces changes the sound, not the volume. pre-delay (0 to 250 ms, 10 to start) holds the reverb back after the sound (clearer vocals), length (10 to 100%) shortens it with a smooth fade, low cut (20 hz to 1 khz, 80 to start) and high cut (1 to 20 khz, 12 to start) keep it out of the bass and take the fizz off, width (0 to 150%) narrows or widens it, mix sets wet against dry (lower it when it's on a track itself). load ir... uses an impulse response of your own (wav or aiff): a recording of a real room, hall, plate or spring (free ones are online; check each one's licence). it adds no latency, so it can be on a track you're recording through."],["mixing--make-a-knob-move-by-itself-modulators-lfo-envelope-follower-steps","Make a knob move by itself (modulators: LFO, envelope follower, steps...)","Mixing","mixing.html","make a knob move by itself (modulators: lfo, envelope follower, steps...) right-click any knob (a plugin setting, a fader's pan, a send in the mixer) > modulate with > new lfo on <track> (or envelope follower, steps, random, shape), or tick one the song already has. window > panels > modulators (or the track header's menu > modulators... ) opens a window with the selected track's: a card for each ( + lfo , + envelope , + steps , + random , + shape add more), its settings, and what it moves, each with an amount (-100 to 100 %: how far at its full swing; negative turns it down; +30% to start, -50% for an envelope follower). + target... adds something more for it to move, on any track. adding, ticking and removing are undo steps. lfo : a wave (sine, triangle, saw up, saw down, square, 4 or 8 steps up or down, random, noise). sync type transport and rate type a note value (1/8 to start, 1/4 t...) keep it in time with the song; free uses rate in hz. envelope follower : follows how loud its own track is. on the vocal, with the guitars' reverb send as a target at a negative amount, the reverb ducks while the vocal sings and comes back between lines. gain (12 db to start) sets how readily it moves; attack and release (5 and 150 ms) how quickly; hold , depth , offset and its filters shape it further. steps : a pattern of 2 to 64 steps (8 sixteenths, rising, to start: click or drag the bars), in time with the song. random : a new value each step (1/8 to start), smoothed or not. shape : a shape over each cycle (a bar to start). a modulated knob shows a dot where the modulators have it now. modulators are kept in the song, and their own settings can be automated like any other (their lanes are \"lfo 1: rate\"...). x on a card takes one away; what it moved stays where it was."],["mixing--repeat-a-bar-of-automation-automation-that-loops","Repeat a bar of automation (automation that loops)","Mixing","mixing.html","repeat a bar of automation (automation that loops) draw the pattern in an automation lane over a bar (or any range), select that range (marquee), then right-click the lane > loop the range to the end of the song : the pattern repeats from the range's end to the song's end (where its last clip ends), replacing what was there; the status line says how many times. it's greyed without a range, or when the range reaches the end already. one undo takes it back. (for a pattern that stays editable in one place, use a steps or shape modulator instead.)"],["mixing--a-few-big-knobs-that-move-several-settings-at-once-smart-controls","A few big knobs that move several settings at once (Smart Controls)","Mixing","mixing.html","a few big knobs that move several settings at once (smart controls) select a track and press b ( window > panels > smart controls , or the track header's menu > smart controls... ; a window of its own). set up knobs adds ones to start with for what's on the track (audio and instrument tracks): drive and tone for the amp or a capture player (drive turns the gain up and pulls the treble and level back, so it gets dirtier, not just louder), boost for an overdrive, fuzz for a fuzz, movement for a tremolo, auto-pan, flanger, auto-filter, chorus or phaser, tune for live tune, squash for the compressor (it compresses harder and makes up for it, so it gets denser, not quieter), brightness for an eq (its high shelf), the synth or the sampler (its filter), warmth for the saturator, punch for the transient shaper, de-ess for the de-esser, thickness for the doubler, echo for the delay (more of it, and longer), room for the reverb, filter for low and high pass, space for the first send, and on every track level (6 db down to 6 up). drive, squash, space and the other \"more of it\" knobs start at 0; tone, brightness, punch, filter and level in the middle, where they change nothing. one undo step. it measures what the track plays to work out how much drive and squash make up, so turned all the way up the track stays about as loud (squash too with the compressor's mix below 100 %, where its make-up is only partly heard): a few seconds for a long track. or + knob for your own (up to eight; double-click its name to rename it). click a knob to see what it moves: each setting with where the knob at 0 and at 100 puts it (drag or type them; at 100 lower than at 0 turns it down as the knob goes up). add setting... gives it something else to move: any of the track's plugin settings, its fader, pan or sends; the x takes one off. a knob is automated like any setting (its lane is \"smart control: drive\"), and right-clicking it maps it to a controller knob (midi learn). they're kept in the song and in track templates. the settings' own knobs still work: the knob's range moves with them."],["mixing--move-several-faders-together-vca","Move several faders together (VCA)","Mixing","mixing.html","move several faders together (vca) select tracks and choose project > group > group into vca (or right-click > group selected tracks into vca ). the vca's fader turns all of them up or down by the same db while their own faders stay where they are, and its mute mutes them all (all the way down silences them; vcas inside vcas add up). post-fader sends follow it, pre-fader ones don't. each track keeps its own output. drag a track out of the vca to free it; right-click the vca > ungroup vca removes it and leaves the tracks where they are. one undo step each."],["mixing--move-selected-tracks-faders-pans-mutes-and-sends-together-linked-channels","Move selected tracks' faders, pans, mutes and sends together (linked channels)","Mixing","mixing.html","move selected tracks' faders, pans, mutes and sends together (linked channels) select several tracks ( ctrl cmd -click or shift -click their headers or mixer strips), then move one's fader: the others move by the same db, keeping their balance. their pans move by the same amount, a mute mutes them all, and a send moves the same bus's send on the others (on tracks that have one). it works while they're selected (on any of them: move one that isn't selected and only it moves); solos aren't linked. no vca to make. studio > link selected channels turns it off (and on again); on to start with, kept with the song."],["mixing--compare-versions-of-a-mix-mixer-snapshots","Compare versions of a mix (mixer snapshots)","Mixing","mixing.html","compare versions of a mix (mixer snapshots) studio > save mix snapshot... keeps the mix as it is under a name (\"vocal up\", \"less verb\"; \"mix 1\" to start; a name you've used replaces that one): every track's and the master's fader, pan, mute, solo, sends and plugin settings, bypasses included. studio > mix snapshots lists them with when each was saved: choosing one puts that mix back (one undo step), on the tracks and plugins still in the song (it says which aren't). a plugin removed since isn't put back, and one added since is left as it is; a third-party plugin's settings may not undo. the mix you had before is kept as \"before recalling\", so you can go straight back. the song's clips and arrangement don't change (for the whole song, use file > project history... snapshots). delete a snapshot takes one away. they're kept in the song."],["mixing--give-the-mix-an-analog-desk-s-sound-console-mode","Give the mix an analog desk's sound (Console Mode)","Mixing","mixing.html","give the mix an analog desk's sound (console mode) studio > console mode puts a console on every track, folder and bus and first on the master: the gentle saturation an analog desk adds to each channel and the mix, rounding off peaks and adding a little warmth, louder signals more, quiet ones left as they are. each console sits last before the fader, adds no delay, and its drive (0 to 100%, 30 at first; 0 leaves the sound alone) sets how much. studio > console mode again takes them all off, with the drives you set. tracks added afterwards don't get one: switch it off and on (every drive goes back to 30%). one undo step."],["mixing--add-plugins-to-a-track","Add plugins to a track","Mixing","mixing.html","add plugins to a track click the + in a track's plugin slots (in the header or the mixer strip) and choose from built-in or plugins (your scanned effect plugins, by maker; scan for plugins... at the bottom). your favourites and the plugins you added lately ( recent , the last eight) are at the top of that menu: right-click a slot > add to favourites to put one there ( remove from favourites takes it off). click a plugin's slot to open its window. the light at the left of a slot says whether the plugin is on: green on, red off (bypassed); click the light to switch it (one undo step), in the track headers, the mixer and a split's paths alike. drag a slot to another place to change the order, or onto another track's slots (in the headers or the mixer) to move it there; hold alt option as you let go to copy it, its settings with it. one undo step each. an effect dropped above a track's instrument goes just after it (before it, it'd get no sound). (the master's and a split's plugins stay where they are.) right-click a slot for open , add to favourites , bypass / turn on , load preset , compare: switch to b and copy a to b (a/b), sidechain from (plugins with a sidechain input), save preset... , run in its own process (third-party plugins), reload (after a crash) and remove . favourites and recent are kept with take 5, for every song. in a short track, ctrl+↓ cmd+↓ makes room. in the mixer, a strip with more plugins than fit shows \"n more\"."],["mixing--add-a-channel-strip-gate-eq-compressor","Add a channel strip (gate, EQ, compressor)","Mixing","mixing.html","add a channel strip (gate, eq, compressor) select a track and choose studio > add channel strip , or the + slot > built-in > channel strip (gate, eq, compressor) : a gate (its threshold low, at -60 db, so nothing's cut until you raise it), eq and compressor go in before the fader, each with its own window (one undo step). click a slot to open its window: set the gate's threshold to shut out noise between notes, shape the tone with the eq's handles, and even out the level with the compressor's threshold, ratio and makeup."],["mixing--know-the-built-in-effects","Know the built-in effects","Mixing","mixing.html","know the built-in effects the + slot > built-in menu, grouped: guitar and bass : amp (clean, crunch, high gain and bass voicings, gain, bass, mid, treble and presence 0-10, level, a cabinet (4x12 british, 2x12 american, 1x12 open back, 4x10 bass, off) or your own impulse response with load ir... ), capture player (nam captures of real amps, pedals and rigs: see \"play a real amp or pedal (nam captures and tone3000)\"), overdrive (a tight boost: put it before the amp to tighten a high-gain palm mute; tight cuts the lows before it clips), fuzz (fuzz, tone from dark to bright, level), octaver (one or two octaves below a single note, as an analogue octave pedal does, mixed with the dry sound), pitch shifter (up or down by up to 24 semitones: an octave down for a bass line), hardware insert. tone : eq (drag the numbered handles on its curve), dynamic eq (bands that cut or boost only while their part of the spectrum is loud), saturator, low and high pass. dynamics : compressor (threshold, ratio, knee, attack, release, makeup, with a gain-reduction meter, sidechain, and mix for parallel compression), multiband compressor (2-4 bands, each compressed on its own), gate (threshold, range, attack, hold, release), transient shaper (attack and sustain up or down), limiter (gain, ceiling -1 db to start, release, true or sample peaks: for the master), drum enhancer (a recorded kit made bigger in a few knobs, on the drum bus or one mic: punch sharpens the hits and blends a squashed copy under them, clarity brings up the attack's presence and takes out the boxy low mids, weight adds lows and a sub under the kick, room a small room, glue a bus compressor, mix ; presets for rock, metal, pop and jazz kits). vocals : de-esser (frequency, threshold, range; split-band or wideband; listen to the esses alone), level rider (evens out a vocal before the compressor: target, range, speed and a floor below which it leaves breaths alone), doubler (mix, width, detune, delay), live tune (pitch correction as it plays: key and scale, speed (0 is the robotic, hard-tuned sound) and amount; put it on the armed vocal track to hear yourself in tune while recording), vocal polish (a finished vocal in a few knobs instead of a chain: clean takes out rumble and mud, even compresses the loud and quiet words together, air lifts the top and keeps its esses down, presence brings the words forward, space a plate and a short slap echo, mix ; presets for a pop or rock lead, backing vocals and speech). space and movement : reverb, convolution reverb (rooms, halls, plates, or your own impulse response), delay (tempo-synced note values, dotted and triplet, or milliseconds; feedback, mix 30% to start, 100% on a bus; high cut, ping-pong), chorus (rate, depth, width, mix), phaser (rate, depth in octaves, feedback), flanger, tremolo, auto-pan and auto-filter (a filter swept by an lfo, or by how hard you play: the auto-wah), 3d panner (around the listener in 3d, for headphones), shimmer (a long reverb whose tail rises an octave, or an octave and a fifth, or a fifth, and feeds back into itself, for ambient guitar and pads: size , decay , shimmer (how much rises), pitch , damping , modulation , mix ), echo (a delay with tape's character: in time with the song or in milliseconds, feedback , mix , ping-pong , wobble (wow and flutter), drive (grit on the repeats), low cut and high cut on the repeats, and ducking , which keeps the repeats down while you play and lets them come up in the gaps) and underwater (a muffled, swimming filter for drops and intros: depth and mix ). shimmer, echo, underwater, the drum enhancer and vocal polish come with presets: the slot's menu > presets . tremolo, auto-pan, flanger and auto-filter follow the song when sync is a note value (1/4, 1/8, 1/8 t...), pulsing on the beat from wherever it plays; free uses rate in hz. plus channel strip (gate, eq, compressor) and split (paths side by side: parallel, by frequency, mid/side) . (the console from console mode isn't in the menu.)"],["mixing--play-a-real-amp-or-pedal-nam-captures-and-tone3000","Play a real amp or pedal (NAM captures and TONE3000)","Mixing","mixing.html","play a real amp or pedal (nam captures and tone3000) add built-in > capture player to a guitar or bass track (where the amp would go). it plays nam captures (.nam files, a1 and a2 models): real amps, pedals and whole rigs captured with neural amp modeler. load capture... lists the ones already on this computer, the last used first, with a search box (type part of a name or a maker; return or a click loads it): every one you've loaded or downloaded from tone3000, the ones in any song's captures folder, and the ones in folders you add with add folder... ( folders shows them; click one to stop listing it). other file... loads one from anywhere, and it's listed from then on. a capture loaded from elsewhere is copied into the song's captures folder, so it goes wherever the song goes. tone3000 reaches tone3000 (tone3000.com), the free library of thousands of them: the first time, choose set the tone3000 key... : sign in on tone3000.com, make a key in settings > api keys (it starts t3k_pub_), and paste it in. it's kept in take 5's settings. tone3000 > pick a tone on tone3000... opens tone3000's catalog in your browser (signing you in the first time): pick a tone and it comes back into take 5, downloaded into the song's captures folder. a tone with several models (gain settings, mics) offers the others in a menu. it plays at once. an amp head captured without its speaker gets a cabinet ( cabinet : one of the amp's, or your own ir with load ir... , listed and copied into the song the same way); an ir tone from tone3000 becomes the cabinet. input (±24 db) drives it harder, gate (off to start) shuts out hum between notes, tone tilts it darker or brighter, output sets its level (captures are brought to about the same loudness first). only mono captures load; one made at another sample rate is converted (adding a little delay). pick a tone and copying into captures need the song saved first. each load is one undo step. the song opens with its captures without the internet. a song package (share) carries your own .nam files, but a tone3000 capture only as its link (its licence lets it be used, not passed on): on a bandmate's computer tone3000 > get it again fetches it. set up knobs gives it drive and tone. ask the assistant for a tone from your tone3000 favourites, downloads or the trending ones, and it can load it; tone3000's free api doesn't let it search the whole library, so for anything else pick it in tone3000's own catalog."],["mixing--use-built-in-plugin-windows","Use built-in plugin windows","Mixing","mixing.html","use built-in plugin windows in a built-in plugin's window, drag a knob up or down (or sideways) to turn it ( shift -drag: in fine steps), double-click or alt option -click it to go back to its default, and type a value in the box under it (or ctrl cmd -click). the power button bypasses the plugin (grey when off), and a and b at the top left compare two settings (see \"compare two settings of a plugin\"). right-click a knob for midi learn... and modulate with . some controls (model, cabinet, note value) are menus. each move is one undo step. in the eq, drag a numbered handle for that band's frequency and gain (shift: frequency only), scroll over it for its width ( q ), and double-click it to put its gain back to 0 db. plugins with bands (the multiband compressor, the dynamic eq) show a row per band; bands not in use are faint."],["mixing--squash-only-the-part-of-the-sound-that-s-too-loud-multiband-compressor-dynamic-eq","Squash only the part of the sound that's too loud (Multiband Compressor, Dynamic EQ)","Mixing","mixing.html","squash only the part of the sound that's too loud (multiband compressor, dynamic eq) for palm mutes that boom, a bass whose low end jumps around, or cymbals that get harsh, use the + slot > built-in : multiband compressor : the sound is split into 2-4 bands ( bands , with split 1-3 where they meet) and each band has its own threshold, ratio, attack, release and gain; each row shows how much its band is being turned down. it starts with 3 bands split at 150 hz and 2.5 khz, each at -24 db, 3:1. listen plays one band alone while you set it. with nothing over the thresholds, it leaves the sound as it was. no added delay. dynamic eq : four bands (low shelf, bell or high shelf, or off), each with a frequency and q, that move only while that part of the spectrum is over its threshold , by the ratio , up to the range (below 0 cuts, above 0 boosts). two start on: 250 hz for low-mid boom and 3.5 khz for harshness. listens to: sidechain makes a band follow another track instead (right-click the slot > sidechain from ): a vocal carving its own room in the guitars. the curve shows how far each band can go, and where they all are as it plays."],["mixing--process-parts-of-the-sound-separately-split","Process parts of the sound separately (Split)","Mixing","mixing.html","process parts of the sound separately (split) the + slot > built-in > split puts paths side by side in one slot, each with plugins of its own (two to start), then mixes them back together. a split can't go inside a split. in its window, split by : nothing (the whole sound to each path) : every path gets the whole sound (parallel processing): a clean and a distorted bass, or a squashed copy of the drums under the drums. 2-4 paths; two paths are 6 db louder than one, so turn one down. frequency : each path gets a band (2-4, with split 1-3 where they meet), and the bands add back up to the sound as it was: distort the bass's highs and keep its lows clean. mid and side : the mid (what's the same on both sides) and the side (what's different) each get a path, then are put back: widen only the sides, or eq the middle on its own. left and right : one path each. fewer paths (or bands) removes the last ones with their plugins. each path has a level knob (-60 to +12 db, automatable), m (mute) and s (solo, to hear one band), and its plugins: + adds one, click opens it, right-click for the same menu as a track's slots. plugins in a path are automated, midi-learned and mapped to smart controls like any other, and plugins with latency stay lined up with the other paths. save the whole split (paths and plugins) with save preset... ; it's kept in track templates, and a copied track gets a split of its own."],["mixing--compare-two-settings-of-a-plugin-a-b","Compare two settings of a plugin (A/B)","Mixing","mixing.html","compare two settings of a plugin (a/b) every plugin has two sets of settings to switch between while you set it up: in a built-in plugin's window, a and b at the top left are the two sets, the one playing lit: click b to switch to it (the first time, b starts as a copy of a, so change it from there) and a to go back; copy to b (or copy to a ) copies the set you're on to the other. for an installed plugin, right-click its slot > compare: switch to b and compare: copy a to b . each switch is an undo step (undoing one puts the settings back, though the button stays where it is); copying isn't. the other set is kept while the song is open, not in the song."],["mixing--duck-the-bass-with-the-kick-sidechain","Duck the bass with the kick (sidechain)","Mixing","mixing.html","duck the bass with the kick (sidechain) put a compressor (or another plugin with a sidechain input) on the bass, right-click its slot > sidechain from and choose the kick track. the kick now drives the compressor, ducking the bass on every hit. the list has every audio and instrument track but its own; the choice is kept with the song (one undo step). none turns it off. plugins inside a split's paths can't be sidechained."],["mixing--automate-volume-pan-or-a-plugin","Automate volume, pan or a plugin","Mixing","mixing.html","automate volume, pan or a plugin click a track's a button to show its automation lanes: one for each setting already automated, and one more whose drop-down picks any setting (volume to start). to find what's already automated, press a ( project > automation > next track with automation , or the a button under the track headers): it scrolls to the next track that has any automation and opens its lanes, the status line naming what's automated; again goes on to the one after, shift+a back. while a track's automation is showing, touch any of its knobs or faders (in a plugin window, the mixer or the header; a third-party plugin's own knobs while its window is in front) and the lane shows that one, ready to draw; project > automation > automate last touched control , alt+a option+a , opens the lane for the last one you touched even when the lanes are hidden. click in a lane to add a point (on the grid), drag points ( ctrl cmd , ignores the grid), right-click or alt option -click a point to delete it. pick another parameter, including any plugin knob or send level, from the bottom lane's drop-down; clear in a lane's header deletes all of that setting's automation (one undo step). the mode box (the track's, read to start with) sets read (play back), touch (record while you hold a control, then return to what was there), latch (record from the first move until stop) or write (from play, every automated setting is written as it is, touched or not; then the track goes to latch). ride a fader or plugin knob while playing to record it. the header's r and w , and the console layout's toolbar r and w (every track), set read and touch."],["mixing--draw-automation-shapes-over-a-range","Draw automation shapes over a range","Mixing","mixing.html","draw automation shapes over a range select a marquee range (or clips), show the automation ( a ), right-click the lane > draw shape (greyed without a range): fade in, fade out, swell, duck or sine (once a beat), just in that range. reverse and invert work on the range (or the whole lane with none), loop the range to the end of the song repeats it, and copy lane to track puts the same automation on another track's matching parameter. with edit > automation follows events on (off to start, kept with the song), moving a clip takes the automation under it along."],["mixing--send-a-track-to-another-output","Send a track to another output","Mixing","mixing.html","send a track to another output right-click a track > output > an output pair (or master , the main mix), or choose it in the inspector's output . turn on more outputs in edit > audio settings... first (the menu says so while there's only one pair). kept with the song; one undo step. folders have no output of their own. useful for outboard summing, a separate headphone feed or a second set of speakers."],["mixing--compare-my-mix-with-a-reference-track","Compare my mix with a reference track","Mixing","mixing.html","compare my mix with a reference track studio > reference track > choose reference track... and pick a finished song: its loudness and the whole mix's are measured. then studio > reference track > listen to reference (a/b) , alt+r option+r , or mix / ref on the master strip, switches between your mix and the reference at the same place in the song (the button then reads reference , and the loudness readout and analyser measure the reference). with match reference loudness on (it is to start with), the reference is turned down or up (by up to 12 db) to the mix's loudness, so louder doesn't sound better; the mix itself is never changed; measure mix loudness again after changing the mix. the reference also shows as a lane above the tracks (its waveform from the start of the song, its name in the header): click the lane to switch between it and the mix ( project > reference track lane , alt+shift+g shift+option+g , hides it). with no reference chosen the lane is empty and says so: double-click it to choose one. remove reference track stops using it. the reference never goes into an export. a reference file inside the song's folder is kept by where it is in the folder, so it's found when the song moves to another computer; one elsewhere isn't copied into the song (put it in the song's folder to take it along)."],["mixing--check-the-mix-in-mono-at-low-volume-and-on-the-analyser","Check the mix in mono, at low volume, and on the analyser","Mixing","mixing.html","check the mix in mono, at low volume, and on the analyser studio > mono (or mono on the master strip): hear the mix summed to mono. studio > dim (or dim ): 20 db quieter. studio > master off (matched loudness) (or master off ): see below. studio > analyser : the mix before mono, dim and the listen bus, with the stereo correlation (-1 to +1, red below 0: parts cancelling in mono) under one of four views, chosen at its top right: spectrum (bass on the left), spectrogram (the spectrum over the last seconds, louder brighter, the newest at the right), vectorscope (where the stereo sits: mono is a line up the middle, wide stereo a round cloud, something out of phase a line across) and level history (the level over the last minute, to see a chorus that doesn't lift). it needs the song playing. the loudness readout in the transport bar shows lufs short (the last 3 seconds), lufs int (integrated) and the true peak (red at -1 dbtp or above), with the click when it's on; click it to reset. none of these change an export. mono and dim are for this session only (not saved)."],["mixing--correct-my-room-or-headphones-the-listen-bus","Correct my room or headphones (the listen bus)","Mixing","mixing.html","correct my room or headphones (the listen bus) studio > listen bus... (or listen on the mixer's master strip) holds plugins that only change what you hear from the speakers or headphones, such as room or headphone correction software. + plugin adds one from your scanned third-party plugins (each in its own process), on switches it off to compare, edit opens its window and x takes it off. they come after everything else (mono, dim, the reference) and are never in an export, a bounce or a freeze; the meters show the mix without them. they're kept for this computer, not the song, with their settings. listen on the master strip is lit while one is on; the toolbar's l opens it too. it's on the main outputs only: a headphone mix or a track sent to another output doesn't go through it."],["mixing--hear-what-the-master-s-plugins-do-master-off","Hear what the master's plugins do (Master Off)","Mixing","mixing.html","hear what the master's plugins do (master off) studio > master off (matched loudness) , alt+m option+m , or master off on the master strip plays the mix without the plugins on the master (eq, compressor, limiter, whatever's there), turned up or down to the loudness it has through them. so you hear what the master does to the sound, not just that it's louder. the first time, and after any change to the song, it renders the mix twice to measure the loudness (over the loop if looping, else the whole song), which takes a few seconds; the status line says how much it turned the mix by. press it again for the master back. it changes only what you hear (the click too): exports, the assistant's analysis and the saved song keep the master, and there's nothing to undo. a plugin added to the master while it's on isn't bypassed: switch it off and on again. with no plugins on the master it has nothing to do (and says so); it matches by up to 24 db."],["mixing--bounce-a-track-to-audio-bounce-in-place","Bounce a track to audio (Bounce in Place)","Mixing","mixing.html","bounce a track to audio (bounce in place) select tracks and choose audio > bounce selection ( ctrl+b control+b ), or right-click a track > bounce selection : what they play, effects and all (their tails too), becomes a 24-bit wav in the song's audio folder on new tracks, with the originals' fader, pan and sends, and the originals are muted. with a marquee range, audio > bounce selection (or bounce range in place ) does just those bars: the original's clips are cut at the range's edges and muted only inside it. one undo step."],["plugins--find-my-installed-plugins-scan","Find my installed plugins (scan)","Plugins","mixing.html","find my installed plugins (scan) studio > plug-in manager... opens the plugins window: scan for plugins looks for installed plugins of every format at once, where they're usually installed: vst3, audio units and clap (the clap folders in library/audio/plug-ins); vst3 and clap on windows (from c:\\program files\\common files\\vst3 and the common files\\clap folders). options... beside it scans one format or a folder of your own. the scan runs in helper processes, so a plugin that crashes while being scanned doesn't take take 5 with it. after scanning, effects appear under plugins in the + slot menu and instruments under track > new instrument track... > plugins . scan for plugins... at the bottom of the + slot menu opens the window and starts the same scan."],["plugins--save-and-load-plugin-presets","Save and load plugin presets","Plugins","mixing.html","save and load plugin presets right-click a plugin's slot > save preset... and give it a name; load preset lists the saved ones for that plugin. works for built-in and third-party plugins, on top of the plugin's own presets. presets are kept in take 5's settings folder, so they're there in every song (a plugin's vst3 and au copies have their own lists). load preset is greyed while there are none. a split's preset keeps its paths and their plugins. to save a whole track's plugins and settings at once, use right-click the track > save as track template... ."],["plugins--a-plugin-crashed-amber-light-with-a","A plugin crashed (amber light with a !)","Plugins","mixing.html","a plugin crashed (amber light with a !) every third-party plugin runs in a helper process of its own (\"take 5 plugin host\"), so when one crashes or hangs, the song keeps playing: the plugin's light turns amber with a \"!\", audio passes straight through it, and a message says what happened. click the slot to reload it with its last settings, kept up to date in the background (or right-click > reload (it crashed) ). edit > preferences... > plug-ins > run plugins in their own processes (on to start with) turns this off for all plugins (they then load inside take 5, and the song's plugins reload); right-click a third-party plugin's slot > run in its own process sets it for that plugin, wherever it's used (kept with take 5). plugins with ara (the ones that work on clips themselves, see \"edit a vocal note by note, or a clip's sound, in an ara plugin\") are the exception: ara only works inside take 5, so they always run there, and their slot menu says \"runs inside take 5 (an ara plugin, which has to)\". if one of them crashes, take 5 closes with it (see \"recover after a crash\": your work since the last save comes back)."],["plugins--use-intel-only-plugins-on-an-apple-silicon-mac","Use Intel-only plugins on an Apple silicon Mac","Plugins","mixing.html","use intel-only plugins on an apple silicon mac intel-only plugins run under rosetta in their own helper process: they're found by the scan and work like any other. their slot menu says \"runs under rosetta (an intel-only plugin)\", and they always run in their own process (they need the take 5 plugin host that comes with take 5). rosetta must be installed: macos offers it the first time an intel app runs, or type softwareupdate --install-rosetta in terminal. without it, a scan skips intel-only plugins and says which ones when it's done, and clicking one already in a song says why it can't open (scan again once rosetta's installed). macos 28 doesn't run intel code, so these plugins stop working when you update to it. on macos 27 a scan that finds an intel-only plugin says so, and its slot menu says \"macos 28 won't run it\": ask the plugin's maker for an apple silicon or universal version before updating. (macos itself may warn that take 5 \"includes a component that will not open in macos 28\": that's the helper's intel half, which only intel-only plugins use; take 5 itself runs on.)"],["plugins--edit-a-vocal-note-by-note-or-a-clip-s-sound-in-an-ara-plugin","Edit a vocal note by note, or a clip's sound, in an ARA plugin","Plugins","mixing.html","edit a vocal note by note, or a clip's sound, in an ara plugin some plugins work on the recording itself rather than on the sound of a track as it plays: vocal editors that show every note of a take to move and reshape, spectral editors that take a cough out of a take, tools that line one take up with another. they use ara, which lets the plugin read the whole clip from take 5 and play it back as edited. install the plugin (vst3 or audio unit) and let settings > plugins... scan it; then right-click the audio clip > ara > edit in <the plugin>. to do several clips at once (a whole vocal comp, every take of a part), select them first and right-click one of them. the first time you use a plugin, take 5 says plainly that it runs inside take 5 (ara only works that way, unlike every other plugin, which runs in a process of its own): if it crashes, take 5 closes with it, so save first. use it goes on. the plugin's window opens, showing the clip (its notes, or its waveform or spectrum) to edit there; the clip plays as edited, and its name strip says \"ara\" and the plugin's name. the edits are kept in the song: saved, opened again, undone and redone with it. right-click the clip > ara : open <the plugin> window : its window again, on this clip. render edits to a new file : the clip as the plugin plays it, its gain and fades included, made into a new audio file in the song's audio folder (\"<clip> (edited).wav\"), in place of the clip. it's a plain clip after that: it plays on a computer without the plugin, goes into a song package for bandmates, and can't be lost if the plugin isn't there one day. undo brings the plugin and its edits back. do it when the edits are done. stop using <the plugin>: the clip plays its own audio again, without the edits (undo brings them back). ara lists only plugins that have it; \"no ara plugins found\" means none was found by the last scan. intel-only ones can't be used this way on an apple silicon mac (they can't run inside take 5). while a clip is in an ara plugin, its stretch mode is the plugin's (it does the time-stretching and tuning, if it can); stopping puts back the one it had. rendering a mix or the song through a clip in an ara plugin tells the plugin it's not playing live, so it takes the time it needs."],["plugins--put-an-effect-on-one-clip-only-clip-effects","Put an effect on one clip only (clip effects)","Plugins","mixing.html","put an effect on one clip only (clip effects) for a reverb or echo throw on one word, de-essing one line, or another amp on one part, without automating the whole track: right-click the audio clip > clip effects > add an effect... and pick it, as for a track. it plays on that clip's audio only, before the track's own effects, and goes with the clip when it's moved, copied or split. clip effects lists the clip's effects: each has open , bypass and remove (the menu reads \"clip effects (2)\" with two). a clip with effects says \"fx 1\" (how many) on its name strip. the clip's fades are on its audio, before its effects, so a reverb or delay on it rings on past the clip's end."],["plugins--render-a-clip-s-effects-into-it-and-take-the-render-back","Render a clip's effects into it, and take the render back","Plugins","mixing.html","render a clip's effects into it, and take the render back right-click a clip with effects > clip effects > render into the clip : the clip as it plays, its effects included (a reverb's tail too: the clip gets longer by as much as it rings on, up to 4 seconds and the next clip on the track), becomes a new file in the song's audio folder and a plain clip in its place (\"rendered\" on its name strip). it saves cpu, and frees the effect to edit the audio further. clip effects > take back the render puts the clip back as it was, its effects playing live again, at any time, even after saving and reopening. one undo step each."],["plugins--use-outboard-gear-on-a-track-hardware-insert","Use outboard gear on a track (Hardware Insert)","Plugins","mixing.html","use outboard gear on a track (hardware insert) add built-in > guitar and bass > hardware insert to a track. choose the interface output your pedal or outboard unit is connected to and the input it comes back on (it starts on the second output and the last input; with one output it waits for you to choose, so nothing feeds back), and press measure so it stays in time with the other tracks: it plays clicks out and listens for them, so turn the gear's output down or measure with a cable first. the result (in ms and samples) is kept with the song. the track then plays through the gear; bypassing the insert plays it dry."],["finishing-and-exporting--export-the-mix-as-wav-mp3-or-flac","Export the mix as WAV, MP3 or FLAC","Finishing and exporting","finishing-and-sharing.html","export the mix as wav, mp3 or flac file > export > audio mixdown... , with export set to the mix (one file) : formats : tick one or more of wav (ticked to start with), aiff, flac and mp3: a file of each. quality : 16 or 24-bit (24 to start) for wav, aiff and flac; for mp3, 128, 192, 256 or 320 kbit/s (320 to start; constant bit rate, 16-bit). sample rate : 44.1, 48, 88.2 or 96 khz (the audio interface's rate to start with). an mp3 can't be 88.2 or 96: it's written at 44.1 or 48. range : whole song , or loop range (greyed until there's one: drag in the ruler). the whole song goes on past the last clip while reverbs and delays ring on, until they've died away (10 seconds at most); a loop range stops at its end. loudness : as mixed , or a target (see \"export at a loudness target for streaming\"). mp3 tags : title (the song's name to start with), artist, album and year, for an mp3. the artist is remembered for every song; the rest goes back to how it was each time. audio mixdown... asks where (the song's folder, \"<song>.wav\"); each other format gets the same name with its own extension, replacing a file of that name without asking. the export respects mute and solo, has every plugin on (even in low-latency mode), is always stereo, and leaves out the click, the reference, mono, dim, master off and the listen bus. the export window shows each file as it's written with a progress bar and cancel (which deletes the file being written). when it's done it says export finished , with the integrated loudness, true peak and loudness range of the first file that isn't an mp3: open in finder ( open in explorer on windows) opens the folder with the file selected, close window closes it. mp3 works out of the box and windows: the encoder is built in."],["finishing-and-exporting--export-at-a-loudness-target-for-streaming","Export at a loudness target for streaming","Finishing and exporting","finishing-and-sharing.html","export at a loudness target for streaming in file > export > audio mixdown... , set the loudness to -14 lufs (streaming) , -16 lufs (podcasts, gentler) or -23 lufs (broadcast) instead of as mixed . the export is turned up or down to that loudness (one change of level, no limiting), but never so far that its true peak goes over -1 dbtp: a mix with loud peaks comes out quieter than the target (check the loudness the finished window shows). for a louder master, put the limiter on the master and push its gain while watching the true peak reading in the transport bar. with each section , each file is brought to the target on its own. stems keep their balance: loudness is greyed for them."],["finishing-and-exporting--start-a-master-from-a-ready-made-chain-mastering-chain","Start a master from a ready-made chain (Mastering Chain)","Finishing and exporting","finishing-and-sharing.html","start a master from a ready-made chain (mastering chain) on the master's + slot > built-in > mastering chain , pick one, and its plugins go on the master in order, already set: an eq (small moves), a gentle compressor (glue, not squash), for some a little saturator, and the limiter last. for where it's going : streaming (-14 lufs) (about as loud as streaming services play songs, the ceiling at -1 db for their encoders), loud , cd (up to -0.3 db) and podcast (-16 lufs) (speech clear and even). for its style : rock , metal , pop , acoustic and electronic . it's a starting point: listen, adjust, and turn the limiter's gain for how loud it should be (or ask the assistant to master it to a loudness, below). one undo takes the whole chain off."],["finishing-and-exporting--master-the-song-for-streaming-with-the-assistant","Master the song for streaming (with the assistant)","Finishing and exporting","finishing-and-sharing.html","master the song for streaming (with the assistant) ask the assistant: \"master this for streaming, punchy\", \"master it like the reference, -14 lufs\". it measures the mix (loudness, true peak, and the balance in third-octave bands, compared band by band with the reference track if you've chosen one, at matched loudness), sets up the master's eq, compressor and limiter from what it measured (a dynamic eq or multiband compressor for problems that come and go, a split by mid/side for width), then measures again and adjusts: within 0.5 lu of the target (-14 lufs unless you say another) with the true peak at or under -1 db. it's one request, so one undo, ctrl+z cmd+z , takes it all back. then use master off on the master strip ( studio > master off (matched loudness) ) to hear whether the master helps."],["finishing-and-exporting--export-stems","Export stems","Finishing and exporting","finishing-and-sharing.html","export stems in file > export > audio mixdown... , choose stems (one file per track, folder and bus) , then a folder: a \"<song> stems\" folder is made in it, with a file per top-level track, folder (everything in it) and bus, \"<song> - <track>.wav\" (and the other formats ticked). stems leave out their sends (those are in the bus stems) and the master's plugins and fader, so dropped into another music app at the same start they add up to the mix before the master. muted tracks get none; drum channels and tracks inside a vca get stems of their own. range applies (the whole song with its tail); loudness and the mp3 tags don't. when it's done it says how many files."],["finishing-and-exporting--export-each-section-as-its-own-file","Export each section as its own file","Finishing and exporting","finishing-and-sharing.html","export each section as its own file add section markers first, then in file > export > audio mixdown... choose each section (one file per section) (it says how many): one numbered file per section, from marker to marker (\"<song> - 1 verse.wav\"; \"01\", \"02\" with ten or more), in a \"<song> sections\" folder made in the folder you choose. anything before the first marker isn't in one; the last runs to the end of the last clip. range is greyed; a loudness target applies to each file; an mp3's title tag gets the section's name. the option is greyed out until the song has section markers (see \"add and name sections (intro, verse, chorus)\")."],["finishing-and-exporting--export-just-part-of-the-song","Export just part of the song","Finishing and exporting","finishing-and-sharing.html","export just part of the song set a loop range by dragging in the ruler and choose loop range in file > export > audio mixdown... . to save what each track plays in a marquee range as separate files, use file > export > export range as wav... (greyed without a marquee range): a 24-bit wav per track, through its effects or instrument and with their tails, but at an even level (no fader, pan, sends or master), named \"<track> <start>-<end>.wav\" by bar and beat, in the song's exports folder to start with (one track asks for a file, several for a folder)."],["finishing-and-exporting--make-a-video-of-the-song-for-social-media","Make a video of the song for social media","Finishing and exporting","finishing-and-sharing.html","make a video of the song for social media file > export > export video... makes a video to post: the song's mix as its sound, and a picture that moves with the music. in the window: part of the song : the whole song, the loop (if one's set), or a section by its marker (a chorus is often enough for a reel; most sites take up to a minute or 90 seconds). shape : 9:16 tall for stories, reels and shorts (1080 x 1920), 1:1 square for a feed (1080 x 1080) or 16:9 wide for youtube (1920 x 1080); 30 frames a second, or 60 for smoother movement (a bigger file). moving with the music : bars (the spectrum, lows at the left), a waveform , or a ring . colours : the background and the bars' colour; picture... puts a photo behind it all (the band, the cover art), filling the shape and dimmed so the rest reads; no picture takes it away. song and band : the names at the top (the band's starts as your name from file > share with bandmates ). the lyrics, word by word : the lyrics lane's line being sung, its words lighting up as they go, the next line under it (see \"write lyrics along the song\"). the preview shows a frame; drag the slider under it to look through. audio mixdown... asks where to save the mp4 (the song's exports folder to start with) and renders it, with progress and stop : about as long as the part takes to play, or less. then it's shown in finder (explorer on windows), ready to send to your phone. the sound is the mix as file > export makes it (h.264 video, aac sound, which every phone and site plays)."],["finishing-and-exporting--write-music-to-a-video-video-in-the-song","Write music to a video (video in the song)","Finishing and exporting","finishing-and-sharing.html","write music to a video (video in the song) file > import video... puts a video (mp4 or mov: a band's live video, a short film, an advert) in the song, its first frame at the playhead, and opens the video window ( window > panels > video player , f8, also in view > panels ). the window shows the frame at the playhead as the song plays, or as you move the playhead, with the video's timecode (hours:minutes:seconds:frames) under it; before or after the video it says so. the video's sound arrives on a track of its own (\"<video> sound\"), lined up with the picture: a guide to play to, or the camera's sound to mix with the band's recordings. a song has one video: importing another replaces it (the first one's sound track stays). the video is kept with the song by where the file is (keep it inside the song's folder, so it goes wherever the song goes)."],["finishing-and-exporting--line-the-video-up-with-the-song","Line the video up with the song","Finishing and exporting","finishing-and-sharing.html","line the video up with the song in the video window ( window > panels > video player ), start at playhead moves the video so its first frame is at the playhead, its sound's clips moving with it: put the playhead on the bar the picture should start at. to start the song partway into the video, import it with the playhead at the song's start and then move the song's music later, or drag the sound's clip and press start at playhead with the playhead where the clip now starts. remove takes the video out of the song (its sound's track stays, to delete or keep). each of these is one undo step."],["finishing-and-exporting--put-markers-at-the-video-s-cuts","Put markers at the video's cuts","Finishing and exporting","finishing-and-sharing.html","put markers at the video's cuts in the video window, markers at cuts finds where the video cuts from one shot to another and puts a section marker at each (\"shot 2\", \"shot 3\"...), so you can write the music to the edit: the sections lane shows them, and project > arranger chains and the chord chart read them like any other markers. soft fades and dissolves aren't cuts and get no marker."],["finishing-and-exporting--set-the-song-s-timecode-start-at-01-00-00-00","Set the song's timecode (start at 01:00:00:00)","Finishing and exporting","finishing-and-sharing.html","set the song's timecode (start at 01:00:00:00) picture editors usually start a film or an advert at 01:00:00:00. to count the song the same way, press timecode... in the video window, type where the song's start is (hours:minutes:seconds:frames, like 01:00:00:00; for drop-frame rates, 00:59:59;29 also works) and choose the frame rate (23.976, 24, 25, 29.97, 29.97 drop-frame, 30, 50, 59.94, 59.94 drop-frame or 60 frames a second). the video window then shows the song's timecode on the left under the picture, beside the video's own, and an aaf exported from the song starts there. clear counts from 00:00:00:00 again. setting it is one undo step. an aaf imported from a session that started at a timecode sets it for you. to see it in the tracks, choose project > timecode in ruler : the song's timecode runs along the top of the ruler, above the bar numbers, closer together as you zoom in. without a timecode set, it counts from 00:00:00:00 at the video's frame rate (25 without a video)."],["finishing-and-exporting--export-the-video-with-your-mix","Export the video with your mix","Finishing and exporting","finishing-and-sharing.html","export the video with your mix in the video window, export with the mix... saves the video again (\"<video> (new mix).mp4\" beside it to start with) with the song's mix over the video's length as its sound, in place of what it had; the picture is unchanged. the mix is made first (as file > export makes it), then the video, with progress along the bottom of the frame; click the button again to stop. mute the video's own sound track first if it shouldn't be in the mix. then the file is shown in finder (explorer on windows)."],["finishing-and-exporting--put-songs-together-as-an-album-or-ep","Put songs together as an album or EP","Finishing and exporting","finishing-and-sharing.html","put songs together as an album or ep file > album... opens a window (choose it again to close it: an album not saved is gone): the album's title , artist and year , and its songs. add songs... adds songs (their .tracktionedit files) at the end; move up , move down and remove put them in order (each song's title is its file's name). for the selected song, then : a gap of some seconds (2 to start) before the next, or crossfade over some seconds into it (an even crossfade; the last song has neither); trim (db) , -24 to +12, turns it up or down by hand after matching. match to sets the loudness every song is brought to: -14 lufs (streaming) (to start with), -16 lufs (podcasts, gentler) , -11 lufs (loud) , -9 lufs (very loud) or off: as they're mixed . whatever the choice, no song goes over -1 db true peak: one that would is left a little quieter, and says so. measure shows each song's loudness now. render album... asks for a folder and writes 24-bit, 44.1 khz files there, replacing ones of the same name: a wav per song (\"01 hearts explode.wav\"...), matched, with its reverb's tail (up to 4 seconds, until it's silent), and its title, artist, album, year and track number in it; one wav of them all (\"<album>.wav\"), in order with the gaps and crossfades, with a marker where each song starts; a cue sheet (\"<album>.cue\") beside it, to burn a cd or for a distributor. then a box lists each song's loudness and true peak and the whole album's length. each song is rendered from its file, through its own master, so a change to a mix is in the next render (the open song is saved first if it's one of them). save... keeps the album as a .t5album file (it offers the folder your songs are in); open... brings it back. the album remembers where each song is: a song moved since shows red, \"(missing)\", and has to be added again."],["finishing-and-exporting--hand-a-song-to-another-music-app-dawproject","Hand a song to another music app (DAWproject)","Finishing and exporting","finishing-and-sharing.html","hand a song to another music app (dawproject) file > export > export dawproject... saves the song as a .dawproject file, the open format many music apps read: the tracks and folders (as submixes), buses (as effect channels), midi clips and their notes, audio clips (the audio files go inside it) with their fades, each channel's fader, pan, mute, solo and sends, the automation of faders, pans and sends, the section markers, and the tempo (its changes as tempo automation; only the starting time signature). it goes in the song's exports folder to start with. installed vst3 plugins go across with their settings (a few older ones by name only); clap and au plugins by name (load their settings again there); a bypassed plugin stays bypassed. the built-in eq and compressor become the other app's own; take 5's other effects and instruments (the amp, the delay...) can't go across, and are listed in each track's comment. every folder goes as a submix (a vca too). not carried: the master's plugins (its fader and pan are), clip gain, and looped audio clips; stretched or reversed clips go as recorded. afterwards take 5 says what didn't go across (\"exported, mostly\"). for an app that reads aaf but not dawproject (and video editors), export an aaf instead."],["finishing-and-exporting--export-an-aaf-session","Export an AAF session","Finishing and exporting","finishing-and-sharing.html","export an aaf session file > export > export aaf... writes the song as an aaf session: audio tracks with their clips, fades and crossfades, clip gain, volume, pan and the markers. it asks first where the audio goes: in the aaf or wav files beside it (a \"<name> audio\" folder, a mono wav per channel), then where to save (the song's exports folder to start with). clips an aaf can't describe (stretched, warped, reversed, looped, pitch-shifted, with envelopes or clip effects) go out rendered as they sound. midi, muted tracks and clips, plugins, sends and automation don't go, and the export says so, with how many tracks and clips went, and any track split in two (mono and stereo clips, or overlapping ones). it starts at 00:00:00:00 at 25 frames a second. a song imported from an aaf that started at a timecode starts there again. for midi parts, use file > export > export midi file... ."],["sharing-with-bandmates--let-a-bandmate-listen-and-comment-from-home-listen-together","Let a bandmate listen and comment from home (Listen Together)","Sharing with bandmates","finishing-and-sharing.html","let a bandmate listen and comment from home (listen together) transport > listen together... , start listening together : the window shows an address with a code (http://192.168.1.20:8790/?code=k7m2xq, say). send it to your bandmate; they open it in a browser and press listen , and hear what take 5 plays (the mix, as you hear it) a second or two behind. under it they can type their name and a comment (\"snare's too loud here\") and send at this moment : it lands in the song as a comment with their name, at the place they were hearing (on the sections lane; hover over its dot to read it), and the status line says so. the window shows how many are listening. stop listening together ends it; it keeps running with the window closed. only someone with the code can listen (a new one each time take 5 opens); after five wrong codes from one place, it isn't answered from there for a minute, so the code can't be guessed. up to eight can listen at once. on the same network (a bandmate in the next room, a phone) it works as it is. for someone elsewhere, your router has to pass the port the window shows (8790, say) on to this computer (\"port forwarding\" in the router's settings), and they use your internet address instead of the one shown. the delay makes it right for hearing a mix, not for playing along."],["sharing-with-bandmates--put-my-name-on-parts-and-comments","Put my name on parts and comments","Sharing with bandmates","finishing-and-sharing.html","put my name on parts and comments edit > preferences... > general > your name... : the name on the parts you send and the comments you write (\"alan: retake this bar\"). it starts as your computer account's first name. set it once on each computer (it's for every song), before you send parts or leave comments, so bandmates can see who played what. a changed version of a track you have arrives as an alternative named after them. changing it later doesn't change earlier comments or parts."],["sharing-with-bandmates--send-a-song-to-a-bandmate-song-package","Send a song to a bandmate (song package)","Sharing with bandmates","finishing-and-sharing.html","send a song to a bandmate (song package) file > share with bandmates > save song package... makes one .take5song file (on the desktop to start with) with the song as it is now (unsaved changes too) and only the files it uses: the audio of its clips and takes, sampler and drum kit samples, and the capture player's captures and cabinets (a tone3000 tone goes as a link, downloaded again at the other end). not the backups, snapshots or exports. up to 4 gb of audio: for more, send parts a few tracks at a time. send it any way you like. double-clicking it (or file > open... ) closes the song you have open (asking to save) and opens it as a song of its own in music/take 5 (\"<song> (2)\" if the name is taken), with its takes, drum kits and plugin settings. its third-party plugins have to be installed on that computer too."],["sharing-with-bandmates--work-on-a-song-through-a-shared-band-folder","Work on a song through a shared band folder","Sharing with bandmates","finishing-and-sharing.html","work on a song through a shared band folder on your computer: file > share with bandmates > share in band folder... and choose a folder your band shares (one a cloud or sync service keeps the same on everyone's computer). a folder named after the song appears there with the package (\"<song> - from <you> <date>.take5song\") and a parts folder. take 5 remembers the band folder for this song on this computer. a bandmate double-clicks the package there: it opens as their own copy, knowing the band folder (if they opened a copy from elsewhere, they choose it with share in band folder...). they record a part, then share with bandmates > send parts... : every track is listed, the new ones (not in the song when it was shared, sent or received) ticked and marked \"(new)\"; send to band folder (or save as a file... to send it another way). inputs aren't sent. take 5 checks the folder every 20 seconds or so (not while recording or while a window is asking something). when parts arrive, \"<name> sent <tracks> for <song>\" asks to import them, the oldest first: import , later (asked again next time the song opens) or don't import . nobody's song file is ever overwritten: only .take5song and .take5parts files go in the shared folder, and sharing again adds another package."],["sharing-with-bandmates--import-parts-a-bandmate-sent","Import parts a bandmate sent","Sharing with bandmates","finishing-and-sharing.html","import parts a bandmate sent double-click a .take5parts file, or file > share with bandmates > import parts... . new tracks land as new tracks, where they were played (on the same bars even if the tempo changed); a new version of a track you already have arrives as an alternative of it, named after who played it, playing, its takes there to comp (right-click the track > alternatives ); a track that hasn't changed is left as it is. new tracks go in the folder they were in, if you have it. their audio is copied into the song's audio folder, and their comments added. a box says what came in; ctrl+z cmd+z takes it all out again. parts for another song are refused (open the song they're for first)."],["sharing-with-bandmates--leave-a-comment-at-a-point-in-the-song","Leave a comment at a point in the song","Sharing with bandmates","finishing-and-sharing.html","leave a comment at a point in the song right-click the sections lane > add comment here... and type it: a dot with your initial, signed with your name, at that point (on the grid; it stays on its beat if the tempo changes). hover over the dot to read it (who, what, where); right-click it > remove comment . both are undo steps. comments go to bandmates with the parts you send and in a song package, and removing one removes it for them too."],["on-stage-and-at-practice--play-a-gig-with-a-setlist-stage-mode","Play a gig with a setlist (stage mode)","On stage and at practice","on-stage-and-practice.html","play a gig with a setlist (stage mode) file > stage mode... plays your songs one after another at a gig: backing tracks and samples to the pa, the click and cues only to the in-ears, one key (or a foot switch) for the next song. it opens on the setlist: add songs... (their .tracktionedit files) in the order you play them, move up and move down to change it, remove to take one out. for the selected song: note : shown big on stage while it plays (\"capo 2\", \"drop d\", \"mike counts in\"). then : wait for the next-song key (the band talks to the crowd, tunes...) or start the next song after a gap in seconds (songs played straight through). in-ears : this song's tracks that only the band should hear, by name with commas (a guide vocal). save... keeps the setlist as a .t5setlist file (the songs by where they are next to it, so a folder with the setlist and its songs can be copied to another computer); open... opens one, and the last one opens by itself next time. a song that's been moved or deleted shows in red. start show opens the first song (and the next one, so it starts at once) and switches to the stage view: the song's name big, its note, the section playing and the next one, the bar and tempo, and what's next. space plays or stops; return (or right or page down) starts the song when it's waiting, and otherwise goes to the next song at once; esc stops everything. double-click a song in the setlist to start the show from it. setlist goes back. the song open in the main window stops while the show runs, and comes back when it ends. songs play as they were saved, from the start to the end (a loop saved on in a song is left off): the show changes nothing in them, and nothing is saved. only the song up runs: the next one is opened but quiet until it starts, so it takes no processing and an armed track in it doesn't play your guitar a second time."],["on-stage-and-at-practice--send-the-click-and-cues-to-the-in-ears-the-rest-to-the-pa","Send the click and cues to the in-ears, the rest to the PA","On stage and at practice","on-stage-and-practice.html","send the click and cues to the in-ears, the rest to the pa in file > stage mode... , choose in-ear output : the interface's output your in-ear (or headphone) mix is plugged into (outputs are pairs, as enabled in edit > audio settings... ). in the show the click, the spoken cues, every track named like a cue (click, cue, guide, count in) and each song's own in-ears tracks go there; everything else plays through the main outputs as usual, to the pa. with none , everything goes to the main outputs (a rehearsal with headphones, say), and there are no spoken cues. if the chosen output isn't on the interface that's plugged in (a setlist made with another one), the show says so as it starts: then there are no spoken cues either, and the click and in-ear tracks play through the main outputs, so check before the audience is in. the click plays as each song has it (on or off, its sound and count-in): set those in the song."],["on-stage-and-at-practice--hear-each-section-s-name-before-it-comes-spoken-cues","Hear each section's name before it comes (spoken cues)","On stage and at practice","on-stage-and-practice.html","hear each section's name before it comes (spoken cues) with say each section a bar before it on (in file > stage mode... ), each section marker's name (\"chorus\", \"bridge\") is spoken a bar before the section starts, in the in-ears only (never through the pa: with no in-ear output there are none), so nobody loses their place. the computer's own voice says it the first time and it's kept in the stage cues folder in take 5's settings folder (see \"where take 5 keeps things\"). to use your own voice instead, record a short file named after the section (chorus.wav, bridge.wav) into that folder: it's used in place of the computer's. sections are the song's markers (insert adds one)."],["on-stage-and-at-practice--change-songs-with-a-foot-switch","Change songs with a foot switch","On stage and at practice","on-stage-and-practice.html","change songs with a foot switch a midi foot switch or any controller button can run the show. in file > stage mode... , click learn foot switch and press the switch: it shows as \"cc 64, channel 1\" (or a note). in the show it plays a song that's waiting and starts the next song between songs. while a song plays, one press does nothing (so a stray step doesn't cut a song off): press twice within a second to skip to the next one."],["on-stage-and-at-practice--change-my-guitar-rig-s-patch-at-each-section-rig-changes","Change my guitar rig's patch at each section (rig changes)","On stage and at practice","on-stage-and-practice.html","change my guitar rig's patch at each section (rig changes) a guitar modeller, amp or pedal switcher that takes midi program changes can change patch by itself at the chorus, while you record and on stage. midi > rig changes... , add rig , then set: name : what you call it (\"floor unit\", \"bass rig\"). midi output : the output the unit is on (over usb it shows by the unit's name; else your interface's midi out with a cable to the unit's midi in) and the channel the unit listens on (set on the unit). unit : how patches are named in the lists, to match what your unit shows: numbers (pc 1-128), banks of four (01a-32d), performances of five slots (p1 s1) or banks of eight (1a-16h). scenes : the controller your unit changes snapshots or scenes on, if you use them (cc 69 or cc 43, as its manual says). the list has the song's start and each section marker. select one and choose its patch (and a bank , for a unit with more than 128 patches, and a scene ); \"-\" leaves that as it is. or click learn and pick the patch on the unit itself: the program change it sends is set. send now sends the selected one to try it. while the song plays each change is sent as the playhead reaches its section, and whenever playing starts (from anywhere, before a count-in too) the patch in force there is sent first, so the unit is always right. a second guitarist's or the bass player's unit is another rig ( add rig ). rig changes are kept with the song, each change an undo step. stage mode sends a song's first patches as it gets ready to play."],["on-stage-and-at-practice--try-ideas-as-loops-in-the-clip-launcher","Try ideas as loops in the clip launcher","On stage and at practice","on-stage-and-practice.html","try ideas as loops in the clip launcher window > panels > clip launcher opens a grid: a column for each track, a row for each scene. each slot holds a clip that loops. to fill one, select a clip on the timeline, right-click a slot and choose copy selected clip here (the clip stays on the timeline too); clear slot empties one. click a clip to launch it: it starts on the next bar ( launch on sets that: 1, 2, 4 or 8 bars, a half, a quarter, an eighth, or at once ), in time with whatever's playing, and the song starts playing if it wasn't. a clip about to start blinks; one playing is lit with a play sign. click it again to stop it, or click an empty slot to stop that track. each track plays one launcher clip at a time: launching another on it changes over at the next bar. a scene's button (at the left) launches its whole row at once; an empty slot in a scene stops its track. right-click a scene's button to rename it. add scene adds a row, stop all stops everything on the next bar. while a track plays launcher clips it doesn't play its timeline (its name is lit); back to arrangement sends every track back to the song as it's arranged."],["on-stage-and-at-practice--make-scenes-from-the-song-s-sections","Make scenes from the song's sections","On stage and at practice","on-stage-and-practice.html","make scenes from the song's sections in window > panels > clip launcher , scenes from sections makes a scene for each section of the song (its markers, insert adds one), named after it, each track's part of the section in the scene's slot: a midi track's notes in the section in one clip, an audio track's clip cut to the section. launch verse, then chorus, then verse again to try the song in another order, live. ( project > arranger chains does the same thing on the timeline, to keep.)"],["on-stage-and-at-practice--record-a-jam-into-the-song","Record a jam into the song","On stage and at practice","on-stage-and-practice.html","record a jam into the song in window > panels > clip launcher , turn on record jam and launch clips and scenes as you like. turn it off and what you played is written into the timeline: each clip where it played, looped for as long as it played, so the jam becomes an arrangement you can edit (one undo step). every track goes back to the arrangement then."],["on-stage-and-at-practice--loop-a-guitar-part-live-the-looper","Loop a guitar part live (the looper)","On stage and at practice","on-stage-and-practice.html","loop a guitar part live (the looper) in window > panels > clip launcher , right-click an empty slot on a track with an input (a guitar on input 1, say, or a midi keyboard) and choose record a loop here : 1, 2, 4 or 8 bars, or until i finish it . the song starts if it's stopped, and recording begins on the next bar (the slot shows \"on the bar...\" then \"rec\"); only that track records, whatever else is armed. a loop of so many bars stops by itself; one recorded until you finish it ends on the bar after you choose finish the loop (on the next bar) in its slot's menu (or press the loop switch). the loop plays at once, in time, and goes on looping: play the next part over it. to add to a loop, right-click it and choose overdub a layer : the loop's next pass is recorded and added onto it (an audio loop's sound mixed in, a midi loop's notes added). each layer can be taken off again, last first, with undo the loop's last layer ; edit > undo takes one off too. stop recording the loop (keep nothing) in the slot's menu stops at once. a loop's audio is in the song's audio folder (one file per layer), so it stays with the song."],["on-stage-and-at-practice--launch-scenes-and-loop-with-foot-switches","Launch scenes and loop with foot switches","On stage and at practice","on-stage-and-practice.html","launch scenes and loop with foot switches in window > panels > clip launcher , click learn foot switch and press a midi foot switch (or any controller button). each press launches the next scene that has anything in it, from the one after the last scene launched, round to the first again. learn loop switch gives the looper a switch of its own, so both hands stay on the guitar. the first press records a loop into the slot last looped (or the first empty slot of the first armed track), the next press ends it on the bar and it plays, and each press after that overdubs a layer onto it."],["on-stage-and-at-practice--control-take-5-from-my-phone-phone-remote","Control Take 5 from my phone (phone remote)","On stage and at practice","on-stage-and-practice.html","control take 5 from my phone (phone remote) when you're at the drum kit or the amp, across the room from the computer, a phone can be the remote. transport > phone remote... , start the remote : the window shows an address (http://192.168.1.20: 8765/?code=k7m2xq, say) and a code. type the address into the phone's browser (the phone on the same wi-fi as the computer). the page has big buttons: back to the start, play ( stop while playing), rec , the previous and next section, + marker (a section marker at the playhead), and the song's tracks to arm and mute, with where the song is, its tempo and section. everything the buttons do is as if you'd done it in take 5 (with the count-in, if it's on), and each change can be undone there. rec from here after 2 bars gives you time to get to the kit: it records from where the playhead is after two bars counted in, whatever the song's own count-in is, the click playing them and the phone counting the beats down in big numbers (8, 7... 1 in 4/4). press it again to stop recording. nothing can reach take 5 until you start the remote, and only from this computer or its local network, with the code (a new one each time take 5 opens; five wrong ones and that phone waits a minute), and from the remote's own page (another web page open in a browser can't send it commands). stop the remote turns it off; it keeps running with the window closed. on windows, the first time you start it, windows may ask whether take 5 may use the network: allow it on private networks."],["on-stage-and-at-practice--print-a-chord-chart-of-the-song-for-the-band","Print a chord chart of the song for the band","On stage and at practice","on-stage-and-practice.html","print a chord chart of the song for the band score > chord chart... makes a page to play from, with nothing to type: the song's title, key, tempo and time signature; its sections in order (from the section markers), each with how many bars it has; the chord lane's chords in those bars, four bars to a line, the chord on the beat it starts and a slash for each beat it carries on; under each section its lyrics (from the lyrics lane), each chord above the word it comes on; and the rig changes at each section (see \"change my guitar rig's patch at each section\"). the page is drawn on the right as it will print: the type is as big as fits on one page, and a long song goes onto a second. print... prints it (or saves it as a pdf from the print window); save pdf... saves it to send round or read on a tablet. to change the chart, change the song (a marker's name, a chord in the chord lane) and open it again."],["on-stage-and-at-practice--a-chart-for-guitar-bass-or-drums","A chart for guitar, bass or drums","On stage and at practice","on-stage-and-practice.html","a chart for guitar, bass or drums in score > chord chart... , for chooses who the chart's for: the band : the chords and lyrics. guitar : a chord diagram for each chord in the song along the top (where to put the fingers, in the tuning of the song's first guitar part, e.g. drop d; open strings as rings, strings not played as x, a barre where it needs one), then the chart. bass : the roots of the chords in the bars (a, f, c, g), the lyrics too. drums : the sections and their bars as slashes, an accent (>) where the chord changes off the first beat (where the band hits together), and the chords small for reference; no lyrics. save every part... saves all four as pdfs in a folder (\"song - chart.pdf\", \"song - guitar chart.pdf\"...). nashville numbers writes the chords as numbers in the key (1, 4, 5, 6m; b7 for a chord from outside it), so the chart works in any key. lyrics with their chords leaves the lyrics out when it's off."],["on-stage-and-at-practice--play-the-song-in-another-key-or-with-a-capo","Play the song in another key, or with a capo","On stage and at practice","on-stage-and-practice.html","play the song in another key, or with a capo in score > chord chart... , key transposes the chart: the chords for playing the song in another key (a singer's), up or down six semitones; the key on the page is the new one. with for set to guitar , capo puts a capo on a fret: the chart shows the chords as the shapes you play with the capo there (with key a tone up and capo on 2, the shapes stay those of the song's own key), and the diagrams are those shapes. the song itself doesn't change."],["on-stage-and-at-practice--print-the-setlist-for-a-gig","Print the setlist for a gig","On stage and at practice","on-stage-and-practice.html","print the setlist for a gig in score > chord chart... , click setlist... and choose a setlist saved by stage mode (a .t5setlist, see \"play a gig with a setlist\"): a page in big print, a song to a line, numbered, with each song's key, tempo and guitar tuning (read from the songs) and its note (\"capo 2\"). it's saved as a pdf beside the setlist (\"friday - setlist.pdf\") and shown in finder (explorer on windows), to print or put on a tablet. a song that can't be found is listed with just its name."],["on-stage-and-at-practice--record-a-whole-rehearsal-and-find-the-songs-in-it-the-rehearsal-recorder","Record a whole rehearsal and find the songs in it (the rehearsal recorder)","On stage and at practice","on-stage-and-practice.html","record a whole rehearsal and find the songs in it (the rehearsal recorder) file > rehearsal recorder... records a band practice without thinking about it, no song needed. under record , tick the interface's inputs to record: a stereo pair from a room mic (or the desk's two-track out), or every channel the band's plugged into (the ticks are remembered). click record rehearsal : the time counts up big, a meter for each input, and how many hours of disk space are left. it records for as long as you play (hours is fine), to a folder of its own named by the date and time, written to disk as it goes in pieces of five minutes, so if the computer crashes only the last seconds are lost. click stop when you're done. then it's cut into its songs by itself (a minute or so for a two-hour rehearsal): where the band plays is found by how loud it is against the room's own quiet (learnt from the recording), so the talk, tuning and noodling between songs are left out; a song has to last half a minute, and a break of up to six seconds in one keeps it one song. each song becomes a take, its own wav file, with its tempo and key found. they're listed under the rehearsal: stars, the song's name, its length, tempo, key and a note. show talk between songs lists the stretches in between too. closing the window while it records asks first: closing stops the recording (what's recorded is kept)."],["on-stage-and-at-practice--name-a-rehearsal-s-takes-from-the-setlist","Name a rehearsal's takes from the setlist","On stage and at practice","on-stage-and-practice.html","name a rehearsal's takes from the setlist in file > rehearsal recorder... , name songs from > setlist... chooses a setlist (a .t5setlist, as stage mode saves): the takes are named from its songs in order, the first song played after the setlist's first song and so on; takes past its end are \"take 4\", \"take 5\". none names them all take 1, take 2... to fix a name (a song played twice, one left out), select the take and click rename... (or double-click its name): its file is renamed too. cut again... cuts the chosen rehearsal into songs again with the setlist chosen now; stars and notes stay with the songs of the same name."],["on-stage-and-at-practice--find-how-a-song-went-at-every-rehearsal","Find how a song went at every rehearsal","On stage and at practice","on-stage-and-practice.html","find how a song went at every rehearsal in file > rehearsal recorder... , the rehearsals are listed newest first, each with its length and how many songs. type a song's name in find a song : its takes from every rehearsal are listed together, with the date of each, to hear how it's come on (\"how did the bridge sound on tuesday?\"). select a take and click play (or press space ) to hear it; click it again to stop. click a star to rate a take (the same star again: none), or press 1 to 5 (0 for none); note... (or double-click the note) writes one (\"the bridge finally worked\"). show in finder (explorer on windows) opens the rehearsal's folder."],["on-stage-and-at-practice--turn-a-rehearsal-take-into-a-song-or-send-it-round","Turn a rehearsal take into a song, or send it round","On stage and at practice","on-stage-and-practice.html","turn a rehearsal take into a song, or send it round select a take in file > rehearsal recorder... : open as new song starts a new song (after asking to save the open one) with the take on a track, at the take's tempo, so the bars line up: record the parts properly over it, or use it as a guide. add to this song puts it on a new track in the open song at the playhead. share as mp3 saves it as an mp3 (\"2026-10-31 ballad.mp3\") in the band's shared folder (see \"work on a song through a shared band folder\"), for everyone to hear; with none it asks where, once."],["on-stage-and-at-practice--learn-a-song-from-a-recording-the-practice-player","Learn a song from a recording (the practice player)","On stage and at practice","on-stage-and-practice.html","learn a song from a recording (the practice player) file > practice... opens the practice player, a window of its own for learning a song you have as a recording (a band's demo, a song you're covering, a lesson's backing track). open... a recording (wav, aiff, flac, mp3 or ogg), or drop one on the window. it doesn't need a song open in take 5 and changes none: what's playing in the main window stops while you practise. as it opens it finds the beats, the bars and the chords (a few seconds): the bars are numbered along the top of the waveform (bar 1 is the first full bar; anything before it is the pickup), and the chords are named under them. while it plays, the chord playing shows big, with the next one and how soon it comes, and the bar and time at the right, so \"from bar 33\" means the same to you and your teacher. the chords are the plain major and minor ones the music sounds like (a 7th or a sus shows as its major or minor), and a song without a steady beat (rubato, a free intro) gets no bars or chords. click the waveform to play from there; space plays and stops; home (or to loop start ) goes back. speed : 50% to 125%, the pitch kept (double-click the slider for 100%). transpose : semitones (-12 to +12), and cents (-50 to +50) for a recording that isn't tuned to a 440. the speed is kept. everything you set for a recording (the speed, transpose and saved loops) is kept for it, and comes back the next time you open that file."],["on-stage-and-at-practice--loop-the-hard-part-and-slow-it-down","Loop the hard part and slow it down","On stage and at practice","on-stage-and-practice.html","loop the hard part and slow it down in file > practice... , drag across the waveform over the part (it snaps to the beats; hold ctrl cmd , not to), or double-click a bar's number to loop that bar. loop turns it on and off (off, the loop stays drawn faintly, to turn on again). turn speed down to where you can play it, and press space : it plays round and round. count-in gives a bar of clicks before it starts, on the recording's own beats, the recording silent until the loop begins. save loop... names it (\"solo\", \"bridge riff\") and keeps it with the recording; the loops list brings it back (with its bars), delete forgets one."],["on-stage-and-at-practice--speed-a-loop-up-a-little-each-time-round","Speed a loop up a little each time round","On stage and at practice","on-stage-and-practice.html","speed a loop up a little each time round to get a solo up to speed: loop it, set speed where you can play it cleanly (70%, say), and tick speed up each pass , choosing how much (+1% to +5% a pass). each time the loop comes round it plays that much faster, until 100%; the readout says which pass it is and at what speed. save the loop to keep the setting with it."],["on-stage-and-at-practice--mute-the-guitar-or-the-vocal-of-a-recording-and-play-along","Mute the guitar (or the vocal) of a recording and play along","On stage and at practice","on-stage-and-practice.html","mute the guitar (or the vocal) of a recording and play along in file > practice... , click separate stems... : the recording is split into vocals, drums, bass, guitar, piano and the rest (as separate stems does on a clip; see \"split a song into vocals, drums, bass and the rest\"). it takes a few minutes the first time (and downloads the 55 mb model if it hasn't been), and you can keep practising meanwhile; the stems are kept, so the next time the recording opens they're there. then each part has a box under parts : untick the guitar to mute it and play it yourself, and s solos a part (hear only the bass, to learn its line). the speed, transpose, loops and count-in work on the parts as on the recording."],["on-stage-and-at-practice--play-along-through-the-amp-tune-up-first","Play along through the Amp, tune up first","On stage and at practice","on-stage-and-practice.html","play along through the amp, tune up first in file > practice... , play along chooses the input your guitar, bass or mic is on: you hear yourself over the recording. through the amp puts take 5's amp on it (for a guitar or bass plugged straight into the interface); amp... opens its settings. tuner opens the tuner on that input (see \"tune my guitar or bass\"). for a recording tuned down a half step, set transpose to +1 to play it in standard tuning, or tune down and leave it."],["on-stage-and-at-practice--play-in-time-with-other-apps-and-devices-over-wi-fi-link","Play in time with other apps and devices over Wi-Fi (Link)","On stage and at practice","on-stage-and-practice.html","play in time with other apps and devices over wi-fi (link) transport > link keeps take 5's tempo and beat in time with the other apps and devices on the same network that have link (drum machine and looper apps on a phone or tablet, other music software, some hardware), with no cables or setup. turn it on in each; take 5 then plays in time with the others, its bars lined up with theirs, and nudges itself to stay there. transport > share start and stop with link also starts and stops them when you play and stop (and take 5 when they do). the tempo goes both ways. a song with one tempo takes the tempo the others are at (once there are others: turning link on with no one else leaves the song's tempo as it is), and when you change it they follow; each tempo taken from them is an undo step of its own. a song with tempo changes leads: as it plays through a change, the others follow it. the setting is for every song, and stage mode's songs follow it too. the status line says how many others are in time with it when you turn it on."],["on-stage-and-at-practice--let-the-song-follow-the-drummer-s-tempo","Let the song follow the drummer's tempo","On stage and at practice","on-stage-and-practice.html","let the song follow the drummer's tempo when the band plays live with backing tracks or a click from take 5, it can follow the drummer instead of the drummer following it. transport > follow the drummer... lists the tracks that record from an input: tick the drum tracks to listen to (kick and snare mics work best; tracks named as drums are ticked to start with) and choose up to , how far from the song's tempo the band may take it (6 bpm either way to start with). press follow and play: every half second take 5 finds the tempo the drums are playing in the last few seconds and plays the song at that tempo (smoothly, never further than up to from the song's own), so backing tracks and the click speed up and slow down with the band. the window shows the band's tempo and the song's. the song's own tempo isn't changed while following. to keep what the band played, write the band's tempo writes it into the song's tempo, a change at each bar where it moved by more than half a bpm (one undo step). it finds the tempo, not the exact beat, so start together with the count-in. it can't follow while link has another app in time with take 5 (both would set the song's speed): switch link off first."],["on-stage-and-at-practice--what-stage-mode-does-to-be-safe-on-stage","What stage mode does to be safe on stage","On stage and at practice","on-stage-and-practice.html","what stage mode does to be safe on stage in a show take 5 doesn't autosave or show dialogs, and keys only do what the stage view says ( space , return , esc), not the main window's commands. with low-latency mode on (the default) each song plays in transport > low-latency mode , for playing live through its plugins. a song that won't open (moved, deleted, damaged) is skipped and named in red on the stage view, and the show goes on with the next one."],["the-assistant--set-up-the-assistant","Set up the assistant","The assistant","help-and-backups.html","set up the assistant the assistant makes changes you ask for in plain words, through claude code on your own claude plan, free through google's gemini, or free and offline through a model running on your own computer. with claude code: install claude code from claude.com/code. open terminal (on windows, command prompt), type claude, and sign in once. in take 5, window > panels > assistant , ctrl+alt+a option+cmd+a . take 5 looks for claude code when it opens: if you installed it while take 5 was open, press look again in the panel (shown while there's nothing to run on), or ... > look for claude code again , or reopen take 5. with gemini (no claude plan needed): edit > preferences... > general > assistant... , then get a free key... : sign in to google ai studio with a google account and create a key (no card needed). paste it into gemini key , set use to gemini (or leave it on automatic , which uses claude code when it's installed, else gemini when there's a key) and press save . with use on claude code it never falls back to gemini. open the assistant: window > panels > assistant . gemini model is the model it asks (gemini-flash-latest, the newest flash, unless you change it; left empty, it's that); choose model... (with the key typed in) lists the models your key can use, the newest flash and flash-lite first, to pick one. after save , the status line says what the assistant runs on; saved while it's working on a request, it changes over once that's done. gemini's free tier has limits per minute and per day, each model its own: when the model's limit is reached it asks the lighter flash-lite model instead (and says so in the chat), and when flash-lite's is reached too it says so, or waits a moment when the wait is short. when google's servers are busy (\"high demand\") it asks again a couple of times, then asks flash-lite; with no answer within a minute it switches to flash-lite at once. once flash-lite has answered for it, the next 10 requests that get an answer go straight to flash-lite, then it tries your model again. if flash-lite is busy too, or doesn't answer within a minute either, it says to try again in a few minutes. google may use what's sent on the free tier to improve its products. the key is kept in take 5's settings on this computer (not encrypted) and never written to the log. with a model on this computer (free, offline, private; see \"run the assistant on my own computer\"), local models... installs one with a click; one in ollama or lm studio is use > local model (ollama, lm studio) . the panel's ... menu shows what it runs on, and has assistant settings... . the assistant needs a song open."],["the-assistant--run-the-assistant-on-my-own-computer","Run the assistant on my own computer","The assistant","help-and-backups.html","run the assistant on my own computer the assistant can run on a model on your own computer: free, offline once the model's downloaded, and nothing leaves the computer. take 5 runs the model itself; nothing else needs installing: edit > preferences... > general > assistant... > local models... lists the models it can run, each with its download size, the memory it needs and a line on what it's like. the one that suits this computer's memory says suggested for this computer (qwen3 8b on a computer with 16 gb or more; a smaller one with less). a model that needs more memory than the computer has says so: it's slow, or may not load. click one and install (or double-click it). a window shows each step as it goes: the download (how much, how fast, the time left), the check, the model loading, and a first question to try it. stop stops it, and a part downloaded is deleted. when it's done, the assistant uses the model at once ( use reads built-in model ), and the status line says so. open the assistant ( window > panels > assistant ) and ask. the model loads when a song opens with the assistant on it (a few seconds, longer for a big one), and uses its memory while take 5 is open; it's let go when the assistant is switched to something else. in local models... , use switches to another model that's installed, and remove deletes one (its download is several gb). the models are kept in the models folder in take 5's settings folder (language). a mac with apple silicon runs them on its graphics chip. a windows pc runs them on its graphics card when the card's driver has vulkan (any recent nvidia, amd or intel driver does); the parts of a big model that don't fit the card's memory run on the processor. a pc without one runs them on the processor, which is much slower: there, once a model loads, it spends a few minutes reading the assistant's instructions (a request sent meanwhile waits for that), and then answers in a minute or so; a smaller model is quicker."],["the-assistant--run-the-assistant-on-a-model-in-ollama-or-lm-studio","Run the assistant on a model in Ollama or LM Studio","The assistant","help-and-backups.html","run the assistant on a model in ollama or lm studio if you already use ollama or lm studio, the assistant can use the models there instead. it needs a model that can use tools: install ollama (ollama.com) and download a model that uses tools, in terminal (command prompt on windows): ollama pull qwen2.5:7b (about 5 gb; a bigger one, 14b or 32b, does better if the computer has the memory for it). or install lm studio (lmstudio.ai), download a model there and start its server (the developer tab). in take 5, edit > preferences... > general > assistant... : use local model (ollama, lm studio) ; local server is ollama's address, http://localhost:11434 (for lm studio, http://localhost:1234). choose model... lists the models it has: pick one. save . it does what it does through claude code or gemini (changes as one undo step, answers from the guide, the app's commands), as well as the model can: a small model on a laptop is slower and gets more wrong than claude or gemini, so start with simple requests. the first request after starting can take a while as the model loads (it waits up to five minutes). if nothing answers, it says so: start ollama (or lm studio's server) and ask again."],["the-assistant--ask-the-assistant-to-change-the-song","Ask the assistant to change the song","The assistant","help-and-backups.html","ask the assistant to change the song type a request in the assistant panel and press return : \"compress the bass a bit\", \"make the chorus 2 db louder\", \"add a bar of silence before the outro\", \"pan the rhythm guitars wider\", \"transpose the arp up an octave\", \"set the tempo to 120\". it says what it changed. each request is one undo step: ctrl+z cmd+z takes the whole request back (edit > undo names it \"assistant: ...\"). a menu command it runs is an undo step of its own, and settings it changes (the audio device, the theme, the click) aren't undone. while it works, the box shows what it's doing and for how long, and send becomes stop : it stops after the step it's on, keeping what it changed so far (one undo step). a reply too long for the panel opens at its start. with gemini, a request that takes more than 25 steps stops: ask for less at once."],["the-assistant--ask-the-assistant-about-the-song-or-about-take-5","Ask the assistant about the song or about Take 5","The assistant","help-and-backups.html","ask the assistant about the song or about take 5 ask questions too: \"why does the mix sound muddy?\" makes it analyse the mix before answering, without changing anything. it can also answer \"how do i...\" questions from this guide, find menu commands and their shortcuts, run commands (show the mixer, start the tuner, turn on the loop), and read and change settings. it asks before changing anything that could cut the sound, such as the audio device or buffer size, and changes it only once you've said yes. besides those, it can switch midi inputs and outputs, the click's sound and output, the count-in and pre-roll, and the theme. it knows every plugin you have, built in and installed: it can add one by name, turn any of its knobs (\"set the reverb's mix to 30%\"), load or save its presets, and put another instrument on a track (\"give the keys a grand piano sound\"). it won't open, close or save songs, quit, or undo for you. click one of its messages and press ctrl+c cmd+c to copy it (as plain text); ctrl+a cmd+a copies the whole conversation; right-click for copy and copy conversation ."],["the-assistant--what-the-assistant-can-and-can-t-do","What the assistant can and can't do","The assistant","help-and-backups.html","what the assistant can and can't do it works only on the open song and take 5's own commands and settings: it can't open files you choose, run other programs or touch anything outside the app (it writes only into the song's folder: a dawproject export, a tone3000 tone it downloads). only the song's details (track names, levels, plugins, notes, lyrics, measurements), the guide's text and your audio devices' names go to claude (or gemini), never audio. it remembers the conversation until you choose ... > clear conversation , open another song, save the assistant's settings, or quit (with gemini, a request that failed or was stopped isn't part of what it remembers, though what it changed stays in the song). if claude code isn't installed, isn't signed in, gemini's key is wrong or its limit is reached, or the internet is off, the panel says so: a request that fails before it starts leaves the song alone; one that stops partway keeps what it changed (one undo step). on windows, a request to claude code can be about 32,000 characters at most."],["backups-history-and-recovery--undo-several-steps-at-once","Undo several steps at once","Backups, history and recovery","help-and-backups.html","undo several steps at once edit > undo , ctrl+z cmd+z , and redo , ctrl+shift+z shift+cmd+z ; the menu names the step. edit > history lists the last 25 steps: choose one to go back to before it in one go. fader, pan, send and plugin-knob moves are undoable too (one step per drag), and each assistant request is a single step. saving isn't a step: after a save, undo still undoes your last edit. insert silence, delete time and deleting a range are one step each. the history goes when the song closes (and after remove unused media... , restore or recover). while the assistant is working, stop it first. for versions from earlier saves, see \"go back to an earlier save\"."],["backups-history-and-recovery--how-autosave-and-backups-work","How autosave and backups work","Backups, history and recovery","help-and-backups.html","how autosave and backups work while there are unsaved changes, take 5 saves a recovery copy every 2 minutes (not while recording): a hidden file beside the song, gone when you save or close without saving. each file > save ( ctrl+s cmd+s ) keeps the previous save in the song's backups folder, \"<song> <date> <time>\" (at most one every 5 minutes, the newest 20). the song is also saved when a recording stops."],["backups-history-and-recovery--recover-after-a-crash","Recover after a crash","Backups, history and recovery","help-and-backups.html","recover after a crash if take 5 stopped without saving (a crash, a power cut, a force quit), the next time you open the song it offers the recovery copy: recover changes brings your unsaved work back; open last save opens the song as last saved and drops the recovery copy. recovering puts the recovered song in place of the song file at once, and the last save goes to the backups folder: to go back to it, use file > revert (closing without saving doesn't). a recovered song counts as unsaved until you save it, so closing it asks whether to save; the recovery isn't offered again."],["backups-history-and-recovery--send-a-crash-report-or-turn-them-off","Send a crash report, or turn them off","Backups, history and recovery","help-and-backups.html","send a crash report, or turn them off if take 5 closed unexpectedly or stopped responding (and was ended), the next time it opens it asks whether to send a report so it can be fixed. the report says where take 5 stopped, what it was doing just before, which version it is and what kind of computer: your user name, the names of your songs, tracks and files, and anything you said to the assistant are taken out. show report opens exactly what would be sent; the box above the buttons is for what you were doing, if you'd like to say. send sends it (without an internet connection, at the next launch), don't send doesn't, and neither asks about that crash again. tick always send without asking to skip the question from then on; help > send crash reports without asking (also in edit > preferences... > general ) turns that on and off. nothing is sent without your yes."],["backups-history-and-recovery--go-back-to-an-earlier-save","Go back to an earlier save","Backups, history and recovery","help-and-backups.html","go back to an earlier save file > revert lists earlier saves (not snapshots) by time, newest first; pick one and revert (unsaved changes are lost; the current save is kept as a backup). file > project history... lists backups (saved) and snapshots (snapshot), newest first. select one and press listen (or double-click it) to hear 30 seconds of that version from the playhead (or the loop) without changing the song ( stop ends it). restore... makes it the song again; the song as last saved is kept as a backup. the undo history goes with a restore."],["backups-history-and-recovery--bring-back-a-deleted-track","Bring back a deleted track","Backups, history and recovery","help-and-backups.html","bring back a deleted track file > project history... , pick a save from before you deleted it, then bring back track : tracks you've deleted since are listed under \"deleted since then\". it comes back where it was (in its folder, if that's still there), with its clips and plugins. as it was then (a copy) brings back a copy of how a track used to be, \"<track> (earlier)\", after it. ctrl+z cmd+z takes it away again. if its audio has been cleaned up since, it says how many clips lost theirs."],["backups-history-and-recovery--save-a-named-snapshot","Save a named snapshot","Backups, history and recovery","help-and-backups.html","save a named snapshot file > save snapshot... (or save snapshot in song history) keeps the song as it is now under a name (\"before the rewrite\"), unsaved changes included (the song file itself isn't saved). it's a file in the song's snapshots folder (a name already used gets a number). snapshots show marked snapshot in file > song history... and are kept until you delete them from that folder."],["backups-history-and-recovery--keep-a-second-copy-on-another-disk-or-in-the-cloud","Keep a second copy on another disk or in the cloud","Backups, history and recovery","help-and-backups.html","keep a second copy on another disk or in the cloud edit > preferences... > general > second copy of backups... (or second copy... in song history, where it shows where the copy goes): choose a folder on another disk or one a cloud service syncs, outside the song's folder. it's one folder for every song. after each save (and each snapshot), a folder named after the song's folder there gets everything in it (song file, backups, snapshots, audio, exports), in the background, copying only what's changed. backups dropped from the song are dropped from the copy; deleted audio and snapshots stay there. with a folder chosen, the same command offers choose another folder... , turn off and show in finder ( show in explorer on windows). if the disk isn't connected, the status line says the copy wasn't made."],["backups-history-and-recovery--start-songs-from-a-template","Start songs from a template","Backups, history and recovery","help-and-backups.html","start songs from a template set up a song the way you like to start (band tracks, inputs, buses, tempo, click), then file > save as template... and name it (a name you've used replaces that template): tracks, plugins, buses and settings, no clips, takes or sections, nor its comments or what ties it to a shared song. file > new project from template starts from it, and edit > preferences... > general > template for new songs makes file > new project... always use it ( none (one audio track) goes back: one audio track, 120 bpm, 4/4). a new song from a template starts with the playhead at the start, wherever it was when the template was saved. templates are kept with take 5 (its templates folder), for every song."],["backups-history-and-recovery--tidy-up-a-song-folder","Tidy up a song folder","Backups, history and recovery","help-and-backups.html","tidy up a song folder media > collect audio into project copies the audio its clips use from elsewhere into its audio folder, so the folder works on its own (one undo step; it says how many files, and any missing). media > remove unused media... lists files in the audio folder that nothing uses (not the song's clips, takes or alternatives, nor its backups and snapshots) and, on move to trash , moves them to the trash (recycle bin on windows). it clears the undo history."],["backups-history-and-recovery--find-files-a-song-is-missing","Find files a song is missing","Backups, history and recovery","help-and-backups.html","find files a song is missing when a song opens and some of its files aren't where it says (it came from another computer, or a folder was moved or renamed), a message lists them: its clips' audio, the capture player's captures and cabinet irs, the reference track. the rest of the song plays. find in folder... looks through a folder you choose, and the folders in it, for each by its file name and points the song at what it finds (one undo step); later leaves them, and the message comes back the next time the song opens. media > find missing files... does it any time."],["troubleshooting--i-can-t-hear-anything","I can't hear anything","Troubleshooting","help-and-backups.html","i can't hear anything check edit > audio settings... : the right output device, its output channels ticked, and press test for a tone. check the master fader and that studio > dim isn't on; check nothing is soloed ( studio > unsolo all ) or muted ( studio > unmute all ). check the track's output (right-click > output ) is master or an output you're listening to. a deactivated track (greyed out) is silent: right-click > activate track . if something went extremely loud (over +12 db, or broken audio from a plugin), the output mutes itself for 2 seconds to protect your ears and the status line says so."],["troubleshooting--i-can-t-hear-my-guitar-or-mic-while-recording","I can't hear my guitar or mic while recording","Troubleshooting","help-and-backups.html","i can't hear my guitar or mic while recording in edit > audio settings... , the interface is the input device and its input channel is ticked. the track's input menu shows that input (not \"no input\"). the track is armed (its r button, not the r key): its meter should move when you play. if not, check the interface's gain and cable. (an input feeds one track at a time: choosing it on another track takes it from this one.) input monitoring (the headphones button) is auto or on , not off . it belongs to the input: every track on that input follows it. on a mac, take 5 must be allowed the microphone: system settings > privacy & security > microphone. some interfaces have a direct-monitor knob or switch; if you hear yourself twice, set monitoring to off ."],["troubleshooting--my-recording-is-late-or-out-of-sync-with-the-click","My recording is late or out of sync with the click","Troubleshooting","help-and-backups.html","my recording is late or out of sync with the click take 5 moves recordings earlier by the latency the interface reports. if takes still land late or early, measure the real round trip: a cable from an output straight to an input, studio > recording latency... , measure (see \"measure recording latency so takes line up\"); it's kept for each input, so measure each one you record from. plugins that delay the sound are compensated on playback; while recording, transport > low-latency mode keeps what you hear immediate. bluetooth headphones lag too much to record with."],["troubleshooting--i-hear-crackles-clicks-or-dropouts","I hear crackles, clicks or dropouts","Troubleshooting","help-and-backups.html","i hear crackles, clicks or dropouts raise the buffer size in edit > audio settings... (for example 128 to 256, or 512 for mixing). on windows, use the interface's asio driver rather than windows audio or directsound. find the heavy ones in window > panels > audio performance (or click the cpu reading at the bottom right), then freeze or deactivate them (right-click a track > freeze or deactivate track ). clicks at clip edits: turn on edit > snap to zero crossing , or add short fades. clicks only in a mix that's very loud may be clipping: watch the master meter and the true peak readout."],["troubleshooting--my-midi-keyboard-doesn-t-play-anything","My MIDI keyboard doesn't play anything","Troubleshooting","help-and-backups.html","my midi keyboard doesn't play anything plug it in: take 5 finds a midi keyboard within a few seconds, even while it's open, and listens to every one unless it's switched off in midi > midi inputs (ticked: listened to). if it still plays nothing, unplug it and plug it back in, or quit and reopen take 5. a bluetooth one has to be paired first: bluetooth midi... in edit > audio settings... (mac only). play an instrument track ( project > add track > instrument... ), not an audio track, and arm it (its r button). the instrument track's input should be \"all midi ins\" or your keyboard. check the instrument makes sound: click a key on the piano roll's keyboard, or a drum machine pad. a bundled instrument only plays its own range: musical typing dims keys out of reach. notes stuck on? transport > panic , or double-click the play button."],["troubleshooting--my-keyboard-plays-some-notes-twice","My keyboard plays some notes twice","Troubleshooting","help-and-backups.html","my keyboard plays some notes twice some keyboards with worn contacts send a note twice. edit > preferences... > midi > ignore notes sent twice by and tick the keyboard (kept for that keyboard): a second note-on for a key still held, within 40 ms, is dropped, so a doubled note sounds and records once while fast repeated notes still work. for notes already recorded, open them in the midi editor and choose midi > delete doubles (notes on one key starting within 40 ms become one)."],["troubleshooting--notes-or-sounds-are-stuck-on","Notes or sounds are stuck on","Troubleshooting","help-and-backups.html","notes or sounds are stuck on transport > panic (it has no key until you give it one), or double-click the play button: every plugin is reset and all notes, sounds and the sustain pedal are released on every track and midi input, including plugins in their own processes. if a note keeps sticking, check the keyboard's sustain pedal and cable, and see \"my midi keyboard doesn't play anything\"."],["troubleshooting--a-plugin-is-missing-from-the-menu","A plugin is missing from the menu","Troubleshooting","help-and-backups.html","a plugin is missing from the menu scan again: studio > plug-in manager... > scan for plugins . if it's installed somewhere else, options... > scan for new or updated vst3, audiounit or clap plug-ins and choose the folders to look in. each plugin is scanned in a separate process: one that crashes (twice) or takes more than 2 minutes is skipped, listed at the end, and tried again next time. options... also removes plugins from the list (the selected ones, or those no longer there). check its format:, vst3, audio units or clap; on windows, vst3 or clap. check it's installed where plugins go:, library/audio/plug-ins (in your home folder or the disk's); on windows, c:\\program files\\common files\\vst3 (or clap), or the same in %localappdata%\\programs\\common. instruments are listed under project > add track > instrument... > plugins , effects under the + slot > plugins ."],["troubleshooting--space-or-num-doesn-t-do-anything","Space or Num * doesn't do anything","Troubleshooting","help-and-backups.html","space or num * doesn't do anything space plays and stops, num * records (on a mac, r does too: a mac laptop has no numpad). single-key shortcuts don't work while you're typing in a text box (a track name, a value box): click an empty part of the tracks first. with no song open, there's nothing to play. if you changed the key set, check edit > key commands... or the cheat sheet ( ctrl+/ cmd+/ ). (while on-screen keyboard is on, the letter keys of its keyboard play notes; space and num * still work.)"],["troubleshooting--send-a-bug-report","Send a bug report","Troubleshooting","help-and-backups.html","send a bug report help > show log files opens the folder with this launch's log selected (\"take 5 2026-10-31 14-05-12.log\": the date and time it opened). send it to alan with what you did; it already has your computer, system, audio device, midi inputs, how the last launch ended and everything the app did. the last 20 launches' logs are kept. for a plugin problem, send \"plugin hosts.log\" from the same folder too. if take 5 won't start, the logs are in ~/library/logs/take 5 and %appdata%\\take 5\\logs on windows. edit > preferences... > general > detailed log (ticked while on, and remembered) writes more, the plugins' processes too, for chasing a problem."],["windows-and-mac-differences--shortcuts-and-menus-on-windows","Shortcuts and menus on Windows","Windows and Mac differences","help-and-backups.html","shortcuts and menus on windows where this guide says cmd, use ctrl; where it says opt, use alt (ctrl+s saves, ctrl+z undoes). the shortcut that's control on the mac, bounce in place, is ctrl+b on windows. return is enter. the menu bar is inside the take 5 window (open its menus with the mouse; alt and f10 don't). file > quit , ctrl+q, quits (on the mac, take 5 > quit take 5 ). finder is explorer, and the trash is the recycle bin. in the key sets, where a mac key and a control key become the same ctrl key, the second command gets ctrl+alt instead (set b's midi editor, ctrl+alt+=; mute notes in sets c and f, ctrl+alt+m)."],["windows-and-mac-differences--keys-on-a-mac-keyboard","Keys on a Mac keyboard","Windows and Mac differences","help-and-backups.html","keys on a mac keyboard a mac laptop has no numpad, so on the mac the numpad's transport keys have second keys: r records (as num * does), / turns cycle on and off (num /), and comma and full stop go back and on a bar (num - and num +). the f-keys on a mac keyboard control brightness and volume until you hold fn: press fn+f3 for the mixer, or turn on use f1, f2, etc. keys as standard function keys in macos's keyboard settings. home, end, page up and page down are fn with the arrow keys."],["windows-and-mac-differences--where-take-5-keeps-things","Where Take 5 keeps things","Windows and Mac differences","help-and-backups.html","where take 5 keeps things songs: music/take 5 (mac), music\\take 5 (windows). settings, templates and presets: ~/library/take 5 (mac), %appdata%\\take 5 (windows). rehearsals: music/take 5/rehearsals (music\\take 5\\rehearsals on windows), a folder for each by date and time, with the whole recording in its recording folder and the songs cut out of it in takes. a rehearsal of two hours from a stereo mic takes about 2 gb, and the takes as much again: once the takes are right, the recording folder can be deleted to save the space (the takes stay). models downloaded the first time they're used (stem separation, lyrics transcription's speech models, and the assistant's local models, in language): the models folder in the settings folder, ~/library/take 5/models (mac), %appdata%\\take 5\\models (windows). delete one to free the space: it's downloaded again when it's next needed. the demo song: the windows installer puts it in music\\take 5\\take 5 demo; on the mac, copy it from the disk image. logs: ~/library/logs/take 5 (mac), %appdata%\\take 5\\logs (windows). backups: in each song's own backups folder, on both."],["windows-and-mac-differences--what-s-different-on-windows","What's different on Windows","Windows and Mac differences","help-and-backups.html","what's different on windows audio: asio (with your interface's driver), windows audio or directsound, instead of core audio. plugins: vst3 and clap (audio units are mac-only). midi: no bluetooth midi keyboards (pairing is mac-only), and for midi between apps you need a virtual midi port tool (the mac has the iac driver built in). printing sheet music opens the pdf in your pdf viewer to print from. the bluetooth-headset microphone switch and rosetta for intel-only plugins (until macos 28, which doesn't run intel code) are mac-only. the first launch may show smartscreen's \"windows protected your pc\": more info , run anyway . stage mode's spoken cues are made with windows' speech voice (on the mac, its own voice from say ). the phone remote and listen together: the first time either is started, windows may ask to let take 5 use the network (allow it on private networks); the mac may ask about incoming connections the same way. about take 5 , check for updates... and check for updates at startup are in the help menu (on the mac, in the take 5 menu); on both an update installs itself and opens take 5 again. the installer adds take 5 to the start menu (and, if you like, the desktop); uninstall it from settings > apps. a new song's folder name loses dots and spaces at its end (windows doesn't allow them). transcribe lyrics runs on the processor on windows; on the mac it uses the graphics chip too, so it can be quicker there. transcribe to tab needs macos 13.4 or later on a mac (take 5 itself runs from macos 11); on windows it runs on any version take 5 does. the assistant's local models (local models...) run on the graphics card on windows when its driver has vulkan (else on the processor, much more slowly), on the graphics chip on a mac with apple silicon. everything else (songs, templates, song packages, parts) works the same on both. a song folder copied from one to the other opens with its audio: songs are saved the way both read (a song saved by an older version on windows is read on the mac too). audio kept outside the song's folder (by a full path, such as c:\\... or a network drive) isn't found on the other system: media > collect audio into project first."]];
var T5_AREAS = {"getting-started":"setting-up.html","audio-and-midi-setup":"setting-up.html","customising":"setting-up.html","recording":"recording.html","takes-and-comping":"recording.html","tracks":"tracks-and-arranging.html","arranging":"tracks-and-arranging.html","editing-audio":"editing-audio.html","midi-and-instruments":"writing-and-midi.html","drums":"writing-and-midi.html","mixing":"mixing.html","plugins":"mixing.html","finishing-and-exporting":"finishing-and-sharing.html","sharing-with-bandmates":"finishing-and-sharing.html","on-stage-and-at-practice":"on-stage-and-practice.html","the-assistant":"help-and-backups.html","backups-history-and-recovery":"help-and-backups.html","troubleshooting":"help-and-backups.html","windows-and-mac-differences":"help-and-backups.html"};

var T5 = (function () {
  function esc(s) { return s.replace(/[&<>"]/g, function (c) { return {"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;"}[c]; }); }
  function words(q) { return q.trim().toLowerCase().split(/\s+/).filter(Boolean); }

  // The tasks with every word in them, the ones with the words in their title first.
  function find(ws) {
    var hits = [];
    T5_INDEX.forEach(function (e) {
      var title = e[1].toLowerCase(), all = title + " " + e[2].toLowerCase() + " " + e[4];
      if (!ws.every(function (w) { return all.indexOf(w) >= 0; })) return;
      var score = ws.filter(function (w) { return title.indexOf(w) >= 0; }).length;
      hits.push({e: e, score: score});
    });
    hits.sort(function (a, b) { return b.score - a.score; });
    return hits.map(function (h) { return h.e; });
  }

  function snippet(text, ws) {
    var at = -1;
    ws.forEach(function (w) { var i = text.indexOf(w); if (i >= 0 && (at < 0 || i < at)) at = i; });
    var start = Math.max(0, at - 50), s = text.slice(start, start + 150);
    var raw = (start > 0 ? "…" : "") + s + (start + 150 < text.length ? "…" : "");
    // All the words in one pass over the text as it is (longest first), escaped piece by piece: a
    // word marked one at a time over marked, escaped text matched inside the marks and entities.
    var sorted = ws.slice().sort(function (a, b) { return b.length - a.length; });
    var pattern = new RegExp(sorted.map(function (w) { return w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }).join("|"), "g");
    var out = "", last = 0, m;
    while ((m = pattern.exec(raw)) !== null) {
      if (!m[0].length) { pattern.lastIndex++; continue; }
      out += esc(raw.slice(last, m.index)) + "<mark>" + esc(m[0]) + "</mark>";
      last = m.index + m[0].length;
    }
    return out + esc(raw.slice(last));
  }

  // A list of the tasks found, linked, into a box; how many there were.
  function results(q, box, limit) {
    var ws = words(q);
    if (!ws.length) { box.hidden = true; box.innerHTML = ""; return 0; }
    var hits = find(ws);
    var here = location.pathname.split("/").pop() || "index.html";
    box.innerHTML = '<p class="m-res-count">' + (hits.length ? hits.length + (hits.length === 1 ? " task" : " tasks") + " in the manual" : "Nothing in the manual") + "</p>"
      + '<ol>' + hits.slice(0, limit || 40).map(function (e) {
        var href = (e[3] === here ? "" : e[3]) + "#" + e[0];
        return '<li><a href="' + href + '"><b>' + esc(e[1]) + "</b><span>" + esc(e[2]) + "</span><small>" + snippet(e[4], ws) + "</small></a></li>";
      }).join("") + "</ol>";
    box.hidden = false;
    return hits.length;
  }

  function keysToggle() {
    var root = document.documentElement;
    var win = document.getElementById("os-win"), mac = document.getElementById("os-mac");
    if (!win || !mac) return;
    function set(os) {
      root.classList.toggle("mac", os === "mac");
      win.setAttribute("aria-pressed", String(os !== "mac"));
      mac.setAttribute("aria-pressed", String(os === "mac"));
    }
    var saved = null;
    try { saved = localStorage.getItem("take5-keys"); } catch (e) {}
    set(saved || (/Mac/.test(navigator.platform || navigator.userAgent) ? "mac" : "win"));
    function pick(os) { set(os); try { localStorage.setItem("take5-keys", os); } catch (e) {} }
    win.addEventListener("click", function () { pick("win"); });
    mac.addEventListener("click", function () { pick("mac"); });
  }

  // "/" anywhere outside a text box goes to the search.
  function slashTo(input) {
    document.addEventListener("keydown", function (e) {
      if (e.key === "/" && !/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName)) {
        e.preventDefault(); input.focus();
      }
    });
  }

  // Screenshots open over the page, full size (to the window), not in a tab of their own: a click,
  // x or Esc closes it, the arrow keys go through the page's others. (Without scripts the link
  // still opens the image.)
  function lightbox() {
    var shots = [].slice.call(document.querySelectorAll("a.m-shot"));
    if (!shots.length) return;
    var box = document.createElement("div");
    box.className = "lightbox";
    box.hidden = true;
    box.setAttribute("role", "dialog");
    box.setAttribute("aria-modal", "true");
    box.innerHTML = '<button type="button" class="lb-close" aria-label="Close">\u00d7</button>'
      + '<button type="button" class="lb-prev" aria-label="Previous screenshot">\u2039</button>'
      + '<figure><img alt=""><figcaption></figcaption></figure>'
      + '<button type="button" class="lb-next" aria-label="Next screenshot">\u203a</button>';
    document.body.appendChild(box);
    var img = box.querySelector("img"), caption = box.querySelector("figcaption");
    var current = -1, opener = null;

    function show(i) {
      current = (i + shots.length) % shots.length;
      var a = shots[current], thumb = a.querySelector("img");
      img.src = a.getAttribute("href");
      img.alt = thumb ? thumb.alt : "";
      caption.textContent = (thumb ? thumb.alt.replace(/^Screenshot: /, "") : "") + (shots.length > 1 ? "  \u00b7  " + (current + 1) + " of " + shots.length : "");
      box.classList.toggle("single", shots.length < 2);
    }
    function open(i, from) {
      opener = from;
      show(i);
      box.hidden = false;
      document.documentElement.classList.add("lb-open");
      box.querySelector(".lb-close").focus();
    }
    function close() {
      box.hidden = true;
      document.documentElement.classList.remove("lb-open");
      img.removeAttribute("src");
      if (opener) opener.focus();
    }
    shots.forEach(function (a, i) {
      a.addEventListener("click", function (e) {
        if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return;   // (a new tab when asked for)
        e.preventDefault();
        open(i, a);
      });
    });
    box.addEventListener("click", function (e) {
      if (e.target.closest(".lb-prev")) show(current - 1);
      else if (e.target.closest(".lb-next")) show(current + 1);
      else close();
    });
    document.addEventListener("keydown", function (e) {
      if (box.hidden) return;
      if (e.key === "Escape") { e.preventDefault(); close(); }
      else if (e.key === "ArrowLeft") { e.preventDefault(); show(current - 1); }
      else if (e.key === "ArrowRight") { e.preventDefault(); show(current + 1); }
    });
  }

  // A part page: the sidebar's search shows its results in place of the contents.
  function manualPage() {
    keysToggle();
    lightbox();
    var input = document.getElementById("m-find"), box = document.getElementById("m-results");
    var toc = document.querySelector(".m-toc");
    var timer = null;
    function run() { var n = results(input.value, box); toc.hidden = !box.hidden; return n; }
    input.addEventListener("input", function () { clearTimeout(timer); timer = setTimeout(run, 120); });
    input.addEventListener("keydown", function (e) {
      if (e.key === "Escape") { input.value = ""; run(); }
      if (e.key === "Enter") { var a = box.querySelector("a"); if (a) a.click(); }
    });
    slashTo(input);
    // The contents follow the reading: the area being read is marked.
    var links = {};
    [].forEach.call(toc.querySelectorAll("a"), function (a) { links[a.getAttribute("href").slice(1)] = a; });
    if ("IntersectionObserver" in window) {
      var current = null;
      var seen = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (!en.isIntersecting) return;
          var a = links[en.target.id];
          if (!a) return;
          if (current) current.classList.remove("on");
          current = a; a.classList.add("on");
        });
      }, {rootMargin: "0px 0px -75% 0px"});
      [].forEach.call(document.querySelectorAll(".m-task"), function (t) { seen.observe(t); });
    }
  }

  // The front page: an id it doesn't have (an area or task from the app's links) is on a part page.
  function redirect() {
    var id = decodeURIComponent(location.hash.slice(1));
    if (!id || document.getElementById(id)) return false;
    var page = T5_AREAS[id.split("--")[0]];
    if (page) { location.replace(page + "#" + id); return true; }
    return false;
  }

  return {results: results, manualPage: manualPage, keysToggle: keysToggle, slashTo: slashTo, redirect: redirect};
})();
